(window.TNQ=window.TNQ||[]).push({"terms":{"시장지배적사업자":{"d":"일정한 거래분야에서 가격과 수량 등 거래조건을 좌우할 수 있는 시장지위를 가진 사업자이다.","r":["일정한 거래분야"]},"일정한 거래분야":{"d":"거래의 객체, 단계, 지역별로 경쟁관계가 있거나 성립될 수 있는 분야이다.","r":["시장지배적사업자"]},"사업자단체":{"d":"둘 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 연합체이다.","r":[]},"계열회사":{"d":"같은 기업집단에 속하는 회사들을 서로 상대방에 대하여 이르는 말이다.","r":["기업집단"]},"기업집단":{"d":"동일인이 사실상 사업내용을 지배하는 회사들의 집단이다.","r":["계열회사"]},"채무보증":{"d":"기업집단 소속 회사가 국내 금융기관의 여신과 관련해 국내 계열회사에 하는 보증이다.","r":["여신"]},"여신":{"d":"국내 금융기관이 하는 대출과 회사채무의 보증 또는 인수이다.","r":["채무보증"]},"순환출자":{"d":"셋 이상의 계열출자가 고리처럼 이어져 각 회사가 출자자이자 피출자가 되는 관계이다.","r":["계열출자"]},"계열출자":{"d":"기업집단 소속 회사가 계열회사의 주식을 취득하거나 소유하는 행위이다.","r":["순환출자"]},"지주회사":{"d":"주식 소유로 국내 회사의 사업내용을 지배하는 것이 주된 사업이며 자산총액이 일정 금액 이상인 회사이다.","r":[]},"재판매가격유지행위":{"d":"거래상대방과 그 다음 단계 사업자에게 판매가격을 정해 그대로 팔도록 구속하는 행위이다.","r":[]},"역외적용":{"d":"외국에서 이루어진 행위라도 국내 시장에 영향을 미치면 국내법을 적용하는 것이다.","r":[]},"관련매출액":{"d":"위반기간 동안 해당 거래분야에서 판매한 관련 상품과 용역의 매출액으로 과징금 산정의 기준이다.","r":[]},"공시대상기업집단":{"d":"자산총액이 일정 규모 이상으로 공정거래위원회가 지정하는 기업집단이다.","r":["상호출자제한기업집단"]},"상호출자제한기업집단":{"d":"공시대상기업집단 중 자산총액이 국내총생산액의 일정 비율 이상인 기업집단이다.","r":["공시대상기업집단"]},"기업결합":{"d":"주식 취득, 임원 겸임, 합병, 영업양수, 신설회사 참여로 기업이 결합하는 것이다.","r":[]},"특수관계인":{"d":"동일인과 그 친족 등 부당한 이익제공 금지의 대상이 되는 관계인이다.","r":[]},"입찰담합":{"d":"입찰에서 낙찰자나 입찰가격 등을 미리 합의하여 정하는 부당한 공동행위이다.","r":[]},"암묵의 요해":{"d":"명시적 약속 없이 서로 뜻이 통하는 묵시적 합의이다.","r":[]},"자진신고":{"d":"담합을 한 사업자가 스스로 신고해 시정조치와 과징금의 감면을 받는 제도이다.","r":[]},"동의의결":{"d":"사업자가 제시한 시정방안이 요건을 갖추면 위반 여부를 확정하지 않고 사건을 끝내는 제도이다.","r":["이행강제금"]},"이행강제금":{"d":"의무를 이행하지 않은 자에게 이행할 때까지 반복해 부과하는 금전적 제재이다.","r":["동의의결"]},"시정권고":{"d":"위반 행위가 있을 때 시정방안을 정해 따르도록 권하는 조치로 수락하면 시정조치가 내려진 것으로 본다.","r":[]},"전속고발":{"d":"공정거래위원회의 고발이 있어야만 검사가 공소를 제기할 수 있는 제도이다.","r":[]},"부당염매":{"d":"정당한 이유 없이 비용보다 현저히 낮은 가격으로 팔아 경쟁사업자를 배제할 우려가 있는 행위이다.","r":["부당고가매입"]},"부당고가매입":{"d":"통상 가격보다 높은 가격으로 사들여 경쟁사업자를 배제할 우려가 있는 행위이다.","r":["부당염매"]},"사원판매":{"d":"자기나 계열회사의 임직원에게 상품을 사거나 팔도록 강제하는 행위이다.","r":[]},"구속조건부거래":{"d":"거래상대방의 사업활동을 부당하게 구속하는 조건을 붙여 거래하는 행위이다.","r":[]},"부당한 지원행위":{"d":"특수관계인이나 다른 회사에 자금, 자산, 인력을 상당히 유리한 조건이나 규모로 제공하는 행위이다.","r":[]},"약관":{"d":"한쪽 당사자가 여러 명의 상대방과 계약하려고 일정한 형식으로 미리 마련한 계약 내용이다.","r":["표준약관"]},"설명의무":{"d":"사업자가 약관의 중요한 내용을 고객이 이해할 수 있도록 설명하여야 하는 의무이다.","r":["약관"]},"작성자불이익 원칙":{"d":"약관의 뜻이 명백하지 않으면 작성한 사업자에게 불리하게, 고객에게 유리하게 해석하는 원칙이다.","r":["약관"]},"표준약관":{"d":"일정한 거래 분야에서 표준이 되도록 공정거래위원회가 심사하거나 제정하는 약관이다.","r":["약관"]},"집단분쟁조정":{"d":"같은 유형의 피해가 다수 고객에게 발생했을 때 한꺼번에 조정하는 절차이다.","r":[]},"비밀유지명령":{"d":"소송에서 알게 된 영업비밀을 소송 수행 외 목적으로 쓰거나 공개하지 못하도록 법원이 내리는 명령이다.","r":[]},"결손처분":{"d":"체납자에게 징수할 가능성이 없을 때 체납액의 징수를 포기하는 처분이다.","r":[]},"제척":{"d":"위원이 사건과 특별한 관계가 있어 법률상 당연히 직무에서 배제되는 것이다.","r":["기피","회피"]},"기피":{"d":"공정을 기대하기 어려운 사정이 있을 때 당사자가 위원을 직무에서 빼 달라고 신청하는 것이다.","r":["제척","회피"]},"회피":{"d":"위원이 스스로 사유가 있다고 보아 직무에서 물러나는 것이다.","r":["제척","기피"]},"서면실태조사":{"d":"공정한 거래질서 확립을 위해 서면으로 자료를 받아 실태를 조사하는 방법이다.","r":[]},"공정경쟁규약":{"d":"사업자와 사업자단체가 부당한 고객유인을 방지하려고 자율적으로 정하는 규약이다.","r":[]}},"notes":{"'거래상 실질적 역할이 없는 특수관계인을 매개로 한 거래'는 제47조가 아니라 불공정거래행위 중 부당한 지원행위(제45조 제1항 제9호 나목)다":"실질적 역할 없는 특수관계인을 끼운 거래는 사익편취 조항이 아니라 불공정거래행위 중 부당한 지원행위로 다룹니다.","'다른 사업자'에는 시장지배적사업자의 경쟁사업자뿐 아니라 거래상대방, 판매대리점 등 전·후방관계 사업자도 포함된다":"방해 대상이 되는 다른 사업자는 경쟁사만이 아니라 거래상대방과 대리점 같은 전후방 사업자까지 포함합니다.","'다른 사업자로 하여금 부당한 공동행위를 하도록 하는 행위'는 금지된다":"담합에 직접 참여하지 않아도 다른 사업자에게 부당한 공동행위를 하게 하는 것 자체가 금지됩니다.","'법위반 사실의 공표'는 규정에 없다":"조문에 있는 것은 시정명령을 받은 사실의 공표이고 법위반 사실의 공표는 규정에 없습니다.","'시장 또는 산업의 동향과 공정경쟁에 관한 조사 및 분석'은 공정거래위원회 소관 사무가 아니라 한국공정거래조정원의 업무다":"시장과 산업 동향 및 공정경쟁에 관한 조사와 분석은 공정거래위원회가 아니라 한국공정거래조정원이 맡습니다.","'체납자가 국외로 이주하여 해외 소재지가 확인된 경우'는 사유로 규정되어 있지 않다":"체납자가 외국으로 이주해 소재지가 확인된 경우는 결손처분 사유로 조문에 정해져 있지 않습니다.","(2021 기출 당시) 품질동일성을 쉽게 식별할 수 있는 상품으로 공정거래위원회가 지정한 상품은 재판매가격유지행위가 허용되었다":"과거에는 품질 동일성을 쉽게 식별하는 지정상품에 대해 재판매가격유지가 허용되었던 제도가 있었습니다.","(간주가 아님) ① 고객에게 부당하게 불리한 조항, ② 고객이 계약의 거래형태 등 모든 사정에 비추어 예상하기 어려운 조항, ③ 계약의 목적을 달성할 수 없을 정도로 계약에 따르는 본질적 권리를 제한하는 조항":"고객에게 부당하게 불리한 조항과 예상하기 어려운 조항, 본질적 권리를 제한하는 조항은 공정성을 잃은 것으로 추정됩니다.","2년 이하의 징역 또는 200만원 이하의 벌금":"비밀엄수의무를 어긴 경우의 형사처벌은 이 년 이하 징역 또는 이백만 원 이하 벌금입니다.","2년 이하의 징역 또는 2천만원 이하의 벌금":"비밀유지명령을 어기면 이 년 이하 징역 또는 이천만 원 이하 벌금에 처합니다.","3년 이하의 징역 또는 2억원 이하의 벌금":"남용행위를 한 자에 대한 형사 처벌은 삼 년 이하 징역 또는 이억 원 이하 벌금입니다.","40%여도 합계 요건에 못 미치면 추정되지 않을 수 있다":"점유율이 높아도 상위 세 곳 합계가 사분의 삼에 미치지 못하면 추정되지 않을 수 있습니다.","4급 이상 공무원 경력자, 판사·검사·변호사 7년 이상, 법률·경제·경영·소비자 분야 전공 부교수 이상으로 7년 이상 근무한 사람, 기업경영·소비자보호·분쟁조정 활동 7년 이상 종사자":"공무원, 법조인, 교수, 기업이나 분쟁조정 활동 경력이 위원이 될 수 있는 자격 부류로 정해집니다.","50%, 20%인 사업자와 함께 추정된다(합계 80%)":"십 퍼센트 사업자는 오십 퍼센트와 이십 퍼센트 사업자와 합쳐 팔십 퍼센트라 함께 추정됩니다.","A 35%(70억원), B 25%(50억원), C 15%(30억원), D 10%(20억원), E 5%, D가 A의 계열회사이면 A·D는 한 사업자(45%, 90억원)":"D가 A의 계열회사면 둘을 합산해 점유율 사십오 퍼센트, 매출 구십억 원의 한 사업자가 됩니다.","A 50%, B 20%, C 10%, D 9%, E 5%, 모두 매출액 80억원 이상이면 추정되는 자는 A, B, C":"A가 오십 퍼센트라 추정되고 상위 셋 합계도 팔십 퍼센트이므로 A, B, C가 추정되며 D는 십 퍼센트 미만입니다.","A 55%, B 20%, C 10%, D 7%, E 5%, B와 E가 계열회사이면 B·E는 합쳐 25%인 한 사업자":"계열회사인 B와 E를 합산하면 한 사업자로서 점유율이 이십오 퍼센트가 됩니다.","① 고객에게 약관의 내용을 밝히지 않거나 사본을 내주지 않은 자, ② 약관의 중요한 내용을 설명하지 않은 자, ③ 표준약관과 다르게 정한 주요 내용을 고객이 알기 쉽게 표시하지 않은 자":"약관 내용을 밝히지 않거나 설명하지 않거나 달라진 주요 내용을 표시하지 않으면 오백만 원 이하 과태료입니다.","① 고의 또는 손해 발생의 우려를 인식한 정도, ② 위반행위로 인한 피해 규모, ③ 위반행위로 취득한 경제적 이익, ④ 위반행위에 따른 벌금 및 과징금, ⑤ 위반행위의 기간·횟수 등, ⑥ 사업자의 재산상태, ⑦ 사업자·사업자단체의 피해구제 노력의 정도":"배상액을 정할 때 고의 정도, 피해 규모, 얻은 이익, 벌금과 과징금, 기간, 재산 상태, 피해구제 노력을 따집니다.","① 기초 사실관계의 현저한 변경 등으로 시정방안이 적정하지 않게 된 경우, ② 불완전·부정확한 정보 제공 또는 거짓·부정한 방법으로 받은 경우, ③ 정당한 이유 없이 이행하지 않는 경우":"사정이 크게 바뀌었거나 거짓 정보로 받았거나 이행하지 않으면 동의의결을 취소할 수 있습니다.","① 분할납부 결정된 과징금을 기한까지 납부하지 않은 경우, ② 담보 변경·보전 명령 불이행, ③ 강제집행·경매 개시·파산선고·법인 해산·체납처분 등으로 징수 불가능하다고 인정되는 경우, ④ 사유가 해소되어 일시 납부할 수 있다고 인정되는 경우":"분할납부를 못 지키거나 담보 명령을 어기거나 징수가 불가능하거나 사유가 사라지면 결정을 취소하고 일시 징수할 수 있습니다.","① 소비자단체등의 요청이 있는 경우, ② 일정 거래 분야에서 여러 고객에게 피해가 발생하거나 우려되어 조사한 결과 약관이 없거나 불공정약관조항이 있는 경우, ③ 법률의 제정·개정·폐지 등으로 약관을 정비할 필요가 발생한 경우":"소비자단체 요청이 있거나 조사에서 약관 부재나 불공정 조항이 확인되거나 법 개정으로 정비가 필요하면 심사청구를 권고할 수 있습니다.","① 시정권고·시정명령을 하기 위해 필요한 경우, ② 약관 심사청구를 받은 경우":"약관 조사는 시정권고나 시정명령이 필요하거나 심사청구를 받은 경우에 합니다.","① 약관 조항과 관련하여 법률상 이익이 있는 자, ② 소비자기본법 제29조에 따라 등록된 소비자단체, ③ 소비자기본법 제33조에 따라 설립된 한국소비자원, ④ 사업자단체":"심사청구는 법률상 이익이 있는 자와 등록된 소비자단체, 한국소비자원, 사업자단체가 할 수 있습니다.","① 위반으로 판단될 경우 예상되는 시정조치 및 그 밖의 제재와 균형을 이룰 것, ② 경쟁질서·거래질서를 회복시키거나 소비자·다른 사업자 등을 보호하기에 적절할 것":"시정방안은 예상 제재와 균형을 이루고 경쟁질서와 소비자 보호에 적절해야 한다는 두 요건을 충족해야 합니다.","① 위반행위의 내용 및 정도, ② 위반행위의 기간 및 횟수, ③ 위반행위로 취득한 이익의 규모 등":"과징금을 매길 때 위반의 내용과 정도, 기간과 횟수, 얻은 이익의 규모 등을 고려합니다.","① 자기·배우자(였던 사람)가 당사자이거나 공동권리자·공동의무자인 사건, ② 자기가 당사자와 친족이거나 친족이었던 사건, ③ 자기 또는 자기가 속한 법인이 당사자의 법률·경영 등에 대한 자문·고문인 사건, ④ 증언·감정을 한 사건, ⑤ 당사자의 대리인으로 관여했거나 관여했던 사건, ⑥ 대상 처분·부작위에 관여한 사건, ⑦ 공정거래위원회 소속 공무원으로서 해당 사건을 조사·심사한 사건":"당사자나 친족이거나 자문, 증언, 대리, 처분 관여, 조사 경력이 있는 사건에서는 위원이 직무에서 배제됩니다.","① 재해 또는 도난 등으로 재산에 현저한 손실이 생긴 경우, ② 사업여건 악화로 사업이 중대한 위기에 처한 경우, ③ 일시납부로 자금사정에 현저한 어려움이 예상되는 경우, ④ 이에 준하는 사유":"재해나 도난, 사업 위기, 자금사정 곤란, 이에 준하는 사유가 있을 때 납부를 미루거나 나누어 낼 수 있습니다.","① 표준약관과 다른 내용을 약관으로 사용하면서 표준약관 표지를 사용한 자, ② 제20조 제1항 조사를 거부·방해·기피한 사업자 또는 사업자단체":"표준약관 표지를 부당하게 쓴 자와 조사를 거부하거나 방해한 사업자 또는 단체는 오천만 원 이하 과태료입니다.","① 해당 행위가 제40조 제1항(부당한 공동행위) 위반, ② 제129조 제2항 고발요건 해당, ③ 동의의결 전에 신청인이 신청을 취소":"담합이거나 고발 요건에 해당하거나 신청인이 취소했다면 동의의결 없이 정식으로 심의합니다.","가격뿐 아니라 수량, 품질, 그 밖의 거래조건을 결정할 수 있는 시장지위도 해당한다":"가격만이 아니라 수량과 품질 같은 다른 거래조건을 정할 수 있는 지위도 시장지배력에 해당합니다.","가격을 '유지'하는 합의도 가격을 결정·유지·변경하는 행위(제1호)에 해당한다":"가격을 올리거나 내리는 합의뿐 아니라 현재 가격을 유지하자는 합의도 같은 유형입니다.","가격을 결정·유지 또는 변경하는 행위":"가격담합으로 가격을 정하거나 현재 가격을 지키거나 바꾸기로 합의하는 행위입니다.","가격을 올린 경우에도 다른 상위 사업자와 합쳐 셋 이하 합계 75% 이상이면 추정될 수 있다":"점유율이 삼십 퍼센트인 일위 사업자도 다른 상위 사업자와 합쳐 합계 요건을 채우면 추정될 수 있습니다.","가격의 부당한 결정·유지·변경, 상품 판매·용역 제공의 부당한 조절, 다른 사업자의 사업활동 부당 방해, 새로운 경쟁사업자의 참가 부당 방해, 부당한 경쟁사업자 배제 거래 또는 소비자 이익을 현저히 해칠 우려가 있는 행위":"시장지배적 지위 남용행위는 가격, 출고조절, 사업활동 방해, 참가 방해, 경쟁사업자 배제와 소비자 이익 침해의 다섯 유형입니다.","가격의 인하는 시장지배적지위 남용에서만 명시된 시정조치다":"가격 인하 명령은 다른 위반 유형에는 없고 시장지배적지위 남용에서만 명시된 시정조치입니다.","가산금 징수 기간은 60개월 상한":"가산금을 물리는 기간은 최대 육십 개월까지로 제한됩니다.","가지급금·대여금·인력·부동산·유가증권·상품·용역·무체재산권 등을 제공하거나 상당히 유리한 조건으로 거래, 또는 거래상 실질적 역할이 없는 특수관계인·다른 회사를 매개로 거래":"자금과 인력, 자산을 제공하거나 유리한 조건으로 거래하거나 실질적 역할 없는 회사를 끼우는 것이 지원 수단입니다.","각 조합원이 평등한 의결권을 가질 것":"출자 규모와 관계없이 각 조합원이 평등한 의결권을 가져야 합니다.","각하 대상 사건(제27조 제1항 각 호)은 조정신청을 각하하여야 한다":"법이 열거한 신청 불가 사유에 해당하는 사건은 협의회가 반드시 각하해야 합니다.","각하하거나 종료하면 공정거래위원회에 사유와 관계 서류를 서면으로 지체 없이 보고하고 분쟁당사자에게 통보한다":"각하하거나 종료하면 사유와 서류를 서면으로 바로 공정거래위원회에 보고하고 당사자에게도 알립니다.","간접적 영향까지 모두 포함하지 않는다":"국내 시장에 닿는 영향이라도 간접적인 것까지 전부 포함해 역외적용하지는 않습니다.","감면받은 날부터 5년 이내에 다시 제40조 제1항을 위반하면 감경·면제를 하지 않는다":"감면받은 날로부터 오 년 안에 다시 담합을 하면 이번에는 감경이나 면제를 해 주지 않습니다.","감사와 지배인 등 영업 전반을 총괄하는 상업사용인은 임원에 포함된다":"감사는 물론 영업 전반을 총괄하는 지배인 같은 상업사용인도 임원으로 봅니다.","감정인 지정은 사건명, 감정인 성명, 감정의 목적 및 내용, 감정기간이 포함된 서면으로 한다":"감정인을 지정할 때는 사건명과 감정인, 목적과 내용, 기간을 담은 서면으로 합니다.","강제성 없는 희망가격 제시는 금지되지 않는다":"따르지 않아도 불이익이 없는 단순한 희망가격 제시는 금지 대상이 아닙니다.","같은 항 제3호 위반은 2년 이하의 징역 또는 1억5천만원 이하의 벌금":"구성사업자의 활동을 부당하게 제한한 경우의 형사처벌은 이 년 이하 징역 또는 일억오천만 원 이하 벌금입니다.","개별 교섭으로 정한 계약조항은 약관이 아니다":"개별 교섭을 거쳐 정한 조항은 일방이 미리 만든 약관의 성격을 잃어 약관법 대상에서 빠집니다.","개별 구성사업자와 구별되는 단체성·조직성을 갖추어야 한다":"구성 사업자 각각과 구분되는 조직으로서의 단체성이 있어야 사업자단체로 인정됩니다.","개별 사업자가 단체에 흡수되어 독자적 활동을 하지 않으면 사업자단체가 아니다":"사업자가 단체에 흡수되어 독자적 활동이 없으면 단체가 아니라 하나의 사업자로 봅니다.","거래가격을 정해 그 가격대로 판매하도록 구속조건을 붙여 거래하면 재판매가격유지행위다":"가격을 정하고 그대로 팔도록 구속하는 조건이 붙으면 재판매가격유지행위가 됩니다.","거래강제의 상대방은 원칙적으로 직접 거래의 상대방이다":"거래강제에서 강제당하는 상대방은 원칙적으로 직접 거래하는 상대입니다.","거래거절, 차별적 취급, 경쟁사업자 배제, 구속조건부거래는 아니다":"거래거절과 차별, 경쟁사업자 배제, 구속조건부거래는 공정경쟁규약의 대상이 아닙니다.","거래 또는 사업기회 제공의 상대방은 제1항 각 호에 해당할 우려가 있음에도 해당 거래를 하거나 사업기회를 제공받아서는 안 된다":"이익을 받는 쪽도 금지 행위에 해당할 우려가 있음을 알면 그 거래를 하거나 사업기회를 받으면 안 됩니다.","거래상대방에게 자기를 위해 금전·물품·용역, 그 밖의 경제상 이익을 제공하도록 강요":"거래상대방에게 자기를 위한 돈이나 물품, 용역 같은 이익을 내놓게 하는 이익제공강요입니다.","거래상대방에게 자기의 상품·용역을 공급하면서 정상적인 거래관행에 비추어 부당하게 다른 상품·용역을 자기 또는 자기가 지정하는 사업자로부터 구입하도록 하는 행위":"주된 상품을 팔면서 정상 관행을 넘어 다른 상품까지 사도록 강요하는 끼워팔기입니다.","거래상대방의 거래지역·거래상대방 구속(구속조건부거래), 기술의 부당이용(사업활동 방해), 부당한 자금지원(부당한 지원행위), 거래처이전 방해(사업활동 방해), 부당고가매입(경쟁사업자 배제), 부당한 이익에 의한 고객유인(부당한 고객유인), 사원판매(거래강제)":"이 행위들은 각각 다른 유형에 속하므로 거래상 지위의 남용 유형에서는 제외됩니다.","거래상대방의 임직원을 선임·해임할 때 자기의 지시 또는 승인을 얻게 하거나, 생산품목·시설규모·생산량·거래내용을 제한하여 경영활동을 간섭":"상대방의 임직원 인사에 지시나 승인을 요구하거나 생산과 거래 내용을 제한해 경영에 간섭하는 행위입니다.","거래상대방이 구입할 의사가 없는 상품·용역을 구입하도록 강제":"상대방이 사려는 뜻이 없는 상품이나 용역을 사게 만드는 구입강제입니다.","거래의 객체별·단계별 또는 지역별로 경쟁관계에 있거나 경쟁관계가 성립될 수 있는 분야":"일정한 거래분야는 상품, 거래 단계, 지역 기준으로 경쟁이 있거나 생길 수 있는 범위입니다.","거래의 상대방의 사업활동을 부당하게 구속하는 조건으로 거래하는 행위(구속조건부거래)":"일곱 번째는 상대방의 사업활동을 부당하게 구속하는 조건을 붙이는 구속조건부거래입니다.","거래주체나 계약유형에 관계없이 원칙적으로 모든 약관에 적용된다":"원칙적으로 누가 하는 거래이고 어떤 계약인지와 상관없이 모든 약관에 적용됩니다.","거래지역 또는 거래상대방을 제한하는 행위":"사업자끼리 영업 지역이나 거래 상대를 나누어 서로 경쟁하지 않기로 하는 합의입니다.","거래지역 또는 거래상대방의 제한은 남용행위가 아니라 불공정거래행위(구속조건부거래)다":"거래지역과 거래상대방을 제한하는 것은 지위 남용이 아니고 불공정거래행위 유형 중 하나로 다룹니다.","검찰총장·중대범죄수사청장은 고발요건에 해당하는 사실을 통보하고 고발을 요청할 수 있다":"수사기관의 장은 고발요건에 해당하는 사실을 알리고 공정거래위원회에 고발을 요청할 수 있습니다.","결손처분 시 지방행정기관 등에 체납자 행방·재산 유무를 조사·확인하여야 한다":"결손처분에 앞서 지방행정기관 등을 통해 체납자의 소재와 재산이 있는지 살펴 두어야 합니다.","결손처분 후 압류할 수 있는 다른 재산을 발견하면 지체 없이 결손처분을 취소하고 체납처분을 하여야 한다":"결손처분 뒤 압류할 수 있는 재산을 새로 찾으면 바로 결손처분을 취소하고 체납처분을 해야 합니다.","결원 시 보궐위원을 위촉하며 임기는 전임자의 남은 임기":"결원이 생기면 보궐위원을 위촉하고 그 임기는 전임자가 남긴 임기만큼입니다.","결원 시 보궐위원의 임기는 전임자의 남은 임기":"결원이 생겨 뽑는 보궐위원은 전임자의 남은 기간만 일합니다.","경기급변, 금융위기, 천재지변, 해킹·컴퓨터바이러스로 인한 전산시스템 장애 등 회사 외적 요인으로 인한 사업상 긴급한 필요에 따른 불가피한 거래":"경기 급변이나 천재지변, 전산 장애처럼 회사 밖 요인에 따른 긴급한 필요가 있는 거래가 긴급성 예외입니다.","경쟁사업자가 실제로 배제되어야 하는 것은 아니다":"경쟁사업자가 실제로 시장에서 사라지지 않아도 부당염매로 규제할 수 있습니다.","경쟁사업자와 그 고객의 거래를 계약성립 저지, 계약불이행 유인 등으로 부당하게 방해해 고객을 자기와 거래하도록 유인":"경쟁사와 고객의 계약 성립을 막거나 불이행을 부추겨 고객을 자기 쪽으로 돌리는 행위입니다.","경쟁제한사항을 내용으로 하는 승인·처분을 한 경우에도 그 내용을 공정거래위원회에 통보하여야 한다":"이미 한 승인이나 처분에 경쟁제한사항이 있다면 그 내용도 공정거래위원회에 알려야 합니다.","경쟁제한적인 법령 및 행정처분의 협의·조정 등 경쟁촉진정책에 관한 사항":"경쟁을 제한하는 법령과 행정처분을 협의하고 조정하는 경쟁촉진정책이 소관 사무입니다.","경제의 민주화, 중소기업의 보호와 육성, 완전경쟁의 실현, 경제규제의 완화, 사회복지(사회복리) 증진, 적정한 소득의 분배, 정의로운 시장경제":"이 항목들은 법 목적 조문에 명시되어 있지 않아 목적으로 볼 수 없는 선택지입니다.","경제적 파급효과가 중대한 사항":"경제에 미치는 파급 효과가 큰 사항은 전원회의에서 다룹니다.","계속적 채권관계의 발생을 목적으로 하는 계약에서 존속기간을 부당하게 단기 또는 장기로 하거나 묵시적인 기간의 연장 또는 갱신이 가능하도록 정하여 고객에게 부당하게 불이익을 줄 우려가 있는 조항":"계속적 계약에서 기간을 부당하게 짧거나 길게 하거나 묵시 갱신이 되게 해 고객에게 불이익을 줄 우려가 있는 조항은 무효입니다.","계속하여 회사의 업무에 종사하는 사람으로서 임원 외의 사람":"종업원은 회사 일을 계속해서 하는 사람 가운데 임원이 아닌 사람을 말합니다.","계약당사자가 개별적인 교섭을 거쳐 기재한 위약금 조항":"당사자들이 따로 교섭해 정한 위약금 조항은 미리 마련한 것이 아니어서 약관이 아닙니다.","계약의 성질상 또는 목적상 취소·해제·해지가 불가능하거나 취소·해제·해지하면 고객에게 현저한 재산상 손해가 발생하는 경우":"계약을 되돌리기 어렵거나 되돌리면 고객이 큰 재산상 손해를 입는 경우도 시정명령 사유입니다.","계약의 성질상 설명하는 것이 현저하게 곤란한 경우에는 설명의무가 면제된다":"계약의 성질상 설명이 현저히 곤란한 경우에는 사업자의 설명의무가 면제됩니다.","계약의 한쪽 당사자로서 사업자로부터 약관을 계약의 내용으로 할 것을 제안받은 자":"약관법의 고객은 사업자에게서 약관을 계약 내용으로 하자고 제안받는 쪽입니다.","계약의 한쪽 당사자로서 상대 당사자에게 약관을 계약의 내용으로 할 것을 제안하는 자":"약관법의 사업자는 약관을 계약 내용으로 삼자고 제안하는 쪽입니다.","계약이 무효가 되거나 사업자가 계약을 취소할 수 있는 것이 아니다":"의무 위반의 효과는 계약 무효나 취소가 아니라 해당 약관을 계약 내용으로 주장할 수 없다는 것입니다.","계약 체결 경위 등을 고려해 고객별로 달리 해석하지 않는다":"계약을 맺은 경위나 개별 고객의 사정에 따라 약관을 달리 해석하지 않습니다.","계열출자는 기업집단 소속 회사가 계열회사의 주식을 취득·소유하는 행위":"집단에 속한 회사가 다른 계열회사의 주식을 취득하거나 가지고 있는 것이 계열출자입니다.","계열회사 합산해 한 사업자로 묶기, 상위 3개 사업자 합계 75% 이상인지 확인, 10% 미만 사업자 제외, 사업자별 매출액·구매액 요건 확인":"계열 합산, 상위 세 곳 합계 확인, 십 퍼센트 미만 제외, 매출액 요건 점검의 순서로 계산합니다.","고객과 사업자 간에 분쟁해결이나 피해보상에 관한 합의가 이루어진 사건":"이미 분쟁 해결이나 피해 보상을 합의한 사건은 조정할 필요가 없어 신청이 받아들여지지 않습니다.","고객에게 '부당하게 과중한' 지연 손해금 등의 손해배상 의무를 부담시키는 약관 조항은 무효다":"고객에게 부당하게 과중한 지연 손해금 등을 부담시키는 조항이 무효이며 정도가 문제가 됩니다.","고객에게 법에 없는 해제권을 부여하는 조항은 무효사유가 아니다":"고객에게 법에 없는 해제권을 주는 것은 고객에게 불리하지 않아 무효 사유가 아닙니다.","고객에게 부당하게 불리한 소송 제기 금지 조항 또는 재판관할의 합의 조항은 무효":"소송을 아예 못 하게 하거나 먼 법원만 쓰게 하는 식으로 고객에게 부당하게 불리하면 그 조항은 무효입니다.","고객에게 주어진 기한의 이익을 '상당한 이유 없이' 박탈하는 조항":"고객이 누리는 기한의 이익을 상당한 이유 없이 빼앗는 조항은 무효입니다.","고객에 따라 다르게 해석되어서는 안 된다(객관적·획일적 해석)":"같은 약관은 고객마다 다르게 읽지 않고 누구에게나 똑같이 해석하는 객관적이고 획일적인 해석입니다.","고객의 대리인에 의해 계약이 체결된 경우 고객이 의무를 이행하지 않으면 대리인에게 그 의무의 전부 또는 일부를 이행할 책임을 지우는 약관 조항은 무효":"대리인이 계약했다는 이유로 고객이 의무를 안 지키면 대리인이 책임지도록 하는 약관 조항은 무효입니다.","고객의 의사표시의 형식이나 요건에 대하여 부당하게 엄격한 제한을 두는 조항":"고객이 의사표시를 할 때의 형식이나 요건을 부당하게 엄격하게 정한 조항은 무효입니다.","고객의 이익에 중대한 영향을 미치는 사업자의 의사표시가 상당한 이유 없이 고객에게 도달된 것으로 보는 조항":"고객의 이익에 중대한 영향을 주는 사업자의 의사표시를 상당한 이유 없이 도달한 것으로 간주하는 조항은 무효입니다.","고객의 이익에 중대한 영향을 미치는 사업자의 의사표시 기한을 부당하게 길게 정하거나 불확정하게 정하는 조항":"사업자가 의사표시를 해야 하는 기한을 부당하게 길게 하거나 불확정하게 하는 조항은 무효입니다.","고객이 요구할 경우 약관의 사본을 내주어 약관의 내용을 알 수 있게 하여야 한다":"고객이 요구하면 약관 사본을 주어 내용을 알 수 있게 하는 것이 교부의무입니다.","고객이 제3자와 계약을 체결하는 것을 '부당하게' 제한하는 조항":"고객이 제삼자와 계약하는 것을 부당하게 제한하는 조항은 무효입니다.","고의·과실 없음을 입증하면 면책":"손해배상 책임에서 사업자가 고의나 과실이 없음을 입증하면 책임을 면합니다.","고의 또는 과실이 없음을 입증하면 면책된다":"사업자가 자기에게 고의나 과실이 없었음을 입증하면 손해배상 책임을 면합니다.","골프용품 수입·판매회사가 도매가·권장소비자가를 표시한 가격표를 대리점에 배부하고 영업사원이 최저판매가를 구술 통지하면서 위반 시 거래정지 등 불이익을 준 행위는 재판매가격유지행위다":"최저판매가를 통지하고 어기면 거래정지 같은 불이익을 준 것은 구속조건이 있어 재판매가격유지행위입니다.","공공사업자의 전기·가스 공급규정":"공공사업자가 다수 고객에게 일률적으로 적용하는 전기와 가스 공급규정은 약관에 해당합니다.","공급자뿐 아니라 수요자(용역시장의 수요자 포함)도 시장지배적사업자가 될 수 있다":"파는 쪽만이 아니라 사는 쪽도 거래조건을 좌우할 힘이 있으면 시장지배적사업자입니다.","공동주택지 판매에서 비인기토지를 매입하지 않고서는 인기토지를 사실상 살 수 없게 한 행위는 거래강제에 해당한다":"인기 토지를 사려면 비인기 토지를 함께 사야 하도록 한 판매 방식은 거래강제에 해당합니다.","공동행위대표사업자를 선정해 신청서 제출":"인가를 신청할 때는 공동행위대표사업자를 정해 이 사업자가 신청서를 냅니다.","공시대상기업집단 소속 국내 회사가 특수관계인(국외 계열회사 제외)을 상대방으로 하거나 위해 대통령령이 정하는 규모 이상의 자금·유가증권·자산 거래 등을 하려면 미리 이사회 의결을 거쳐 공시하여야 한다":"일정 규모 이상의 특수관계인 거래는 사전에 이사회 의결을 거치고 공시해야 하는 대규모내부거래 규제입니다.","공시대상기업집단 중 자산총액이 국내총생산액의 1천분의 5 이상인 기업집단":"상호출자제한기업집단은 공시대상 집단 가운데 자산총액이 국내총생산액의 천분의 오 이상인 집단입니다.","공정거래법 제66조에 따른 질서유지 명령을 따르지 않은 자":"공정거래법에 따른 질서유지 명령을 따르지 않은 사람에게는 백만 원 이하의 과태료를 부과합니다.","공정거래위원회, 고객 또는 사업자":"집단분쟁조정을 의뢰하거나 신청할 수 있는 주체는 공정거래위원회와 고객 또는 사업자입니다.","공정거래위원회가 고발요건에 해당하지 않는다고 결정해도 감사원장, 중소벤처기업부장관, 조달청장은 사회적 파급효과, 국가재정 영향, 중소기업 피해 정도 등을 이유로 고발을 요청할 수 있다":"공정거래위원회가 고발 대상이 아니라고 정해도 감사원장과 중소벤처기업부장관, 조달청장은 파급효과 등을 이유로 고발을 요청할 수 있습니다.","공정거래위원회가 관계 행정기관의 장에게 경쟁 도입 등 시장구조 개선에 관한 의견을 제시할 수 있다":"공정거래위원회는 다른 행정기관에 경쟁 도입 같은 시장구조 개선 의견을 낼 수 있습니다.","공정거래위원회가 사실관계 조사를 마친 후 시정방안이 요건을 갖췄다고 판단하면 심의 절차를 중단하고 시정방안과 같은 취지로 의결할 수 있다":"조사를 마친 뒤 시정방안이 요건을 갖추면 심의를 중단하고 그 방안대로 의결해 사건을 끝낼 수 있습니다.","공정거래위원회가 시장지배적사업자에게 명할 수 있는 시정조치: 가격의 인하, 해당 행위의 중지, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치":"시장지배적사업자에게는 가격 인하와 행위 중지, 시정명령 사실의 공표 등을 명할 수 있습니다.","공정거래위원회가 자료의 열람·복사 요구를 거부해 당사자가 소를 제기하면 시효 진행이 정지되고 재판이 확정된 때부터 진행한다":"열람과 복사 요구를 거부당해 소송을 내면 시효가 멈추고 재판이 확정되면 다시 진행합니다.","공정거래위원회가 지정·통지한 날부터 제21조~제30조 및 제47조를 적용한다":"집단 규제 조문은 공정거래위원회가 지정하고 통지한 날부터 적용합니다.","공정거래위원회가 직접 처리하는 것이 적합한 경우로 대통령령이 정하는 기준에 해당하는 행위":"공정거래위원회가 직접 처리하는 것이 적합하다고 시행령이 정한 행위는 분쟁조정을 각하합니다.","공정거래위원회 고발 없이는 공소 제기 불가":"담합은 공정거래위원회가 고발하지 않으면 검사가 공소를 제기할 수 없습니다.","공정거래위원회는 경쟁제한사항 시정 의견을 제시할 수 있다":"통보받은 경쟁제한사항에 대해 공정거래위원회는 이를 바로잡자는 의견을 낼 수 있습니다.","공정거래위원회는 공소가 제기된 후에는 고발을 취소할 수 없다":"공소가 제기된 뒤에는 공정거래위원회가 고발을 취소하는 것이 허용되지 않습니다.","공정거래위원회는 국가·지방자치단체·공공기관·지방공기업이 발주하는 입찰의 부당한 공동행위를 적발·방지하려고 중앙행정기관·지방자치단체·공공기관·지방공기업의 장에게 입찰 관련 자료의 제출과 협조를 요청할 수 있다":"공공 발주 입찰 담합을 막기 위해 공정거래위원회가 중앙행정기관과 발주기관에 입찰 자료 제출과 협조를 요청할 수 있습니다.","공정거래위원회는 금지행위를 예방하기 위해 필요하면 사업자단체가 준수하여야 할 지침을 제정·고시할 수 있다":"예방을 위해 필요하면 공정거래위원회가 사업자단체가 지킬 지침을 만들어 고시할 수 있습니다.","공정거래위원회는 독과점적 시장구조가 장기간 유지되는 상품·용역의 공급시장 또는 수요시장에 경쟁을 촉진하기 위한 시책을 수립·시행하여야 한다":"독과점 구조가 오래 이어지는 시장에는 공정거래위원회가 경쟁 촉진 시책을 세우고 시행할 의무가 있습니다.","공정거래위원회는 분쟁조정을 협의회에 의뢰할 수 있다":"신청 외에도 공정거래위원회가 분쟁조정을 협의회에 의뢰하는 방법이 있습니다.","공정거래위원회는 불공정거래행위를 예방하기 위해 필요하면 사업자가 준수하여야 할 지침을 제정·고시할 수 있다":"예방을 위해 필요하면 공정거래위원회는 사업자가 지킬 지침을 만들어 고시할 수 있습니다.","공정거래위원회는 사업자와 사업자단체에 제3항 업무에 필요한 자료의 제출을 요청할 수 있다":"공정거래위원회는 시장구조 개선 업무를 위해 사업자와 사업자단체에 자료 제출을 요청할 수 있습니다.","공정거래위원회는 시정조치 이행 여부를 점검하고 자료제출을 요구할 수 있으며 이행관리 업무를 조정원에 위탁할 수 있다":"시정조치가 지켜지는지 점검하고 자료를 요구할 수 있으며 이 업무를 조정원에 맡길 수 있습니다.","공정거래위원회는 신고일부터 30일 내 심사하며 90일 범위에서 연장할 수 있다":"공정거래위원회는 신고일부터 삼십 일 안에 심사하고 구십 일 범위에서 기간을 늘릴 수 있습니다.","공정거래위원회는 신속한 조치의 필요성, 소비자 피해의 직접 보상 필요성 등을 종합 고려해 절차 개시 여부를 결정한다(반드시 개시할 의무는 없다)":"신속한 조치와 소비자 피해 보상의 필요 등을 종합해 개시 여부를 정하며 반드시 개시해야 하는 것은 아닙니다.","공정거래위원회는 신청일부터 30일(공시기간 제외) 이내 결정하며 30일 이내 연장 가능":"공정거래위원회는 신청일부터 삼십 일 안에 결정하며 공시 기간을 빼고 삼십 일까지 늘릴 수 있습니다.","공정거래위원회는 심사 요청을 받은 날부터 60일 이내에 심사결과를 서면으로 요청인에게 통보하여야 한다 (90일이 아니다)":"심사 결과는 요청받은 날로부터 육십 일 안에 서면으로 알려야 하며 구십 일이 아닙니다.","공정거래위원회는 심사청구를 받은 날부터 특별한 사유가 없으면 60일 이내에 심사결과를 청구인에게 서면으로 통보하여야 한다":"특별한 사유가 없으면 심사청구를 받은 날부터 육십 일 안에 결과를 서면으로 청구인에게 알려야 합니다.","공정거래위원회는 심사하거나 제정·개정한 표준약관을 공시하고 사용을 '권장'할 수 있다":"심사하거나 제정한 표준약관은 공시하고 사용을 권장할 수 있으며 강제하는 것은 아닙니다.","공정거래위원회는 심의 전에 그 약관에 따라 거래한 사업자 또는 이해관계인에게 심사 대상이 되었다는 사실을 알려야 한다(서면으로, 회의 일시·장소 기재)":"심의 전에 그 약관으로 거래한 사업자나 이해관계인에게 심사 대상이 되었음을 서면으로 알려야 합니다.","공정거래위원회는 외국사업자들이 외국에서 한 가격담합에 시정명령과 과징금 납부명령을 내렸다":"외국에서 이뤄진 가격담합에도 공정거래위원회가 시정명령과 과징금 납부 명령을 내린 사례입니다.","공정거래위원회는 이 법 시행을 위해 필요하다고 인정할 때 관계 행정기관 등의 장의 의견을 들을 수 있고(들어야 하는 것이 아니다), 필요한 조사 의뢰·자료 요청, 시정조치 이행 확보를 위한 협조 의뢰를 할 수 있다":"의견 청취는 필요하다고 판단하면 할 수 있는 재량이며 의무가 아니고 조사 의뢰와 자료 요청도 할 수 있습니다.","공정거래위원회는 이 법에 따른 권한의 일부를 소속 기관의 장이나 시·도지사에게 위임하거나 다른 행정기관의 장에게 위탁할 수 있다":"권한 일부를 소속 기관이나 시도지사에게 위임하고 다른 행정기관에 위탁할 수 있습니다.","공정거래위원회는 이 법에 따른 사무를 독립적으로 수행하기 위하여 국무총리 소속으로 둔다":"공정거래위원회는 사무를 독립해서 수행하도록 국무총리 소속으로 두는 기관입니다.","공정거래위원회는 이 법에 위반된다고 심의·의결한 약관 조항의 목록을 인터넷 홈페이지에 공개하여야 한다":"법 위반으로 의결한 약관 조항의 목록은 인터넷 홈페이지에 공개해야 합니다.","공정거래위원회는 이 법을 위반하는 행위가 있는 경우 사업자 또는 사업자단체에 시정방안을 정해 따를 것을 권고할 수 있다":"위반 행위가 있을 때 공정거래위원회는 시정방안을 정해 따르라고 권고할 수 있습니다.","공정거래위원회는 이 법을 위반한 혐의가 있다고 인정할 때 직권으로 필요한 조사를 할 수 있다":"공정거래위원회는 신고가 없어도 위반 혐의가 있으면 직접 조사에 나설 수 있습니다.","공정거래위원회는 이행 여부를 점검하고 자료 제출을 요청할 수 있다":"공정거래위원회는 이행했는지 점검하고 필요하면 자료 제출을 요청할 수 있습니다.","공정거래위원회는 제80조 제2항에 따른 신고가 접수된 경우 협의회에 그 행위 또는 사건의 분쟁조정을 의뢰할 수 있다":"신고가 접수된 사건을 공정거래위원회가 직접 처리하지 않고 협의회에 분쟁조정으로 의뢰할 수 있습니다.","공정거래위원회는 타당하면 연기할 수 있다":"연기 신청의 사유가 타당하다고 판단되면 공정거래위원회가 기간을 미룰 수 있습니다.","공정거래위원회는 표준약관 표지를 정할 수 있고, 표준약관을 사용하는 사업자는 고시하는 바에 따라 표지를 사용할 수 있다":"공정거래위원회가 정한 표준약관 표지를 표준약관을 쓰는 사업자는 고시에 따라 쓸 수 있습니다.","공정거래위원회는 행정관청이 작성한 약관이나 다른 법률에 따라 행정관청의 인가를 받은 약관이 제6조~제14조에 해당된다고 인정하면 해당 행정관청에 그 사실을 통보하고 시정에 필요한 조치를 하도록 요청할 수 있다":"관청이 만들었거나 인가한 약관이 불공정하다고 판단되면 그 관청에 알리고 시정 조치를 하도록 요청합니다.","공정거래위원회로부터 조사 및 심의를 받는 사업자·사업자단체·임직원은 변호사 등 변호인으로 하여금 조사 및 심의에 참여하게 하거나 의견을 진술하게 할 수 있다":"조사와 심의를 받는 쪽은 변호인을 참여시키고 변호인이 의견을 진술하게 할 수 있습니다.","공정거래위원회 소관 법령이나 규칙·고시 등의 해석 적용에 관한 사항":"소관 법령과 규칙과 고시의 해석 적용에 관한 사항은 전원회의가 맡습니다.","공정거래위원회와 소속 공무원은 사건처리에 필요한 경우 등 대통령령으로 정하는 경우를 제외하고 자진신고자 관련 정보를 사건 처리와 관계없는 자에게 제공·누설할 수 없다":"공정거래위원회는 예외 사유가 아니면 자진신고자 정보를 사건과 무관한 사람에게 누설할 수 없습니다.","공정거래위원회 위원장은 위원이 직무 관련 비위, 직무태만, 품위손상 등으로 적합하지 않다고 인정하면 해임 또는 해촉할 수 있다(협의회 위원장의 권한이 아니다)":"비위나 직무태만 등이 있는 위원의 해임과 해촉은 협의회 위원장이 아니라 공정거래위원회 위원장이 합니다.","공정거래위원회 위원장의 심사를 거쳐 비영리 업무는 겸할 수 있다":"비영리 업무는 공정거래위원회 위원장의 심사를 거쳐 겸직이 가능합니다.","공정거래위원회 위원장의 심사를 거쳐 비영리 업무를 겸할 수 있다":"비영리 업무는 공정거래위원회 위원장의 심사를 거치면 겸할 수 있습니다.","공정거래위원회의 심의·의결에는 공정거래법 제64조~제68조를 준용한다":"약관법상 공정거래위원회의 심의와 의결에도 공정거래법의 해당 절차 규정을 준용합니다.","공정거래위원회의 조사나 심의를 받고 있는 사업자 또는 사업자단체":"동의의결은 조사나 심의를 받고 있는 사업자나 사업자단체가 신청할 수 있습니다.","공정거래위원회 회의에 출석한 자에게는 구두로 할 수 있다":"회의에 이미 출석한 사람에게는 제출 명령을 서면 대신 말로 할 수 있습니다.","공정경쟁규약으로 방지하는 불공정거래행위는 부당한 고객유인이다":"규약이 막으려는 행위 유형은 불공정거래행위 가운데 부당한 고객유인뿐입니다.","공정경쟁규약으로 방지하려는 대상은 부당한 고객유인이다":"공정경쟁규약이 겨냥하는 것은 여러 불공정거래행위 중 부당한 고객유인 하나입니다.","공정경쟁규약이 제1항 제4호(부당한 고객유인)를 위반하는지 심사를 요청할 수 있다":"규약을 만든 사업자나 단체는 그 규약이 부당한 고객유인 금지에 어긋나는지 공정거래위원회에 심사를 요청할 수 있습니다.","공정하고 자유로운 경쟁 촉진, 창의적인 기업활동 조성, 소비자 보호, 국민경제의 균형 있는 발전 도모":"법 목적 조문에 직접 적힌 항목들로 경쟁 촉진과 기업활동, 소비자, 국민경제가 들어 있습니다.","공행정관계에서는 사업자가 아니다":"공권력을 행사하는 행정 작용에서는 국가나 지자체가 사업자로 인정되지 않습니다.","과대한 이익 제공으로 경쟁사업자 고객을 유인하는 행위, 거래상 지위를 부당하게 이용한 거래, 거래상대방 사업활동을 부당하게 구속하는 조건 거래(불공정거래행위 유형), 경쟁사업자의 고객을 유인하는 행위":"고객 유인과 거래상 지위 이용, 구속 조건 거래는 공동행위가 아니라 불공정거래행위 유형입니다.","과점시장에서 선발업체가 독자적으로 가격을 정하고 후발업체가 일방적으로 모방하는 경우가 언제나 가격담합인 것은 아니다":"선발업체가 독자적으로 정한 가격을 후발업체가 따라 한 것만으로는 합의 없이 담합이라 단정하지 못합니다.","과징금 100분의 50 감경, 시정조치 감경 가능":"두 번째로 신고하거나 협조한 자는 과징금을 절반으로 줄이고 시정조치도 감경받을 수 있습니다.","과징금 금액이 대통령령 기준(관련 매출액의 100분의 1 또는 10억원)을 초과하고, 아래 사유로 전액 일시 납부가 어렵다고 인정될 때":"과징금이 시행령 기준을 넘고 일시 납부가 어렵다고 인정되는 사유가 있어야 연기와 분할납부를 신청할 수 있습니다.","과징금 납부를 통지받은 날부터 30일 이내에 공정거래위원회에 신청":"연기나 분할납부의 신청은 과징금 납부 통지를 받은 날부터 삼십 일 안에 해야 합니다.","과징금 면제, 시정조치 감경 또는 면제(최초 협조자 요건 동일)":"조사가 시작된 뒤 협조한 최초의 자는 과징금을 면제받고 시정조치도 줄이거나 면제받을 수 있습니다.","과징금 부과기준은 대통령령으로 정한다":"과징금을 얼마나 부과할지의 구체적 기준은 대통령령에 위임되어 있습니다.","과징금 산정 기준 매출액의 관련 상품·용역 범위는 합의 내용에 포함된 상품·용역의 종류와 성질, 거래지역, 거래상대방, 거래단계 등을 고려하여 개별적·구체적으로 판단한다":"과징금 기준이 되는 관련 매출액은 합의가 미친 상품과 지역 등을 개별 사건마다 구체적으로 따져 정합니다.","과징금 한도가 다른 불공정거래행위(4%·10억)와 다르다":"부당한 지원행위는 과징금 한도가 다른 불공정거래행위의 백분의 사와 십억 원보다 높습니다.","과태료는 대통령령으로 정하는 바에 따라 공정거래위원회가 부과·징수한다":"과태료는 시행령이 정한 바에 따라 공정거래위원회가 직접 부과하고 징수합니다.","관계 행정기관의 장은 경쟁제한사항을 내용으로 하는 법령을 제정·개정하거나 경쟁제한사항을 내용으로 하는 승인·처분을 하려면 미리 공정거래위원회와 협의하여야 한다":"경쟁을 제한하는 내용의 법령이나 승인과 처분을 하려면 미리 공정거래위원회와 협의해야 합니다.","관계 행정기관의 장이 경쟁제한사항을 내용으로 하는 예규·고시 등을 제정·개정하려면 미리 공정거래위원회에 통보하여야 한다":"예규와 고시에 경쟁제한사항이 있으면 협의가 아니라 미리 통보만 하면 됩니다.","관련매출액에 100분의 4를 곱한 금액 이하":"재판매가격유지 과징금의 상한은 관련매출액의 백분의 사입니다.","관련 상품의 외국 수입 가능성도 시장지배적지위 판단에서 고려된다":"외국 상품이 들어올 수 있다면 국내 사업자의 지배력이 약해지므로 이 점도 고려합니다.","관련시장이 넓게 획정될수록 사업자의 점유율이 낮아져 시장지배적지위를 가질 가능성이 낮아진다":"시장 범위를 넓게 잡으면 점유율 분모가 커져 지배적 지위로 인정될 가능성이 낮아집니다.","광역시 치과의사회와 치과기공사회가 실무협의회 소속 회원을 통해 치과기공물 가격 가이드라인을 정하고 대표자 추인을 받아 안내문을 발송한 행위는 사업자단체에 의한 가격결정행위다":"치과기공물 가격 가이드라인을 정해 안내문을 보낸 것은 사업자단체에 의한 가격결정행위로 판단되었습니다.","구매 관련 위반이면 매입액을 관련매출액으로 본다":"위반이 구매와 관련된 경우에는 매출액 대신 매입액을 관련매출액으로 취급합니다.","구성사업자(사업자단체의 구성원인 사업자)의 사업내용 또는 활동을 부당하게 제한하는 행위":"구성원 사업자의 사업 내용이나 활동을 부당하게 제한하는 것이 세 번째 금지행위입니다.","구성원이 그 의사결정에 따른 행위를 현실적으로 하였을 것을 요하지 않는다":"구성원이 그 결정대로 실제 행동했는지는 성립 요건이 아닙니다.","구속조건이 없으면 해당하지 않는다":"가격을 정해 주더라도 따르도록 구속하는 조건이 붙지 않았다면 이 행위에 해당하지 않습니다.","구입강제·이익제공강요·판매목표강제 외의 방법으로 거래상대방에게 불이익이 되도록 거래조건을 설정 또는 변경하거나 이행과정에서 불이익을 주는 행위":"앞의 세 유형 외의 방법으로 거래 조건을 불리하게 정하거나 이행 과정에서 불이익을 주는 불이익제공입니다.","국가가 사경제의 주체로서 거래행위를 하면 그 범위에서 사업자에 포함되어 이 법이 적용된다":"국가도 민간처럼 거래행위를 하는 범위에서는 사업자로서 이 법의 적용 대상입니다.","국가나 지방자치단체는 사경제의 주체로서 거래행위를 하는 범위에서만 사업자로 본다":"국가나 지자체는 민간처럼 사경제 주체로 거래하는 범위에서만 사업자로 취급합니다.","국내 금융기관이 하는 대출 및 회사채무의 보증 또는 인수":"여신은 국내 금융기관이 하는 대출과 회사 채무의 보증이나 인수를 가리킵니다.","국내·외 법인 여부, 사업자의 매출액 규모, 사업자의 재산상태(손해배상액 산정 고려사항과 구별)":"국내외 법인 여부와 매출액 규모, 재산 상태는 과징금 부과 때 고려사항으로 열거되어 있지 않습니다.","국외 금융기관은 포함하지 않는다":"여신의 주체는 국내 금융기관에 한정되어 외국 금융기관의 대출은 여신에서 빠집니다.","국외에서 이루어진 행위라도 국내 시장에 영향을 미치면 이 법이 적용된다":"국외라는 이유만으로 적용이 제외되지 않으며 국내 시장에 영향이 있으면 이 법이 적용됩니다.","국외에서 이루어진 행위라도 그 행위가 국내 시장에 영향을 미치는 경우에는 이 법을 적용한다":"행위지가 외국이어도 국내 시장에 영향이 미치면 우리 법을 적용하는 것이 역외적용입니다.","국외에 주소·영업소가 있는 사업자는 국내에 대리인을 지정하게 하여 송달한다":"외국에 주소가 있는 사업자에게는 국내 대리인을 지정하게 하여 그를 통해 송달합니다.","국제적으로 통용되는 부동산업은 해당하지 않는다":"부동산업은 국제적으로 통용되더라도 적용 제한 업종에 들어 있지 않습니다.","국제적으로 통용되는 약관 등 특별한 사정이 있는 약관은 대통령령으로 정하는 경우 제7조~제14조 적용을 조항별·업종별로 제한할 수 있다":"국제 통용 약관 같은 특별한 사정이 있는 약관은 시행령에 따라 개별 불공정 조항 규정의 적용을 제한할 수 있습니다.","국제적으로 통용되는 약관이나 특별한 사정이 있는 약관으로서 대통령령으로 정하는 경우 제7조~제14조 적용을 조항별·업종별로 제한할 수 있다":"국제 통용 약관 등은 시행령이 정한 경우 불공정 조항 규정의 적용을 조항별과 업종별로 제한할 수 있습니다.","권고를 받은 날부터 4개월 이내에 필요한 조치를 하지 않으면 거래 당사자 및 소비자단체등의 의견을 듣고 관계 부처 협의를 거쳐 공정거래위원회가 표준약관을 제정 또는 개정할 수 있다":"권고 후 사 개월 안에 조치가 없으면 의견을 듣고 부처 협의를 거쳐 공정거래위원회가 직접 표준약관을 만들 수 있습니다.","권고를 받은 사업자는 15일 이내에 수락 여부를 알려야 한다":"보상계획서 제출 권고를 받은 사업자는 십오 일 안에 수락할지를 알려야 합니다.","권고를 받은 자는 통지받은 날부터 10일 이내에 수락 여부를 공정거래위원회에 통지하여야 한다":"권고를 받은 자는 통지받은 날부터 십 일 안에 수락할지를 공정거래위원회에 알려야 합니다.","권고를 수락하면 이 법에 따른 시정조치가 명하여진 것으로 본다":"권고를 수락하면 그 내용대로 시정조치가 내려진 것과 같은 효력이 생깁니다.","권장소비자가격 통보나 판매가격 인상요청에 실효성을 확보할 수 있는 수단이 부수되어 있지 않으면 재판매가격유지행위에 해당하지 않는다":"권장가격을 알리거나 인상을 요청해도 지키게 할 실효적 수단이 없다면 재판매가격유지행위가 아닙니다.","규제의 요청에 비해 외국 법률 등을 존중해야 할 요청이 현저히 우월한지도 역외적용에서 고려 대상이다":"외국 법을 존중해야 할 필요가 규제 필요보다 현저히 크다면 역외적용에서 이를 참작합니다.","규칙 또는 고시의 제정 또는 변경":"규칙이나 고시를 새로 만들거나 바꾸는 일은 전원회의의 관장 사항입니다.","그 밖에 전원회의에서 스스로 처리하는 것이 필요하다고 인정하는 사항":"전원회의가 스스로 처리할 필요가 있다고 인정하는 사항도 전원회의가 맡습니다.","그 밖의 상임위원은 고위공무원단 소속 일반직공무원으로서 임기제공무원이다":"다른 상임위원은 고위공무원단 소속 일반직 공무원이며 임기가 정해진 임기제입니다.","그 밖의 위원은 위원장의 제청으로 대통령이 임명하거나 위촉한다":"나머지 위원은 위원장이 제청하고 대통령이 임명하거나 위촉합니다.","그 밖의 행위로서 공정한 거래를 해칠 우려가 있는 행위":"열 번째는 앞의 유형에 들지 않으나 공정한 거래를 해칠 우려가 있는 포괄적 유형입니다.","그 밖의 행위로서 다른 사업자(행위자 포함)의 사업활동 또는 사업내용을 방해·제한하거나, 가격·생산량 등 대통령령으로 정하는 정보를 주고받아 일정한 거래분야에서 경쟁을 실질적으로 제한하는 행위":"사업활동을 방해하거나 정보를 주고받아 경쟁을 실질적으로 제한하는 행위도 공동행위의 마지막 유형입니다.","그 표현은 거래조건 합리화 요건이다":"소비자 편익 증진에 명백히 기여해야 한다는 요건은 연구개발이 아니라 거래조건 합리화에 해당합니다.","금고 이상의 형 선고, 장기간의 심신쇠약으로 직무수행 불능인 경우를 제외하고 의사에 반해 면직·해촉되지 않는다":"금고 이상의 형을 받거나 직무 수행이 불가능한 경우가 아니면 본인 뜻에 반해 면직되지 않습니다.","금액기준으로 산정하기 어려우면 물량기준 또는 생산능력기준으로 산정할 수 있다":"금액으로 계산하기 어려우면 판매량이나 생산능력 기준으로 점유율을 계산해도 됩니다.","금융감독원, 중소벤처기업부, 한국공정거래조정원, 소비자기본법에 따라 등록되지 않은 소비자단체, 사실상 이익만 있는 자":"금융감독원과 중소벤처기업부, 조정원, 등록하지 않은 소비자단체, 사실상 이익만 있는 자는 청구할 수 없습니다.","금융업과 보험업은 명시·교부의무 면제 업종이 아니다":"금융업과 보험업은 면제 업종에 들어 있지 않아 명시와 교부의무를 이행해야 합니다.","금지청구(제108조)는 제45조 위반에 대한 것이며 제46조는 해당 조문에 없다":"법원에 하는 금지청구는 불공정거래행위에 대한 것이고 재판매가격유지는 그 조문에 포함되지 않습니다.","금지청구의 소는 민사소송법상 관할 지방법원 외에 그 지방법원 소재지를 관할하는 고등법원이 있는 곳의 지방법원에도 제기할 수 있다":"금지청구 소송은 통상 관할 법원 외에 그 소재지를 관할하는 고등법원 소재지의 지방법원에도 낼 수 있습니다.","기업결합 신고는 기업결합일부터 30일 이내":"일반적인 기업결합 신고는 결합일로부터 삼십 일 안에 사후에 합니다.","기업결합의 제한 및 경제력 집중의 억제에 관한 사항":"기업결합 제한과 경제력집중 억제도 공정거래위원회의 소관 사무입니다.","기업의 효율성 증대, 보안성, 긴급성 등 거래 목적을 달성하기 위해 불가피한 거래는 제47조 제1항 제4호를 적용하지 않는다":"효율성과 보안성, 긴급성 때문에 불가피한 거래는 합리적 고려 없는 상당한 규모 거래 금지에서 빠집니다.","기업집단에 속하는 회사가 국내 금융기관(은행, 산업은행, 수출입은행, 중소기업은행, 보험회사, 투자매매업자·투자중개업자·종합금융회사, 그 밖에 대통령령이 정하는 금융기관)의 여신과 관련하여 국내 계열회사에 하는 보증":"채무보증은 집단 소속 회사가 국내 금융기관의 여신과 관련해 국내 계열회사를 위해 서 주는 보증입니다.","기한의 이익을 부여하는 조항은 무효사유가 아니다":"고객에게 기한의 이익을 새로 주는 조항은 고객에게 유리하여 무효 사유가 아닙니다.","기획재정부장관은 포함되지 않는다":"고발을 요청할 수 있는 기관 중에는 기획재정부장관이 들어 있지 않습니다.","긴급하거나 부득이한 사정이 있으면 전화 또는 구두로 신고할 수 있다":"원칙은 서면 신고이나 긴급하거나 부득이한 경우 전화나 구두로도 신고할 수 있습니다.","남용행위, 탈법행위, 의결권 행사 위반, 지주회사 규정 위반, 상호출자·순환출자 위반, 채무보증 위반, 부당한 공동행위, 부당한 지원행위(제45조 제1항 제9호)·특수관계인 이익제공, 보복조치, 사업자단체의 제51조 제1항 제1호 위반, 폭언·폭행 등으로 조사를 거부·방해·기피한 자":"남용과 담합, 상호출자와 순환출자와 채무보증 위반, 부당한 지원, 보복조치, 조사 방해 등이 가장 무거운 벌칙 대상입니다.","남용행위를 한 회사가 합병으로 소멸한 경우 합병 후 존속하거나 합병으로 설립된 회사의 행위로 보아 시정조치를 명할 수 있다":"남용행위를 한 회사가 합병으로 없어졌다면 존속회사나 신설회사의 행위로 보아 시정조치를 명할 수 있습니다.","남용행위 위반은 공정거래위원회의 고발이 있어야 공소를 제기할 수 있다":"남용행위는 공정거래위원회가 고발해야 검사가 공소를 제기할 수 있는 전속고발 대상입니다.","남용행위의 유형 및 기준은 대통령령으로 정한다":"남용행위의 구체적 유형과 판단 기준은 법이 아닌 대통령령에 위임되어 있습니다.","납부기한 다음 날부터 납부한 날까지 연 100분의 40의 범위에서 은행 연체이자율을 고려해 징수":"기한 다음 날부터 납부일까지 은행 연체이자율을 고려해 연 백분의 사십 범위에서 가산금을 징수합니다.","납부기한 연기는 납부기한 다음 날부터 2년을 초과할 수 없다":"납부기한을 미루는 기간은 기한 다음 날부터 이 년을 넘길 수 없습니다.","노동조합의 쟁의행위에는 이 법이 적용되지 않는다":"노동조합이 하는 쟁의행위는 노동법 영역이어서 이 법이 적용되지 않습니다.","농업, 어업 등 제1차 산업을 하는 자도 사업자에 해당할 수 있다":"농업과 어업 같은 제1차 산업 종사자도 사업을 하는 한 사업자에 포함될 수 있습니다.","누구든 동의의결을 받은 사실을 들어 위반을 주장할 수 없다":"동의의결이 있었다는 사정을 근거로 위반이 있었다고 주장하지 못합니다.","누구든지 이 법에 위반되는 사실을 공정거래위원회에 신고할 수 있다":"위반 사실의 신고는 누구든 할 수 있고 자격이 제한되지 않습니다.","다른 법령에서 공정거래위원회의 소관으로 규정한 사항":"이 법 외에 다른 법령이 공정거래위원회 소관으로 정한 사항도 소관 사무에 포함됩니다.","다른 사업자에게 의사에 반해 참여하도록 강요하거나 중단하지 못하도록 강요한 경우, 일정 기간 반복적으로 부당한 공동행위를 한 경우":"담합 참여나 중단을 강요했거나 반복적으로 한 자는 자진신고를 해도 감면받지 못합니다.","다른 사업자의 거래처 이전을 부당하게 방해하여 사업활동을 심히 곤란하게 할 정도로 방해":"다른 사업자가 거래처를 옮기지 못하도록 부당하게 막아 사업활동을 심히 곤란하게 하는 행위입니다.","다른 사업자의 공동행위를 단순히 방조하는 행위는 여기에 포함되지 않는다":"남이 담합하는 것을 그저 돕는 정도의 방조는 하도록 하는 행위에 들어가지 않습니다.","다른 사업자의 기술을 부당하게 이용하여 사업활동을 상당히 곤란하게 할 정도로 방해":"다른 사업자의 기술을 부당하게 쓰는 방법으로 상당히 곤란하게 할 정도로 방해하는 행위입니다.","다른 사업자의 인력을 부당하게 유인·채용하여 사업활동을 상당히 곤란하게 할 정도로 방해":"다른 사업자의 인력을 부당하게 빼 와서 사업활동이 상당히 곤란해질 정도로 방해하는 행위입니다.","다만 불공정거래행위 또는 부당하게 경쟁을 제한하여 가격을 인상하게 되는 경우에는 적용한다":"조합의 행위라도 불공정거래행위이거나 경쟁을 부당하게 제한해 가격을 올리면 이 법이 적용됩니다.","다만 사업자 또는 사업자단체의 사업상 비밀을 보호할 필요가 있다고 인정할 때에는 공개하지 않는다":"심리는 공개가 원칙이지만 사업상 비밀을 보호할 필요가 있으면 공개하지 않을 수 있습니다.","다만 상당한 기한 내에 의사표시를 하지 않으면 의제된다는 뜻을 명확하게 따로 고지한 경우나 부득이한 사유로 고지할 수 없는 경우는 제외(유효)":"상당한 기한 안에 의사표시가 없으면 의제된다고 명확히 따로 알렸거나 고지가 불가능한 경우는 유효합니다.","다만 소멸시효 완성(제2호)으로 결손처분한 경우에는 취소하지 않는다":"시효가 완성되어 결손처분한 경우에는 더 이상 징수할 수 없어 새 재산을 찾아도 취소하지 않습니다.","다만 시정조치 등 처분을 받은 후 신청한 경우는 제외":"이미 시정조치 등 처분을 받은 뒤에 신청한 경우에는 각하 사유에서 빠집니다.","다만 신청이 취하되거나 각하된 경우에는 없다":"신청을 취하하거나 각하되었다면 시효중단 효력은 인정되지 않습니다.","다만 유효한 부분만으로는 계약의 목적 달성이 불가능하거나 유효한 부분이 한쪽 당사자에게 부당하게 불리한 경우에는 그 계약이 무효가 된다":"남은 부분만으로 목적을 이룰 수 없거나 한쪽에 부당하게 불리하면 계약 전체가 무효가 됩니다.","다만 정당한 이유가 있는 경우와 출판된 저작물인 경우에는 허용된다":"예외적으로 정당한 이유가 있는 경우와 출판된 저작물의 경우에는 재판매가격유지가 허용됩니다.","다만 조사공무원 또는 당사자의 신청에 대해 전원회의 또는 소회의가 필요하다고 인정하면 할 수 있다":"조사공무원이나 당사자가 신청하고 전원회의나 소회의가 필요하다고 인정하면 예외적으로 가능합니다.","다수의 고객이 공동으로 신청하면 3명 이내의 대표자를 선임할 수 있다":"여러 고객이 함께 신청하면 세 명 이내의 대표자를 뽑을 수 있습니다.","다음 거래단계 상대방은 포함되지 않는다":"거래강제의 상대방에는 직접 거래상대방의 다음 거래단계에 있는 사업자가 포함되지 않습니다.","단독으로 시장지배적지위가 없는 사업자도 다른 사업자와 함께 시장지배적사업자가 될 수 있다":"혼자서는 지배력이 없어도 다른 사업자와 합쳐서 지배적 지위를 갖는 공동 지배가 가능합니다.","단독으로 증거를 제공한 최초의 자일 것, 공정거래위원회가 정보를 입수하지 못했거나 충분한 증거를 확보하지 못한 상태일 것, 사실을 모두 진술하고 끝까지 협조할 것, 부당한 공동행위를 중단할 것":"조사 개시 전 전부 면제는 최초 단독 증거제공자로서 증거가 부족한 상태에서 끝까지 협조하고 담합을 중단해야 받습니다.","단순 과실로 인한 책임 배제는 제7조 제1호 대상이 아니다":"가벼운 과실에 대한 책임을 배제한 조항은 이 호가 정한 무효 사유에 포함되지 않습니다.","담합 참가 회사들이 순차적으로 합의 파기 의사를 대외적으로 표시하고 탈퇴해 1개 회사만 남으면 담합은 종료된다":"참가 회사들이 차례로 합의 파기 의사를 표시하고 빠져 한 곳만 남으면 담합이 끝난 것으로 봅니다.","당사자는 위원에게 심의·의결의 공정을 기대하기 어려운 사정이 있으면 기피신청을 할 수 있다":"공정을 기대하기 어려운 사정이 있다면 당사자가 해당 위원을 사건에서 빼 달라고 기피신청을 할 수 있습니다.","당사자는 회의에 출석해 의견을 진술하거나 자료를 제출할 수 있다":"당사자는 회의에 나와 말로 의견을 밝히거나 자료를 내어 방어할 수 있습니다.","당사자 또는 신고인 등은 처분 관련 자료의 열람·복사를 요구할 수 있다":"당사자와 신고인은 처분과 관련된 자료를 열람하거나 복사해 달라고 요구할 수 있습니다.","당사자·이해관계인·참고인의 출석 및 의견 청취, 감정인 지정 및 감정 위촉, 사업자·사업자단체·임직원에게 원가·경영상황 보고와 자료·물건 제출 명령 또는 일시 보관":"출석과 의견 청취, 감정인 지정, 원가나 경영상황 보고와 자료 제출 명령 및 일시 보관이 세 가지 조사 처분입니다.","당사회사 점유율 합계가 시장지배적사업자 추정요건에 해당하고, 1위이며, 2위와의 차이가 합계의 25% 이상":"당사회사 합계가 지배적사업자 추정 요건에 해당하고 일위이며 이위와 격차가 합계의 사분의 일 이상이면 경쟁제한으로 추정합니다.","대규모회사가 당사회사인 일정 기업결합은 계약 체결일 등부터 기업결합일 전까지 신고하고 심사결과 통지 전에는 이행행위를 하지 못한다":"대규모회사가 당사회사인 일정 결합은 사전에 신고하고 심사 결과 통지 전에는 이행행위를 할 수 없습니다.","대리점에 전기면도기 등 품목을 인터넷 오픈마켓에 공급하는 것을 금지하고 어기면 공급가격 인상 등을 한 행위는 구속조건부거래다":"대리점에 특정 품목을 인터넷 오픈마켓에 공급하지 못하게 하고 어기면 불이익을 준 행위가 구속조건부거래입니다.","대법원은 서울특별시가 전동차 제작납품·구매계약의 주체인 경우 사업자성을 인정했다":"서울특별시가 전동차를 발주하는 계약 당사자로 나선 경우에는 거래 주체로서 사업자라고 판단했습니다.","대법원은 흑연전극봉 제조·판매 외국사업자들의 국외 부당한 공동행위에 역외적용을 인정했다":"외국 사업자들이 국외에서 한 흑연전극봉 담합에 대해 우리 법의 역외적용을 인정한 판례입니다.","대상은 제17조를 위반한 약관 또는 이와 법률상 쟁점이 공통되는 약관과 관련된 분쟁이다":"조정 대상은 불공정약관 사용 금지를 위반한 약관이나 법률상 쟁점이 같은 약관에 관한 분쟁입니다.","대통령령 사항은 낙찰·경락 비율, 설계·시공 방법, 그 밖에 입찰·경매의 경쟁 요소":"시행령이 정한 사항은 낙찰 비율과 설계 시공 방법 등 입찰에서 경쟁이 이루어지는 요소들입니다.","대통령령으로 정하는 공공기관의 장은 입찰공고나 낙찰자 결정 시 입찰 관련 정보를 공정거래위원회에 제출하여야 한다":"시행령이 정한 공공기관은 입찰공고나 낙찰자 결정 때 입찰 정보를 공정거래위원회에 제출할 의무가 있습니다.","대통령령으로 정하는 매출액(관련매출액)에 100분의 6을 곱한 금액을 초과하지 않는 범위":"남용행위 과징금의 상한은 관련매출액에 백분의 육을 곱한 금액입니다.","대통령령으로 정하는 매출액에 100분의 20을 곱한 금액 이하":"부당한 공동행위의 과징금 상한은 관련 매출액에 백분의 이십을 곱한 금액입니다.","대표자, 대리인, 사용인, 종업원이 제32조 위반을 하면 행위자를 벌하는 외에 법인 또는 개인에게도 벌금형":"대표자나 종업원이 위반하면 행위자와 더불어 법인이나 개인도 벌금형으로 처벌하는 양벌규정입니다.","대표자가 분쟁조정 신청 철회, 조정안 수락·거부를 하려면 다른 신청인의 서면 동의를 받아야 한다":"대표자가 신청을 철회하거나 조정안을 수락하거나 거부하려면 다른 신청인의 서면 동의가 있어야 합니다.","대한법무사협회가 소속 법무사의 집단등기사건 수임을 제한하는 규정을 제정·시행한 행위는 구성사업자의 사업내용·활동을 부당하게 제한하는 행위(제3호)다":"소속 법무사의 집단등기사건 수임을 제한한 규정은 구성사업자 활동을 부당하게 제한하는 행위입니다.","대한의사협회가 의약분업정책에 항의해 일제 휴업을 결의·시행한 행위, 대한약사회가 소속 약국의 집단 휴업을 결의·시행한 행위도 제3호에 해당한다":"의사와 약사 단체가 소속 회원의 집단 휴업을 결의하고 시행한 것도 구성사업자 활동 제한에 해당합니다.","대한의사협회는 사업자단체에 해당한다":"전문직 사업자인 의사들의 이익을 위한 대한의사협회는 사업자단체로 판단됩니다.","독립된 사업자들이 각자 책임과 계산으로 사업하고 손익분배 등을 함께 하지 않으면 하나의 사업자로 볼 수 없다":"각자 책임과 계산으로 사업하고 손익을 나누지 않는 독립 사업자들은 하나의 사업자로 묶이지 않습니다.","독점규제·공정거래 또는 소비자분야에 경험·전문지식이 있는 사람으로서 2급 이상 공무원 경력자, 판사·검사·변호사 15년 이상, 법률·경제·경영·소비자 분야 전공 부교수 이상으로 15년 이상 근무한 사람, 기업경영·소비자보호활동 15년 이상 종사자":"위원은 독점규제와 소비자 분야 전문성이 있고 고위 공무원, 법조인, 교수, 기업이나 소비자 활동 경력이 있어야 합니다.","독촉 후에도 납부하지 않으면 국세체납처분의 예에 따라 징수할 수 있다":"독촉해도 내지 않으면 국세 체납과 같은 방식으로 강제로 징수할 수 있습니다.","동의의결 시 시정방안을 이행하지 않으면 제92조에 따라 이행강제금이 부과·징수될 수 있다는 사실을 서면으로 알려야 한다(구두 아님)":"동의의결을 할 때 불이행 시 이행강제금이 부과될 수 있다는 점을 반드시 서면으로 알려야 합니다.","동의의결은 해당 행위가 이 법에 위반된다고 인정한 것을 의미하지 않는다":"동의의결을 받았다는 사실이 위반을 인정한 것으로 해석되지 않습니다.","동의의결을 신청해도 진행이 정지된다":"동의의결을 신청한 기간에도 시효의 진행이 정지됩니다.","동의의결 이행계획의 이행 여부 점검과 이행 관련 자료 제출요청 업무는 한국공정거래조정원에 위탁한다":"이행 여부 점검과 관련 자료 요청 업무는 한국공정거래조정원에 위탁하여 처리하게 합니다.","동의의결 전 30일 이상 기간을 정해 해당 행위의 개요, 관련 법령 조항, 시정방안, 이해를 돕는 정보를 신고인 등 이해관계인에게 통지하거나 관보·홈페이지에 공고해 의견을 제출할 기회를 준다":"의결 전에 삼십 일 이상의 기간으로 이해관계인에게 행위 개요와 시정방안을 알리고 의견을 낼 기회를 줍니다.","동의의결·취소는 전원회의 또는 소회의의 심의·의결을 거친다":"동의의결과 그 취소는 전원회의나 소회의의 심의와 의결을 거쳐 결정합니다.","동일인이 단독으로 또는 다른 특수관계인과 합하여 발행주식총수의 100분의 20 이상을 소유한 국내 계열회사":"동일인이 혼자 또는 특수관계인과 합쳐 주식 오분의 일 이상을 가진 계열회사도 거래 상대방으로 규제됩니다.","동일인이 대통령령으로 정하는 기준에 따라 사실상 그 사업내용을 지배하는 회사의 집단":"기업집단은 동일인이 시행령 기준에 따라 사실상 경영을 지배하는 회사들의 묶음입니다.","동일인이 자연인인 공시대상기업집단에 속하는 국내 회사":"사익편취 금지의 주체는 동일인이 자연인인 공시대상기업집단 소속의 국내 회사입니다.","동일인이 회사이면 동일인과 지배하는 하나 이상의 회사, 회사가 아니면 지배하는 둘 이상의 회사":"동일인이 회사라면 그 회사와 지배받는 회사 한 곳 이상, 사람이라면 지배받는 회사 두 곳 이상이 집단입니다.","동종·유사 사건 소송 진행 중이면 협의회가 결정으로 조정절차를 중지할 수 있다":"같은 종류나 비슷한 사건의 소송이 진행 중이면 협의회는 결정으로 조정절차를 중지할 수 있습니다.","둘 이상의 사업자로 구성된다":"사업자가 한 곳뿐인 모임은 단체라 할 수 없어 최소한 두 사업자 이상이 모여야 합니다.","둘 이상의 회사가 같은 거래상대방과 거래하면 각 회사 거래금액을 합산한다":"같은 상대와 거래한 여러 회사의 금액은 합산해서 상당한 규모 여부를 계산합니다.","둘 이상의 회사가 동일한 기업집단에 속하는 경우 이들 각각의 회사를 서로 상대방의 계열회사라 한다":"같은 기업집단에 속한 회사들은 서로에게 계열회사가 되는 상대적 관계입니다.","따르지 않으면 100만원 이하의 과태료":"질서유지 조치를 따르지 않은 사람에게는 백만 원 이하의 과태료를 부과합니다.","또는 대규모회사가 중소기업 점유율 3분의 2 이상인 분야에서 5% 이상 점유하게 되는 경우":"중소기업 점유율이 삼분의 이 이상인 분야에서 대규모회사가 오 퍼센트 이상 차지하게 되는 경우도 추정 사유입니다.","매출액 100분의 20, 매출액 없으면 40억원":"부당한 공동행위의 과징금 상한은 매출액의 백분의 이십이고 매출이 없으면 사십억 원입니다.","매출액 100분의 4, 매출액 없으면 10억원":"지원행위를 뺀 불공정거래행위와 재판매가격유지, 보복조치는 매출액의 백분의 사 또는 십억 원이 상한입니다.","매출액 100분의 6, 매출액 없으면 20억원":"시장지배적지위 남용의 과징금 상한은 매출액의 백분의 육이고 매출이 없으면 이십억 원입니다.","매출액이 없거나 산정이 곤란하면 20억원을 초과하지 않는 범위":"매출액이 없거나 계산하기 어려운 경우 과징금은 이십억 원을 넘지 않는 범위에서 부과합니다.","매출액이 없는 경우 등은 10억원 이하":"관련매출액이 없는 경우의 과징금은 십억 원 이하입니다.","매출액이 없는 경우 등은 40억원 이하":"평균매출액을 계산할 수 없는 경우의 과징금 상한은 사십억 원입니다.","면제 업종의 약관도 사업자는 영업소에 해당 약관을 비치하여 고객이 볼 수 있도록 하여야 한다":"면제 업종도 영업소에 약관을 갖춰 두어 고객이 볼 수 있게 해야 합니다.","명시·교부의무가 면제되는 업종: 여객운송업, 전기·가스 및 수도사업, 우편업, 공중전화 서비스 제공 통신업":"여객운송과 전기와 가스와 수도, 우편, 공중전화 통신업은 명시와 교부의무가 면제되는 업종입니다.","명시·교부의무 위반(고객에게 약관 내용을 밝히지 않거나 사본을 내주지 않음), 설명의무 위반은 각각 500만원 이하의 과태료":"명시와 교부의무 위반, 설명의무 위반에는 각각 오백만 원 이하의 과태료를 부과합니다.","명칭이나 형태 또는 범위에 상관없이 계약의 한쪽 당사자가 여러 명의 상대방과 계약을 체결하기 위하여 일정한 형식으로 미리 마련한 계약의 내용":"약관은 한쪽이 다수의 상대방과 계약하려고 일정한 형식으로 미리 만들어 둔 계약 내용입니다.","목적 달성에 필요한 정도를 초과하는 경우, 수요자·관련 사업자의 이익을 부당하게 침해할 우려가 있는 경우, 참가사업자 간 내용에 부당한 차별이 있는 경우, 참가·탈퇴를 부당하게 제한하는 경우":"목적을 넘거나 수요자 이익을 침해하거나 참가자를 차별하거나 참가와 탈퇴를 제한하면 인가를 받을 수 없습니다.","목적은 경쟁제한상태 등의 자발적 해소, 소비자 피해구제, 거래질서 개선":"동의의결의 목적은 경쟁제한 상태를 스스로 풀고 소비자 피해를 구제하며 거래질서를 개선하는 것입니다.","무체재산권 제공도 부당한 지원행위(제9호)에 해당한다":"특허권 같은 무체재산권을 제공하는 것도 부당한 지원행위의 수단이 됩니다.","무혐의 처분은 헌법소원의 대상이 될 수 있다":"공정거래위원회의 무혐의 처분은 헌법소원으로 다툴 수 있는 공권력의 행사로 볼 수 있습니다.","문서 송달은 행정절차법 제14조~제16조를 준용한다":"문서를 송달하는 방법은 행정절차법의 송달 규정을 준용합니다.","발행주식총수의 100분의 20(상장법인은 100분의 15) 이상 소유":"주식 취득 신고 대상은 발행주식의 오분의 일 이상, 상장법인은 백분의 십오 이상을 소유하게 되는 경우입니다.","법률에 따른 고객의 항변권, 상계권 등의 권리를 '상당한 이유 없이' 배제하거나 제한하는 조항":"고객이 법률상 갖는 항변권과 상계권을 상당한 이유 없이 막는 조항은 무효입니다.","법률에 따른 고객의 해제권 또는 해지권을 배제하거나 그 행사를 제한하는 조항":"법률이 고객에게 준 해제권이나 해지권을 없애거나 행사를 제한하는 조항은 무효입니다.","법률에 따른 사업자의 해제권 또는 해지권의 행사 요건을 완화하여 고객에게 부당하게 불이익을 줄 우려가 있는 조항":"사업자의 해제권이나 해지권 행사 요건을 완화해 고객에게 불이익을 줄 우려가 있는 조항은 무효입니다.","법원에 소가 제기되어 조정절차를 진행할 실익이 없는 경우는 조정절차를 종료한다(출제 기준)":"소가 제기되어 조정을 계속할 실익이 없다면 조정절차를 종료합니다.","법원에 소를 제기한 사건은 각하 사유로 규정되어 있지 않다":"법원에 소를 낸 사건이라는 사정은 약관 분쟁조정의 각하 사유로 정해져 있지 않습니다.","법원은 금지청구의 소가 제기되면 피고의 이익을 보호하기 위해 필요하다고 인정하는 때 피고의 신청이나 직권으로 원고에게 상당한 담보 제공을 명할 수 있다":"피고 이익을 보호할 필요가 있으면 법원은 원고에게 상당한 담보를 제공하라고 명할 수 있습니다.","법원은 손해배상소송에서 당사자가 보유한 영업비밀에 대해 신청이 있으면 결정으로 상대방 당사자, 소송대리인 등에게 소송 수행 외 목적 사용·공개를 금지하는 비밀유지명령을 내릴 수 있다":"영업비밀을 보호하기 위해 법원은 신청을 받아 소송 수행 외 목적의 사용과 공개를 금지하는 비밀유지명령을 낼 수 있습니다.","법원은 제40조 제1항, 제45조 제1항(제9호 제외), 제51조 제1항 제1호 위반 손해배상소송에서 당사자 신청으로 상대방에게 손해 증명·손해액 산정에 필요한 자료(자진신고 관련 자료 제외) 제출을 명할 수 있다":"법원은 당사자가 신청하면 손해를 증명하는 데 필요한 자료를 상대방이 내도록 명할 수 있으나 자진신고 자료는 제외합니다.","법원 판결로 처분이 취소되어 판결이유에 따라 새로운 처분을 하는 경우에는 시효 제한을 적용하지 않는다":"법원 판결로 취소된 처분을 판결 이유에 맞춰 다시 하는 경우에는 시효 제한이 적용되지 않습니다.","법위반 내용, 권고사항, 시정기한, 수락여부 통지기한, 수락거부시의 조치":"권고서에는 위반 내용과 권고 사항, 시정과 통지 기한, 거부 때의 조치를 적습니다.","법인의 대표자, 법인 또는 개인의 대리인·사용인·종업원이 업무에 관해 제124조~제126조 위반을 하면 행위자를 벌하는 외에 법인 또는 개인에게도 벌금형을 과한다":"종업원 등이 업무와 관련해 위반하면 행위자뿐 아니라 법인이나 개인에게도 벌금형을 과하는 양벌규정입니다.","변호사·의사 같은 전문인이 하는 사업에는 이 법이 적용된다":"전문직이라도 사업을 하는 이상 이 법의 적용 대상에서 제외되지 않습니다.","별표 2 제9호 유형은 자금지원, 자산·상품 등 지원, 인력지원, 거래단계 추가 등 4가지다":"부당한 지원행위는 자금, 자산과 상품, 인력 지원과 거래단계 추가의 네 가지로 열거됩니다.","보관할 때는 보관조서를 작성·발급하고, 조사와 관련 없거나 보관할 필요가 없어지면 즉시 반환한다":"일시 보관 때는 보관조서를 쓰고 발급하며 필요가 없어지면 바로 돌려줍니다.","보복조치는 과징금 4%·10억 대상이다":"보복조치를 한 자에게는 매출액의 백분의 사, 매출이 없으면 십억 원 한도의 과징금이 적용됩니다.","보완 기간은 60일 기간에 산입하지 않는다":"보완에 걸린 기간은 조정 처리 기한인 육십 일에 넣지 않고 제외합니다.","보험회사 약관은 해당하지 않는다":"이 통보와 권고 절차는 은행 약관에 대한 것이고 보험회사의 약관은 포함되지 않습니다.","부과 가능 사실은 서면으로 알린다":"이행강제금이 부과될 수 있다는 사실은 사전에 서면으로 알려야 합니다.","부과기준은 거래거절 등 다른 불공정거래행위(제45조 제1항 제9호 제외)와 같다":"과징금 부과 기준은 부당한 지원행위를 뺀 다른 불공정거래행위와 동일합니다.","부당고가매입은 경쟁사업자 배제 유형이다":"부당고가매입은 지원행위가 아니라 경쟁사업자 배제 유형에 들어갑니다.","부당염매와 부당고가매입은 경쟁사업자 배제 유형이다":"가격을 낮게 팔거나 높게 사는 두 행위는 모두 경쟁사업자 배제로 분류됩니다.","부당염매의 요건은 경쟁사업자를 배제시킬 '우려'다":"부당염매는 경쟁사업자를 배제할 우려가 있으면 성립하며 결과를 요건으로 하지 않습니다.","부당하게 거래를 거절하는 행위(거래거절)":"불공정거래행위의 첫 번째 유형은 정당한 이유 없이 거래를 끊거나 거절하는 거래거절입니다.","부당하게 거래상대방이 경쟁사업자와 거래하지 않을 것을 조건으로 그 거래상대방과 거래하는 행위":"경쟁사업자와 거래하지 않는다는 조건을 달아 거래하는 것도 경쟁사업자 배제에 해당합니다.","부당하게 거래상대방이 자기 또는 계열회사의 경쟁사업자와 거래하지 않는 조건으로 그 거래상대방과 거래하는 행위":"자기나 계열회사의 경쟁사업자와는 거래하지 않는 조건으로 거래하는 배타조건부거래입니다.","부당하게 거래의 상대방을 차별하여 취급하는 행위(차별적 취급)":"두 번째는 거래 상대방을 부당하게 차별하는 차별적 취급입니다.","부당하게 거래지역 또는 거래상대방에 따라 현저하게 유리하거나 불리한 가격으로 거래":"지역이나 상대방에 따라 가격을 크게 유리하거나 불리하게 하는 가격차별입니다.","부당하게 경쟁자를 배제하는 행위(경쟁사업자 배제)":"세 번째는 경쟁사업자를 부당하게 시장에서 몰아내는 행위입니다.","부당하게 경쟁자의 고객을 자기와 거래하도록 강제하는 행위(거래강제)":"다섯 번째는 경쟁자의 고객이 자기와 거래하도록 강제하는 거래강제입니다.","부당하게 경쟁자의 고객을 자기와 거래하도록 유인하는 행위(부당한 고객유인)":"네 번째는 경쟁자의 고객을 부당한 방법으로 자기와 거래하도록 끌어오는 고객유인입니다.","부당하게 다른 사업자의 사업활동을 방해하는 행위(사업활동 방해)":"여덟 번째는 다른 사업자의 사업활동을 부당하게 방해하는 행위입니다.","부당하게 상품·용역을 통상거래가격보다 높은 가격으로 구입하여 자기 또는 계열회사의 경쟁사업자를 배제시킬 우려가 있는 행위":"통상 가격보다 높게 사들여 경쟁사업자가 물건을 구하지 못하게 하는 부당고가매입입니다.","부당하게 자기 또는 계열회사의 임직원에게 자기 또는 계열회사의 상품·용역을 구입 또는 판매하도록 강제하는 행위":"자사나 계열회사 임직원에게 자사 상품을 사거나 팔도록 강제하는 사원판매입니다.","부당하게 통상거래가격에 비해 낮은 가격으로 공급하거나 높은 가격으로 구입하여 경쟁사업자를 배제시킬 우려가 있는 행위":"통상 가격보다 낮게 팔거나 높게 사들여 경쟁사업자를 몰아낼 우려가 있는 행위가 경쟁사업자 배제입니다.","부당하게 특수관계인 또는 다른 회사를 지원하는 행위(부당한 지원행위)":"아홉 번째는 특수관계인이나 다른 회사를 부당하게 지원하는 부당한 지원행위입니다.","부당하게 특정사업자에게 거래개시를 거절하거나 계속적 거래관계에 있는 특정사업자에게 거래를 중단하거나 수량·내용을 현저히 제한":"혼자서 특정 사업자에게 거래를 개시하지 않거나 끊거나 현저히 제한하는 그 밖의 거래거절입니다.","부당하게 특정사업자에게 수량·품질 등의 거래조건이나 거래내용을 현저하게 유리하거나 불리하게 취급":"가격이 아니라 수량과 품질 같은 거래조건을 특정 사업자에게 현저히 유리하거나 불리하게 다루는 차별입니다.","부당한 거래기회 제공은 부당한 지원행위 유형이 아니다":"거래기회를 제공하는 것은 지원행위 유형으로 열거되지 않았고 특수관계인 사익편취의 유형에 있습니다.","부당한 거래단계 추가는 부당한 지원행위다":"거래단계를 부당하게 끼워 넣는 것은 경쟁사업자 배제가 아니라 부당한 지원행위에 속합니다.","부당한 공동행위는 동의의결 대상에서 제외되어 심의 절차를 진행한다":"담합은 동의의결로 사건을 끝낼 수 없는 유형이라 통상의 심의 절차를 밟습니다.","부당한 공동행위로 손해를 입은 자에게 손해의 3배를 넘지 않는 범위에서 책임":"피해자에게는 손해의 삼 배를 넘지 않는 범위에서 배상하는 징벌적 성격의 책임을 집니다.","부당한 공동행위를 자진신고한 자, 증거제공 등으로 조사·심의·의결에 협조한 자(소속 전·현직 임직원 포함)":"자진신고한 자와 증거제공 등으로 조사에 협조한 자, 그 소속 전현직 임직원이 감면 대상입니다.","부당한 공동행위를 한 자 또는 하도록 한 자: 3년 이하의 징역 또는 2억원 이하의 벌금":"담합을 한 자와 하도록 한 자 모두 삼 년 이하 징역 또는 이억 원 이하 벌금에 처할 수 있습니다.","부당한 공동행위를 할 것을 약정하는 계약 등은 해당 사업자 간에는 무효다":"담합을 약정한 계약은 그 사업자들 사이에서 법적 효력이 없습니다.","부당한 공동행위 및 사업자단체의 경쟁제한행위 규제에 관한 사항":"담합과 사업자단체의 경쟁제한행위를 규제하는 사항이 소관 사무에 포함됩니다.","부당한 공동행위에 관한 심사의 기준은 공정거래위원회가 정하여 고시한다":"공동행위를 심사하는 구체적 기준은 법이 아니라 공정거래위원회 고시로 정합니다.","부당한 지원행위(제45조 제1항 제9호)의 과징금도 매출액의 100분의 10, 매출액이 없으면 40억원이다":"부당한 지원행위의 과징금 상한은 매출액의 백분의 십이며 매출이 없으면 사십억 원입니다.","부동산·유가증권·무체재산권 등 자산 또는 상품·용역을 상당히 낮거나 높은 대가로 또는 상당한 규모로 제공·거래":"자산이나 상품과 용역을 상당히 낮거나 높은 대가 또는 상당한 규모로 제공하는 부당한 자산 지원입니다.","부득이한 사정이 있으면 30일의 범위에서 결정으로 연장할 수 있다":"부득이한 사정이 있으면 재결기간을 결정으로 삼십 일 범위에서 늘릴 수 있습니다.","분과회의는 전체회의로부터 위임받은 사항을 심의·의결한다":"분과회의는 전체회의가 위임한 사항을 심의하고 의결합니다.","분과회의 의결은 협의회 의결로 보되 결과를 전체회의에 보고한다":"분과회의에서 의결해도 효력은 협의회 의결과 같고 다만 처리 결과는 전체회의에 알려야 합니다.","분쟁당사자(소비자기본법상 소비자 제외 고객, 사업자)는 회의에 출석하여 의견을 진술하거나 관계 자료를 제출할 수 있다":"분쟁당사자는 회의에 직접 출석해 말로 의견을 진술하거나 자료를 낼 수 있습니다.","분쟁당사자가 권고·조정안을 수락하거나 스스로 조정하는 등 조정이 성립된 경우":"권고나 조정안을 받아들이거나 스스로 조정하여 합의에 이르면 조정이 성립되어 절차가 끝납니다.","분쟁당사자가 권고·조정안을 수락하거나 스스로 조정하는 등 조정이 성립된 경우(종료하여야 한다)":"당사자가 권고나 조정안을 받아들이거나 스스로 조정해 성립되면 절차를 종료해야 합니다.","분쟁당사자가 조정절차 개시 전에 스스로 조정하고 조정조서 작성을 요청하면 조정조서를 작성한다":"절차를 시작하기 전에 당사자가 스스로 조정하고 요청하면 협의회가 조정조서를 만들어 줍니다.","분쟁당사자가 조정절차 개시 전에 스스로 조정하고 조정조서 작성을 요청하면 협의회는 조정조서를 작성하여야 한다":"당사자가 절차 개시 전에 스스로 합의하고 작성을 요청하면 협의회는 조정조서를 써 주어야 합니다.","분쟁당사자는 공정을 기하기 어려운 사정이 있으면 협의회에 기피신청을 할 수 있다":"공정을 기대하기 어려운 사정이 있으면 분쟁 당사자가 위원을 빼 달라고 기피신청을 할 수 있습니다.","분쟁당사자는 기피신청을 할 수 있고 위원은 회피할 수 있다":"당사자는 기피신청을 하고 위원은 스스로 회피할 수 있습니다.","분쟁당사자는 분쟁조정을 신청한 후 소를 제기하거나 중재·다른 조정을 신청하면 지체 없이 협의회에 알려야 한다":"신청 후에 소를 내거나 중재나 다른 조정을 신청했다면 바로 협의회에 알려야 합니다.","분쟁당사자는 합의된 사항의 이행결과를 공정거래위원회에 제출하여야 한다":"당사자는 합의한 사항을 이행한 결과를 공정거래위원회에 제출해야 합니다.","분쟁당사자 성명·주소, 조정 신청의 취지와 이유, 대리인, 소송사건번호(소가 제기된 경우)":"신청서에는 당사자와 신청의 취지와 이유, 대리인, 소가 제기된 경우 사건번호를 적습니다.","분쟁당사자 양쪽이 연장에 동의하면 90일이다 (30일이 아니다)":"양쪽이 연장에 동의하면 조정 기간은 구십 일까지이고 삼십 일이 아닙니다.","분쟁당사자의 어느 한쪽이 조정을 거부하는 등 조정절차를 진행할 실익이 없는 경우":"한쪽이 조정을 거부하는 등 계속할 실익이 없으면 조정절차를 종료합니다.","분쟁당사자의 일방이 조정을 거부하는 등 조정절차를 진행할 실익이 없는 경우":"당사자 한쪽이 조정을 거부하는 등 더 이어 갈 이유가 없으면 조정 절차를 종료합니다.","분쟁조정 신청 이전에 공정거래위원회가 조사 중인 사건":"신청 전에 이미 공정거래위원회가 조사 중인 사건은 분쟁조정을 신청할 수 없습니다.","분쟁조정 신청 전후로 소가 제기되어 진행 중이면 수소법원은 조정이 있을 때까지 소송절차를 중지할 수 있다":"소송이 진행 중이면 수소법원은 조정이 끝날 때까지 소송 절차를 중지할 수 있습니다.","분쟁조정의 신청은 시효중단의 효력이 있다":"분쟁조정을 신청하면 소멸시효의 진행이 멈추는 중단 효과가 있습니다.","분쟁조정 종료서에는 당사자 현황, 분쟁 경위, 조정의 쟁점, 각하·종료 사유(조정 성립 시 결과)를 적는다":"종료서에는 당사자 현황과 분쟁 경위, 쟁점, 각하나 종료 사유를 적으며 조정이 성립했다면 그 결과를 적습니다.","분할납부 기한 간격은 6개월 이하, 분할 횟수는 6회 이하":"나누어 낼 때 납부 간격은 육 개월 이하이고 횟수도 여섯 번 이하로 제한됩니다.","분할로 해산되는 경우에는 설립되는 회사 등이 연대 책임":"분할로 원래 회사가 해산되면 새로 설립되는 회사 등이 연대하여 책임을 집니다.","분할·분할합병되는 경우(부과일에 분할·분할합병되는 경우 포함) 과징금은 분할되는 회사, 분할로 설립되는 회사, 분할되는 회사의 일부를 합병하여 존속하는 회사가 연대하여 납부할 책임을 진다":"분할되는 경우 관련 회사들은 과징금을 함께 연대하여 납부할 책임을 집니다.","분할일(분할합병일) 이전의 남용행위를 분할되는 회사, 분할로 설립되는 새로운 회사, 분할되는 회사의 일부를 합병하여 존속하는 다른 회사 중 어느 하나의 행위로 보고 시정조치를 명할 수 있다":"회사가 분할되었어도 분할 전 남용행위는 분할 관련 회사 중 어느 하나의 행위로 보아 시정조치를 명할 수 있습니다.","분할일 이전 위반행위를 분할되는 회사, 분할·분할합병으로 설립되는 새로운 회사, 분할되는 회사의 일부를 합병하여 존속하는 다른 회사 중 어느 하나의 행위로 보고 과징금을 부과·징수할 수 있다":"분할 전의 위반행위는 분할되는 회사나 새로 생긴 회사 중 어느 하나의 행위로 보아 과징금을 부과합니다.","불가피한 경우에도 예외가 없다":"조사권 남용 금지에는 불가피한 경우라는 예외가 조문에 마련되어 있지 않습니다.","불공정거래행위, 재판매가격유지행위 및 특수관계인에 대한 부당한 이익제공의 금지행위 규제에 관한 사항":"불공정거래행위와 재판매가격유지, 특수관계인에 대한 부당한 이익제공 규제도 소관 사무입니다.","불공정거래행위가 되려면 공정한 거래를 해칠 우려가 있어야 한다":"해당 유형의 행위라도 공정한 거래를 해칠 우려가 있어야 불공정거래행위가 됩니다.","불공정거래행위는 조합 행위라도 적용 대상이다":"조합이 불공정거래행위를 하면 적용제외 대상이 아니라 이 법의 규제를 받습니다.","불공정거래행위 유형으로는 규정이 없다":"설비 신설과 증설의 방해는 불공정거래행위의 유형으로는 따로 두고 있지 않습니다.","불공정거래행위의 유형 또는 기준은 대통령령으로 정한다":"불공정거래행위의 구체적 유형과 기준은 대통령령에 위임되어 있습니다.","불공정약관 무효규정은 모든 업종의 사업자에게 예외 없이 적용되는 것이 아니다":"불공정약관의 무효 규정은 일부 업종에서 적용이 제한될 수 있어 예외가 없는 것은 아닙니다.","불복의 소는 서울고등법원을 전속관할로 한다":"처분에 대한 불복 소송은 서울고등법원만 관할권을 가지는 전속관할입니다.","불황극복 구조조정과 중소기업 경쟁력 향상은 이에 해당하지 않는다":"불황 극복을 위한 구조조정과 중소기업 경쟁력 향상은 이 예외 사유에 들어 있지 않습니다.","브랜드 내 가격경쟁(intrabrand)은 불가능해지지만 품질·서비스 등 비가격경쟁은 촉진될 수 있다":"같은 브랜드 안의 가격경쟁은 막히지만 품질과 서비스 같은 비가격 경쟁은 활발해질 수 있습니다.","비밀유지명령 신청을 기각·각하한 재판에 대해서는 즉시항고를 할 수 있다":"비밀유지명령 신청이 기각되거나 각하되면 신청인은 즉시항고로 불복할 수 있습니다.","비밀유지명령 위반 2년 이하의 징역 또는 2천만원 이하의 벌금, 제119조 비밀엄수 위반 2년 이하의 징역 또는 200만원 이하의 벌금":"비밀유지명령 위반과 비밀엄수의무 위반은 각각 정해진 징역과 벌금으로 처벌합니다.","비밀유지명령은 결정서가 명령을 받을 자에게 송달된 때부터 효력이 발생한다":"법원이 비밀유지명령을 결정하면 결정서가 명령을 받는 사람에게 전달되는 순간부터 구속력이 생깁니다.","비밀유지명령이 내려진 소송기록의 비밀 기재부분 열람 청구가 명령 받지 않은 자에 의해 이루어지면 법원사무관등은 신청한 당사자에게 그 사실을 알리고, 청구일부터 2주일이 지날 때까지 열람하게 해서는 안 된다":"명령을 받지 않은 사람이 비밀 부분 열람을 청구하면 법원은 신청 당사자에게 알리고 이 주가 지나기 전에는 열람시키지 않습니다.","사건 심의에 필요하면 당사자의 신청이나 직권으로 할 수 있다":"증거조사는 심의에 필요하다고 판단하면 당사자 신청이 없어도 직권으로 할 수 있습니다.","사건처리절차 등 필요한 사항은 공정거래위원회가 고시한다":"사건 처리 절차의 세부 사항은 법이 아닌 공정거래위원회 고시로 정합니다.","사무처를 두어 사무를 처리한다":"위원회는 사무처를 두고 행정 사무를 처리하게 합니다.","사무처의 장은 정부위원이 된다":"사무처의 장도 위원장과 같이 정부위원의 지위를 가집니다.","사업 개시 후 3년이 안 된 경우는 환산한다":"사업을 시작한 지 삼 년이 안 되었다면 그 기간의 매출액을 기준으로 평균을 환산합니다.","사업능력, 재무상태, 신용도, 기술력, 품질, 가격 또는 거래조건 등에 대한 합리적 고려나 다른 사업자와의 비교 없이 상당한 규모로 거래하는 행위":"능력과 가격 같은 합리적 고려나 타 사업자 비교 없이 상당한 규모로 특수관계인과 거래하는 행위입니다.","사업자, 이행 보조자 또는 피고용자의 고의 또는 중대한 과실로 인한 법률상의 책임을 배제하는 조항":"사업자와 그 보조자의 고의나 중대한 과실로 인한 책임을 배제하는 조항은 무효입니다.","사업자가 2개뿐이고 그중 하나인 경우는 제외":"담합 참가 사업자가 둘뿐이고 그중 하나라면 두 번째 신고자 감경은 적용되지 않습니다.","사업자가 거래가격을 미리 정하여 유통단계의 가격경쟁을 제한해 소비자후생을 저해하는 것을 방지하기 위한 것":"유통 단계의 가격경쟁이 사라져 소비자후생이 줄어드는 것을 막으려는 것이 금지 취지입니다.","사업자가 거래상 지위를 남용하여 불공정한 내용의 약관을 작성해 거래에 사용하는 것을 방지하고 불공정한 약관을 규제함으로써 건전한 거래질서를 확립한다":"약관규제법은 거래상 지위를 남용한 불공정 약관을 막아 건전한 거래질서를 세우려는 법입니다.","사업자가 계약자의 대리인과 계약을 체결하면 그 대리인에게 설명하면 된다":"계약을 대리인과 맺었다면 그 대리인에게 설명하는 것으로 의무를 다한 것이 됩니다.","사업자가 계약·협정·결의 또는 그 밖의 어떠한 방법으로도 다른 사업자와 공동으로 부당하게 경쟁을 제한하는 행위를 할 것을 합의하는 것, 또는 다른 사업자로 하여금 이를 하도록 하는 것":"담합은 방법을 가리지 않고 다른 사업자와 부당하게 경쟁을 제한하기로 합의하거나 그런 합의를 하게 하는 것입니다.","사업자가 공정거래법상 시장지배적사업자인 경우":"사업자가 공정거래법상 시장지배적사업자이면 시정명령을 할 수 있는 사유가 됩니다.","사업자가 명시·교부의무(제2항) 또는 설명의무(제3항)를 위반하여 계약을 체결하면 해당 약관을 계약의 내용으로 주장할 수 없다":"명시, 교부, 설명의무를 어기면 사업자는 그 약관 조항을 계약 내용으로 주장하지 못합니다.","사업자가 상품 또는 용역을 거래할 때 거래상대방인 사업자 또는 그 다음 거래단계별 사업자에 대해 거래가격을 정하여 그 가격대로 판매·제공할 것을 강제하거나 그 밖의 구속조건을 붙여 거래하는 행위":"재판매가격유지행위는 거래상대방이나 그 다음 단계 사업자에게 가격을 정해 그대로 팔도록 강제하는 행위입니다.","사업자가 상품·용역을 거래할 때 거래상대방인 사업자 또는 그 다음 거래단계별 사업자에 대해 거래가격을 정하여 그 가격대로 판매·제공할 것을 강제하거나 그 밖의 구속조건을 붙여 거래하는 행위":"거래 상대와 그 다음 단계 사업자의 판매가격을 정해 두고 그대로 팔도록 구속하는 것이 재판매가격유지입니다.","사업자가 업무상 알게 된 고객의 비밀을 '정당한 이유 없이' 누설하는 것을 허용하는 조항":"업무상 알게 된 고객 비밀을 정당한 이유 없이 누설해도 된다고 하는 조항은 무효입니다.","사업자가 자기의 거래상의 지위를 부당하게 이용하여 계약을 체결하는 경우":"사업자가 거래상 지위를 부당하게 이용해 계약하는 경우도 시정명령 사유입니다.","사업자가 제1항의 권고를 정당한 사유 없이 따르지 않아 여러 고객에게 피해가 발생하거나 발생할 우려가 현저한 경우":"정당한 사유 없이 시정권고를 따르지 않아 여러 고객에게 피해가 생겼거나 생길 우려가 크면 시정명령을 합니다.","사업자가 집단분쟁조정의 내용을 수락하면 협의회는 당사자가 아닌 피해 고객에 대한 보상계획서를 작성해 제출하도록 '권고'할 수 있다(명령 아님)":"사업자가 조정 내용을 받아들이면 협의회는 당사자 외 피해 고객의 보상계획서 제출을 권고할 수 있으며 명령은 아닙니다.","사업자는 계약을 체결할 때 고객에게 약관의 내용을 계약 종류에 따라 일반적으로 예상되는 방법으로 분명하게 밝혀야 한다":"계약을 맺을 때 계약 종류에 맞는 일반적인 방법으로 약관 내용을 분명하게 밝히는 것이 명시의무입니다.","사업자는 계열회사 또는 다른 사업자로 하여금 불공정거래행위를 하도록 해서도 안 된다":"직접 하지 않더라도 계열회사나 다른 사업자가 불공정거래행위를 하게 하는 것도 금지됩니다.","사업자는 고객이 약관의 내용을 쉽게 알 수 있도록 한글로 작성하여야 한다":"약관은 고객이 내용을 쉽게 이해하도록 한글로 쓰는 것이 작성 방법의 하나입니다.","사업자는 약관에 정하여져 있는 중요한 내용을 고객이 이해할 수 있도록 설명하여야 한다":"약관의 중요한 내용은 고객이 이해하도록 사업자가 설명해야 하는 설명의무가 있습니다.","사업자는 재판매가격유지행위를 하여서는 안 된다":"재판매가격유지행위는 사업자가 하면 안 되는 금지 행위가 원칙입니다.","사업자는 제45조 제1항 불공정거래행위 및 제46조 재판매가격유지행위와 관련하여 분쟁조정 신청, 신고, 공정거래위원회 조사 협조를 한 사업자에게 그 이유로 거래정지·물량축소·그 밖의 불이익을 주거나 계열회사·다른 사업자가 하도록 해서는 안 된다":"분쟁조정 신청이나 신고, 조사 협조를 이유로 거래정지나 물량 축소 같은 불이익을 주는 보복은 금지됩니다.","사업자는 제6조~제14조에 해당하는 불공정약관조항을 계약의 내용으로 하여서는 안 된다":"사업자는 불공정약관조항에 해당하는 내용을 계약에 넣어서는 안 됩니다.","사업자단체가 사업자에게 재판매가격유지행위를 하게 하거나 방조하면 금지행위에 해당한다":"사업자단체가 사업자로 하여금 재판매가격유지를 하게 하거나 돕는 것은 단체의 금지행위입니다.","사업자단체가 제51조 제1항 제4호의 불공정거래행위를 하게 한 경우에도 금지청구(제108조)의 대상이 된다":"사업자에게 불공정거래행위를 하게 한 사업자단체도 피해자가 금지청구를 할 수 있는 대상입니다.","사업자단체도 같은 인가 요건에 해당하면 공정거래위원회 인가를 얻어 공동행위를 할 수 있다":"사업자단체도 같은 인가 요건을 갖추었다면 인가를 받아 공동행위를 할 수 있습니다.","사업자단체를 설립해도 공정거래위원회에 신고할 의무가 없다":"설립이 자유로워 공정거래위원회에 신고하거나 허가를 받을 필요가 없습니다.","사업자단체에 10억원의 범위":"사업자단체의 금지행위 위반에 대해 단체에는 십억 원 범위의 과징금을 부과합니다.","사업자단체에 관한 규정을 적용할 때는 사업자의 이익을 위한 행위를 하는 임원, 종업원, 대리인, 그 밖의 자를 사업자로 본다":"사업자단체 규정에서는 사업자를 위해 일하는 임원과 종업원, 대리인도 사업자로 취급합니다.","사업자단체에는 10억원의 범위에서 과징금, 참가 사업자에는 매출액 100분의 10(없으면 20억원) 이하 과징금":"사업자단체에는 십억 원 범위, 참가 사업자에는 매출액 백분의 십 이하의 과징금을 부과합니다.","사업자단체와 구성 사업자는 법인이 아니어도 되며, 조합이나 법인 등 형태의 제한이 없다":"법인격이 없어도 되고 조합이나 법인 같은 형태에 제한이 없어 실질로 판단합니다.","사업자 등이 출석요구에 정당한 이유 없이 불응하면 1억원 이하(임원·종업원 등은 1천만원 이하)의 과태료":"정당한 이유 없이 출석요구에 응하지 않으면 사업자는 일억 원 이하, 임원 등은 천만 원 이하 과태료입니다.","사업자 또는 사업자단체가 다른 법령에 따라 하는 정당한 행위에는 이 법을 적용하지 않는다":"다른 법령이 허용한 정당한 행위는 공정거래법 적용에서 제외됩니다.","사업자 또는 사업자단체는 부당한 고객유인을 방지하기 위하여 자율적으로 공정경쟁규약을 정할 수 있다":"공정경쟁규약은 사업자와 단체가 부당한 고객유인을 스스로 막으려고 정하는 자율 규약입니다.","사업자 또는 사업자단체의 임원·종업원, 그 밖의 이해관계인이 조사를 거부·방해·기피한 경우":"사업자 등의 임원이나 종업원, 이해관계인이 조사를 방해하면 천만 원 이하의 과태료를 부과합니다.","사업자 및 사업자단체는 일정한 거래 분야에서 표준이 될 약관의 제정·개정안을 마련해 법 위반 여부에 관한 심사를 공정거래위원회에 청구할 수 있다":"사업자와 단체는 표준이 될 약관안을 만들어 법 위반 여부의 심사를 공정거래위원회에 청구할 수 있습니다.","사업자·사업자단체는 이 법을 위반하여 피해를 입은 자에게 손해배상 책임을 진다":"이 법을 위반한 사업자와 사업자단체는 피해를 입은 사람에게 손해를 배상할 책임이 있습니다.","사업자·사업자단체 등 1억원 이하, 임원·종업원·이해관계인 1천만원 이하(기업결합 신고 위반, 공시 위반, 출석요구 불응, 서면실태조사 자료 미제출 등)":"신고 위반이나 공시 위반, 출석 불응에 대해 사업자는 일억 원 이하, 임원 등은 천만 원 이하의 과태료입니다.","사업자·사업자단체의 사무소·사업장에 출입해 진술을 들으려면 그 사무소·사업장에서 들어야 한다":"사업장에 출입해서 진술을 듣는 경우에는 그 사무소나 사업장에서 들어야 합니다.","사업자에게 과중하게 부담시키는 조항은 무효사유가 아니다":"사업자에게 의무를 무겁게 지우는 조항은 고객에게 불리하지 않아 무효 사유가 되지 않습니다.","사업자에게 법률에서 규정하고 있지 않은 해제권 또는 해지권을 부여하여 고객에게 부당하게 불이익을 줄 우려가 있는 조항":"법에 없는 해제권이나 해지권을 사업자에게 주어 고객에게 불이익을 줄 우려가 있는 조항은 무효입니다.","사업자에게 불공정거래행위(제45조 제1항) 또는 재판매가격유지행위(제46조)를 하게 하거나 이를 방조하는 행위":"사업자가 불공정거래행위나 재판매가격유지를 하도록 시키거나 돕는 것이 네 번째 금지행위입니다.","사업자에게 입증책임을 부담시키는 조항이 아니다":"무효가 되는 조항은 고객에게 입증책임을 지우는 것이며 사업자에게 지우는 조항이 아닙니다.","사업자의 지위가 현저히 우월하거나 고객이 다른 사업자를 선택할 범위가 제한되어 약관을 계약 내용으로 하는 것이 사실상 강제되는 경우":"사업자 지위가 우월하거나 고객의 선택지가 좁아 약관을 따를 수밖에 없는 경우에도 시정명령을 할 수 있습니다.","사업자의 책임이나 의무를 면제하는 약관 문언이 불명확하면 사업자가 그중 최소한의 책임과 의무만 면제하는 것으로 해석하고 확장 해석하지 않는다":"면책 문구가 불명확하면 사업자에게 불리하게 가장 좁은 범위의 면책으로만 해석합니다.","사업활동 방해 등 다른 불공정거래행위는 100분의 4와 10억원이다":"지원행위가 아닌 다른 불공정거래행위는 과징금 상한이 매출액의 백분의 사, 매출이 없으면 십억 원입니다.","사유가 있어도 하여야 하는 것이 아니다":"결손처분 사유가 있어도 반드시 해야 하는 의무는 없고 공정거래위원회가 재량으로 정합니다.","산업경쟁력 강화에 매우 필요하고 경제적 파급효과가 클 것, 투자금액이 과다하여 한 사업자가 조달하기 어려울 것, 성과의 불확실에 따른 위험분산에 필요할 것, 경쟁제한 효과보다 연구·기술개발 효과가 클 것":"연구개발 인가는 산업경쟁력에 필요하고 투자가 과다하며 위험분산이 필요하고 효과가 경쟁제한보다 클 것을 모두 요구합니다.","상당한 이유 없이 계약목적물에 관하여 견본이 제시되거나 품질·성능 등에 관한 표시가 있는 경우 그 보장된 내용에 대한 책임을 배제 또는 제한하는 조항":"견본이나 품질 표시로 보장한 내용에 대한 책임을 상당한 이유 없이 배제하거나 제한하는 조항은 무효입니다.","상당한 이유 없이 급부의 내용을 사업자가 일방적으로 결정하거나 변경할 수 있도록 권한을 부여하는 조항":"급부의 내용을 사업자가 마음대로 정하거나 바꿀 수 있게 하는 조항은 상당한 이유가 없으면 무효입니다.","상당한 이유 없이 사업자가 이행하여야 할 급부를 일방적으로 중지할 수 있게 하거나 제3자에게 대행할 수 있게 하는 조항":"사업자가 해야 할 급부를 일방적으로 중지하거나 제삼자에게 대행시키도록 하는 조항은 무효입니다.","상당한 이유 없이 사업자의 담보책임을 배제 또는 제한하거나 담보책임에 따르는 고객의 권리행사 요건을 가중하는 조항(완화가 아니다)":"담보책임을 배제하거나 제한하고 고객의 권리 행사 요건을 더 까다롭게 하는 조항이 무효 대상입니다.","상당한 이유 없이 사업자의 손해배상 범위를 제한하거나 사업자가 부담하여야 할 위험을 고객에게 떠넘기는 조항":"상당한 이유 없이 배상 범위를 줄이거나 사업자가 질 위험을 고객에게 넘기는 조항은 무효입니다.","상당한 주의와 감독을 게을리하지 않았다면 제외":"법인이나 개인이 위반을 막으려고 상당한 주의와 감독을 했다면 양벌 처벌에서 제외됩니다.","상당히 유리한 조건의 자금 거래, 자산·상품·용역 거래, 인력 거래":"유리한 조건 거래 금지가 적용되는 거래는 자금, 자산과 상품과 용역, 인력 거래 세 부류입니다.","상대방에게 부당하게 불이익을 주는 행위인지는 문제가 되는 거래조건으로 상대방에게 생길 수 있는 불이익의 내용과 불이익 발생의 개연성 등 여러 요소를 종합하여 판단한다":"불이익의 내용과 발생 개연성 같은 여러 요소를 종합하여 부당 여부를 판단합니다.","상대방은 직접 거래상대방인 사업자뿐 아니라 그 다음 거래단계별 사업자도 포함한다":"가격을 지키도록 하는 상대방에는 직접 거래하는 사업자뿐 아니라 그 이후 단계의 사업자도 들어갑니다.","상법 제3편(회사), 근로기준법, 그 밖에 대통령령으로 정하는 비영리사업 분야에 속하는 계약에 관한 약관":"회사법 분야와 근로기준법, 시행령이 정한 비영리 분야 계약의 약관에는 약관법이 적용되지 않습니다.","상위 사업자가 하위 사업자에 조직적으로 가격제한을 가해 하위 사업자의 자율성을 침해하는 수직적 가격결정(Vertical Price Fixing)이다":"상위 사업자가 하위 사업자의 가격 자율성을 침해하는 수직적 가격결정의 성격을 가집니다.","상위 셋 합계 85%로 요건을 충족하고 연매출 요건(2022 기출 당시 40억원)에서 C(30억원)가 빠져 추정되는 자는 A, B, D":"상위 세 곳 합계는 충족하지만 매출액 요건에서 C가 빠져 결과적으로 A, B, D가 추정됩니다.","상임위원이 주재하며 구성위원 전원의 출석과 출석위원 전원의 찬성으로 의결한다":"소회의는 상임위원이 주재하며 구성위원이 모두 나와 출석위원이 모두 찬성해야 의결됩니다.","상표 내 경쟁은 제한되고 상표 간 경쟁은 촉진될 수 있다는 것이 재판매가격유지의 장점으로 거론되는 내용이다":"같은 상표 안 경쟁은 줄고 상표 사이의 경쟁이 늘 수 있다는 점이 재판매가격유지의 장점으로 거론됩니다.","상품·용역을 거래할 때 그 거래상대방의 거래지역 또는 거래상대방을 부당하게 구속하는 조건으로 거래":"거래상대방이 영업할 지역이나 거래할 상대를 부당하게 구속하는 조건을 붙이는 행위입니다.","상품·용역의 거래조건이나 그 대금 또는 대가의 지급조건을 정하는 행위":"가격 외의 거래조건과 대금 지급조건을 공동으로 정하는 것도 부당한 공동행위입니다.","상품·용역의 생산·거래 시 종류·규격을 제한하는 행위":"생산하거나 거래할 상품의 종류와 규격을 공동으로 제한하는 합의입니다.","상품의 생산·출고·수송 또는 거래의 제한이나 용역의 거래를 제한하는 행위":"생산량과 출고, 수송을 제한하여 공급을 조절하는 합의가 이 유형입니다.","상호출자제한기업집단 소속 국내 회사(금융업·보험업 회사 제외)는 채무보증을 할 수 없다":"금융업과 보험업 회사를 뺀 상호출자제한 집단 소속 회사는 계열회사에 채무보증을 하지 못합니다.","상호출자제한기업집단 소속 국내 회사는 순환출자를 형성하는 계열출자를 할 수 없고, 기존 순환출자 관계 회사는 계열출자대상회사에 추가 계열출자를 할 수 없다":"새로 순환출자를 만들 수 없고 기존 순환출자 회사가 대상 회사에 더 출자하는 것도 금지됩니다.","상호출자제한기업집단 소속 국내 회사는 자기 주식을 취득·소유한 국내 계열회사의 주식을 취득·소유할 수 없다":"자기 주식을 가진 계열회사의 주식을 서로 가지는 상호출자를 금지합니다.","상황 변화를 이유로도 불가능":"사정이 바뀌었다는 이유가 있어도 공소 제기 후의 고발 취소는 불가능합니다.","새로운 경쟁사업자에 대한 필수요소 접근 거절만 참가 방해에 해당한다":"필수요소 접근 거절 가운데 신규 진입자를 대상으로 한 것만 참가 방해로 분류합니다.","생산능률 향상·거래 원활화·소비자 편익증진에 명백히 기여할 것, 합리화 내용이 해당 분야 대부분 사업자에게 기술적·경제적으로 가능할 것, 경쟁제한 효과보다 합리화 효과가 클 것":"거래조건 합리화 인가는 명백한 기여와 대부분 사업자에게 가능한 내용, 경쟁제한보다 큰 효과를 모두 갖춰야 합니다.","생산 또는 용역의 거래를 위한 설비의 신설·증설이나 장비의 도입을 방해하거나 제한하는 행위":"새 설비 설치나 장비 도입을 서로 막거나 제한하기로 합의하는 행위입니다.","생산·용역 거래를 위한 설비의 신설·증설이나 장비 도입의 방해·제한은 부당한 공동행위(제40조 제1항 제5호) 유형이다":"설비 신설과 증설을 방해하거나 제한하는 행위는 담합의 한 유형으로 규정되어 있습니다.","서면으로만 제출하는 것이 아니다":"당사자의 의견 제시는 서면 제출에 한정되지 않고 출석해서 진술하는 방법도 있습니다.","설명의무 대상인 중요한 내용: 사회통념에 비추어 고객이 계약체결 여부나 대가를 결정하는 데 직접적인 영향을 미칠 수 있는 사항":"고객이 계약 체결 여부나 대가를 정하는 데 직접 영향을 줄 수 있는 사항이 설명의무 대상인 중요한 내용입니다.","설명의무의 상대방은 계약자 본인에 한하지 않는다":"설명해야 할 상대는 반드시 계약 당사자 본인이 아니어도 됩니다.","세부 유형 및 기준은 공정거래위원회가 고시한다":"경쟁사업자 배제의 구체적 유형과 기준은 공정거래위원회가 고시로 정합니다.","셋 이하 사업자의 시장점유율 합계가 100분의 75 이상":"세 곳 이하의 합산 점유율이 사분의 삼 이상이면 해당 사업자들을 지배적 사업자로 추정합니다.","소규모의 사업자 또는 소비자의 상호부조를 목적으로 할 것":"조합 적용제외의 첫째 요건은 소규모 사업자나 소비자가 서로 돕는 것을 목적으로 하는 것입니다.","소비자단체등(소비자기본법에 따라 등록된 소비자단체, 한국소비자원)은 소비자 피해가 자주 일어나는 거래 분야에서 표준이 될 약관을 제정 또는 개정할 것을 공정거래위원회에 요청할 수 있다":"소비자단체 등은 피해가 잦은 거래 분야의 표준약관을 제정하거나 개정해 달라고 요청할 수 있습니다.","소속 공무원이 사업자·사업자단체의 사무소·사업장에 출입해 업무·경영상황, 장부·서류, 전산자료·음성녹음자료·화상자료 등을 조사할 수 있다":"공무원이 사업장에 들어가 장부와 서류, 전산 자료와 음성 및 화상 자료 등을 조사할 수 있습니다.","소송이 진행 중이면 수소법원이 소송절차를 중지할 수 있고, 중지되지 않으면 협의회가 조정절차를 중지한다":"같은 사건으로 소송 중이면 법원이 먼저 소송을 멈출 수 있고 그렇지 않으면 협의회가 조정을 멈춥니다.","소송절차가 중지되지 않으면 협의회는 조정절차를 중지하여야 한다":"법원이 소송을 중지하지 않으면 협의회가 조정절차를 중지해야 합니다.","소송 제기 등과 관련해 '상당한 이유 없이 고객에게' 입증책임을 부담시키는 약관 조항은 무효":"소송과 관련해 상당한 이유 없이 고객에게 입증책임을 지우는 약관 조항은 무효입니다.","소회의 결정으로 이행기한을 정해 다시 명령할 수 있고 불이행 시 1일 평균매출액의 1천분의 3 범위(매출액이 없거나 산정 곤란하면 1일 200만원 범위)에서 부과":"자료제출 명령을 다시 내려도 어기면 하루 평균매출액의 천분의 삼 범위, 매출이 없으면 하루 이백만 원 범위에서 부과합니다.","소회의는 전원회의 관장 사항 외의 사항을 심의·의결한다":"전원회의가 맡는 것이 아닌 나머지 사항은 소회의가 심의하고 의결합니다.","소회의에서 의결되지 않았거나 소회의가 전원회의에서 처리하도록 결정한 사항":"소회의가 의결하지 못했거나 전원회의에서 처리하기로 한 사항도 전원회의가 맡습니다.","손해 발생은 인정되나 손해액 입증이 사실의 성질상 매우 곤란하면 변론 전체의 취지와 증거조사 결과에 기초해 상당한 손해액을 인정할 수 있다":"손해는 있는데 금액 입증이 매우 어렵다면 법원이 변론의 취지와 증거 조사를 바탕으로 상당한 액수를 인정합니다.","손해배상소송에서 법원은 공정거래위원회에 사건기록(심문조서, 속기록, 그 밖의 재판상 증거 일체)의 송부를 요구할 수 있다":"손해배상소송의 법원은 공정거래위원회에 심문조서와 속기록 같은 사건기록을 보내 달라고 요구할 수 있습니다.","손해의 3배를 넘지 않는 범위에서 책임":"위 위반의 피해자에게는 실제 손해의 삼 배를 넘지 않는 범위에서 배상 책임을 집니다.","수익의 극대화, 기업지배구조의 조정·합리화, 대기업의 경쟁력 향상, 첨단산업 육성을 위한 산업구조조정":"이 항목들은 법이 인가 목적으로 열거한 네 가지에 들지 않아 인가 사유가 되지 못합니다.","수 차례의 합의가 1개의 공동행위가 되기 위해 위반기간 전체에 걸쳐 합의 당사자가 동일할 필요는 없다":"여러 번의 합의를 하나의 공동행위로 묶으려고 위반 기간 내내 당사자가 같을 필요는 없습니다.","순환출자는 세 개 이상의 계열출자로 연결된 계열회사 모두가 계열출자회사 및 계열출자대상회사가 되는 관계":"세 개 이상의 계열출자가 고리처럼 이어져 각 회사가 출자하는 쪽이자 받는 쪽이 되는 관계가 순환출자입니다.","시장구조의 조사 및 공표, 특정 산업의 경쟁상황 분석·규제현황 분석·경쟁촉진 방안 마련":"독과점 개선 업무로는 시장구조 조사와 공표, 산업별 경쟁상황과 규제 분석, 경쟁촉진 방안 마련이 있습니다.","시장 범위·점유율 등 별도 경제적 분석 필요, 고도의 법리적 분석 필요, 새로운 주장·자료 제출로 장기 조사 필요, 당사자 등의 조사 비협조":"경제 분석이나 고도의 법리 분석이 필요하거나 새 자료로 조사가 길어지거나 비협조가 있으면 재결기간을 늘릴 수 있습니다.","시장점유율, 진입장벽의 존재 및 정도, 경쟁사업자의 상대적 규모":"시장지배적 지위 판단에서 법이 직접 든 고려 요소는 점유율과 진입장벽, 경쟁사업자의 상대적 규모입니다.","시장점유율, 진입장벽의 존재 및 정도, 경쟁사업자의 상대적 규모 등을 종합 고려한다":"점유율 하나만 보지 않고 진입장벽과 경쟁사업자의 규모 같은 요소를 함께 따져 판단합니다.","시장점유율 100분의 10 미만인 사업자는 제외한다":"합계 요건으로 추정할 때 점유율이 십 분의 일에 못 미치는 사업자는 추정 대상에서 뺍니다.","시장지배적사업자를 판단할 때는 해당 사업자와 그 계열회사를 하나의 사업자로 본다":"지배적 지위를 따질 때는 계열회사를 합산해 하나의 사업자로 보고 점유율을 계산합니다.","시장지배적사업자의 사전지정·고시제도는 폐지되었다":"시장지배적사업자를 미리 지정하고 고시하던 제도는 없어져 사건마다 개별 판단합니다.","시장지배적 사업자인지 여부, 피해자의 재산상태":"사업자가 시장지배적인지와 피해자의 재산상태는 배상액 산정 때 법이 정한 고려사항이 아닙니다.","시장지배적지위를 남용하여 경쟁을 제한하는 행위, 소비자의 이익을 현저히 해칠 우려가 있는 행위, 시장구조의 조사·공표":"이 항목들은 사업자단체의 금지행위 네 가지에 들어 있지 않습니다.","시장지배적지위의 남용과 과도한 경제력집중을 방지하고 부당한 공동행위와 불공정거래행위를 규제한다":"이 법이 규제하는 네 가지 영역을 나열한 것으로 남용, 경제력집중, 담합, 불공정거래가 해당합니다.","시장지배적지위의 남용행위 규제에 관한 사항":"공정거래위원회 소관 사무의 하나로 시장지배적지위 남용행위의 규제가 있습니다.","시정권고 또는 시정명령은 그 내용을 분명히 밝힌 서면으로 하여야 한다":"시정권고와 시정명령은 구두가 아니라 내용을 분명히 적은 서면으로 해야 합니다.","시정권고·시정명령을 할 때 필요하면 같은 종류의 사업을 하는 다른 사업자에게 같은 내용의 불공정약관조항을 사용하지 말 것을 권고할 수 있다":"같은 업종의 다른 사업자에게도 같은 내용의 불공정 약관을 쓰지 말라고 함께 권고할 수 있습니다.","시정명령과 같은 효력이 아니다":"조정조서의 효력은 행정청의 시정명령과 같은 것이 아니라 재판상 화해와 같은 것입니다.","시정명령(제17조의2 제2항 명령)을 이행하지 않으면 2년 이하의 징역 또는 1억원 이하의 벌금":"시정명령을 이행하지 않으면 이 년 이하 징역 또는 일억 원 이하 벌금으로 처벌합니다.","시정방안은 신청인과 협의해 수정할 수 있다":"공정거래위원회는 제출된 시정방안을 신청인과 협의해 고칠 수 있습니다.","시정조치 또는 과징금의 감경·면제 가능, 고발 면제 가능":"감면의 내용은 시정조치와 과징금을 줄이거나 면제하고 고발도 면제할 수 있다는 것입니다.","시정조치를 명하거나 과징금을 부과하기 전에 당사자 또는 이해관계인에게 의견을 진술할 기회를 주어야 한다":"시정조치나 과징금 처분 전에 당사자 등이 의견을 말할 기회를 반드시 주어야 합니다.","시정조치를 받은 자가 이의신청을 제기한 경우 회복하기 어려운 손해를 예방하기 위해 필요하다고 인정하면 당사자 신청이나 직권으로 시정조치 이행·절차 계속 진행의 정지를 결정할 수 있다":"회복하기 어려운 손해를 막기 위해 필요하면 이의신청 중 시정조치의 이행이나 절차 진행을 정지할 수 있습니다.","시정조치 불이행, 일정 자료제출 거부·허위, 공인회계사 감사 미수감, 제45조 제1항 위반 불공정거래행위(제1·2·3·7·9호 제외), 사업자단체의 제51조 제1항 제3호 위반, 제81조 제1항 제3호·제6항 보고·자료제출 위반, 자료 은닉·폐기·위조 등 조사 방해":"시정조치를 따르지 않거나 일부 불공정거래행위를 하거나 자료를 숨기고 조사를 방해하면 이 년 이하 징역 또는 일억오천만 원 이하 벌금 대상입니다.","신고는 공정거래위원회의 직권 발동을 촉구하는 단서 제공에 불과하다":"신고는 공정거래위원회가 스스로 조사에 나서도록 계기를 주는 데 그치며 신고인에게 처분 청구권은 없습니다.","신고인의 성명·주소, 피신고인의 주소·대표자 성명·사업내용, 피신고인의 위반행위 내용, 그 밖에 위반행위를 명백히 할 사항":"신고서에는 신고인과 피신고인의 인적 사항, 위반행위의 내용 등을 적어야 합니다.","신문사와 지국 간 소송은 원고 관할법원에서 한다는 약정은 공정거래를 저해할 우려가 있다고 단정할 수 없다고 본 사례가 있다":"소송을 원고 관할 법원에서 한다는 약정만으로는 공정거래 저해 우려가 있다고 단정하지 않은 사례입니다.","신의성실의 원칙을 위반하여 공정성을 잃은 약관 조항은 무효다":"신의성실에 반하여 공정성을 잃은 약관 조항은 무효가 된다는 일반원칙입니다.","신청 내용이 약관의 해석이나 그 이행을 요구하는 사건":"약관의 해석이나 이행을 요구하는 내용의 신청은 조정 대상이 아니라서 각하됩니다.","신청 또는 의뢰를 받은 날부터 60일(분쟁당사자 쌍방이 기간연장에 동의하면 90일)이 지나도 조정이 성립하지 않은 경우 (30일이 아니다)":"신청이나 의뢰 후 육십 일, 양쪽이 연장에 동의하면 구십 일이 지나도 조정이 안 되면 절차가 종료됩니다.","신청서 보완이 필요하면 협의회 위원장이 상당한 기간을 정해 보완을 요구하여야 하며 보완 기간은 60일 기간에서 제외한다":"보완이 필요하면 위원장이 기간을 정해 요구하고 그 기간은 육십 일 처리 기한에서 뺍니다.","신청은 공고기간에 서면으로 하며, 협의회는 공고기간이 끝난 후 10일 이내에 참가 인정 여부를 서면으로 알린다":"추가 신청은 공고 기간에 서면으로 하고 협의회는 기간이 끝난 뒤 십 일 안에 참가 인정 여부를 알립니다.","신청은 해당 행위를 특정할 수 있는 사실관계, 해당 행위의 중지·원상회복 등 시정방안, 피해 구제·예방 시정방안을 기재한 서면으로 한다":"신청서에는 행위를 특정할 사실관계와 중지와 원상회복 방안, 피해 구제 방안을 적어야 합니다.","신청을 받은 날(또는 의뢰받은 날)부터 60일이 지나도 조정이 성립하지 않은 경우":"신청이나 의뢰를 받은 날부터 육십 일이 지나도 조정이 안 되면 절차를 종료합니다.","신청인 또는 명령을 받은 자가 요건을 갖추지 못했거나 못하게 된 경우 소송기록 보관 법원에 취소를 신청할 수 있다":"요건이 없거나 사라졌다면 신청인이나 명령을 받은 자가 소송기록 보관 법원에 취소를 신청할 수 있습니다.","신청인은 이행계획과 이행결과를 제출하여야 한다":"동의의결을 받은 신청인은 이행 계획과 이행 결과를 공정거래위원회에 제출해야 합니다.","신청 전에 공정거래위원회가 제80조에 따라 조사를 개시한 사건에 대해 신청한 경우":"신청하기 전에 공정거래위원회가 이미 조사를 시작한 사건이라면 신청은 각하됩니다.","신청한 자의 고소가 있어야 공소 제기 가능":"비밀유지명령 위반은 명령을 신청한 사람이 고소해야 공소를 제기할 수 있는 친고죄입니다.","심리는 구술심리를 원칙으로 하되 필요한 경우 서면심리로 할 수 있다":"심리는 말로 하는 구술심리가 원칙이고 필요하면 서면으로 대신할 수 있습니다.","심사 대상 약관의 사본을 첨부":"심사청구서에는 심사를 받을 약관의 사본을 함께 붙여야 합니다.","심사 대상 약관이 다른 법률에 따라 행정관청의 인가를 받았거나 받아야 하면 심의 전에 그 행정관청에 의견 제출을 요구할 수 있다":"심사 대상 약관이 관청 인가를 받았거나 받아야 한다면 그 관청에 심의 전에 의견을 내라고 요구할 수 있습니다.","심사대상인 약관 조항이 변경되면 공정거래위원회가 직권으로 또는 심사청구인의 신청에 의해 심사대상을 변경할 수 있다":"심사 중에 약관이 바뀌면 직권이나 청구인의 신청으로 심사 대상을 변경할 수 있습니다.","심사청구는 공정거래위원회에 서면이나 전자문서로 제출한다":"약관 심사청구는 공정거래위원회에 서면이나 전자문서를 내는 방식으로 합니다.","심사 청구를 명령할 수도 없다(권고만 가능)":"공정거래위원회는 사업자에게 심사 청구를 명령하지 못하고 권고만 할 수 있습니다.","심판정 질서유지 명령 불이행은 100만원 이하":"심판정의 질서유지 명령을 따르지 않으면 백만 원 이하의 과태료를 부과합니다.","아래 사유에 해당하면 삭제·수정, 시정명령을 받은 사실의 공표, 그 밖에 약관을 시정하기 위해 필요한 조치를 명할 수 있다":"다음 사유가 있으면 삭제와 수정, 시정명령 사실 공표 등 필요한 조치를 명령할 수 있습니다.","약관 내용이 모호하다는 것은 두 가지 이상의 의미로 해석될 수 있음을 뜻한다":"모호함은 약관 문구가 두 가지 이상으로 해석될 수 있는 상태를 가리킵니다.","약관 분쟁조정협의회는 한국공정거래조정원에 둔다":"약관 관련 분쟁을 맡는 협의회는 공정거래위원회 안이 아니라 한국공정거래조정원 소속으로 운영합니다.","약관분쟁조정협의회의 요청은 권고 사유가 아니다":"약관분쟁조정협의회가 요청했다는 사정은 심사청구 권고 사유로 열거되어 있지 않습니다.","약관에서 정하고 있는 사항에 관하여 사업자와 고객이 약관의 내용과 다르게 합의한 사항이 있으면 그 합의 사항이 약관보다 우선한다":"개별적으로 합의한 내용은 약관과 달라도 약관보다 우선하는 개별 약정 우선의 원칙입니다.","약관은 신의성실의 원칙에 따라 공정하게 해석되어야 한다":"약관의 해석은 신의성실의 원칙에 맞게 공정하게 이루어져야 합니다.","약관의 뜻이 명백하지 아니한 경우에는 고객에게 유리하게 해석되어야 한다(작성자불이익 원칙)":"뜻이 명백하지 않으면 약관을 만든 사업자에게 불리하게, 즉 고객에게 유리하게 풀이합니다.","약관의 무효판정을 요구하는 사건":"약관이 무효인지 판정해 달라는 신청은 협의회의 권한 밖이어서 각하됩니다.","약관의 전부 또는 일부 조항이 제3조 제4항에 따라 계약의 내용이 되지 못하거나 제6조~제14조에 따라 무효인 경우 계약은 나머지 부분만으로 유효하게 존속한다":"약관 조항이 계약 내용이 되지 못하거나 무효여도 계약은 나머지 부분으로 유지됩니다.","약관의 중요한 내용을 부호, 색채, 굵고 큰 문자 등으로 명확하게 표시하여 알아보기 쉽게 작성하여야 한다":"약관의 중요한 내용은 부호와 색채와 큰 글자 등을 사용해 눈에 띄게 표시해야 합니다.","약관이 근로기준법에 속하는 계약에 관한 것이면 이 법을 적용하지 않는다":"근로계약에 관한 약관은 근로기준법의 영역이라 약관법을 적용하지 않습니다.","약관이라는 명칭을 쓰지 않아도, 계약서 자체에 포함되어 있어도 실질이 약관이면 이 법의 적용을 받는다":"명칭이나 위치와 관계없이 다수와 계약하려고 미리 정한 내용이라면 약관으로 보아 이 법이 적용됩니다.","어느 한 사업자가 진의 아닌 의사표시로 합의한 경우에도 공동행위는 성립한다":"한 사업자가 속으로는 지킬 생각이 없었더라도 합의가 이루어졌다면 공동행위가 성립합니다.","업종 예외 없이 모든 사업자에게 적용되는 것도 아니다":"명시와 교부의무는 일부 업종이 면제되므로 예외 없이 모든 사업자에게 적용되는 것은 아닙니다.","역외적용을 명시한 조문이 없던 때에도 공정거래위원회가 역외적용한 사례가 있다":"역외적용 조문이 생기기 전에도 공정거래위원회가 이를 적용한 사례가 있었습니다.","역외적용 조문은 법 제정 시부터 있던 것이 아니다":"역외적용을 명시한 조문은 법을 처음 만들 때부터가 아니라 나중에 들어왔습니다.","연구·기술개발 요건에 '소비자의 편익증진에 명백하게 기여할 것'은 없다":"연구개발 인가 요건에는 소비자 편익 증진에 명백히 기여한다는 항목이 들어 있지 않습니다.","연기·분할납부는 할 수 있는 재량이다":"연기와 분할납부를 허용할지는 공정거래위원회가 재량으로 정합니다.","영업비밀이라도 손해 증명에 반드시 필요하면 제출 거절의 정당한 이유로 보지 않는다":"영업비밀이라는 이유만으로는 거절할 수 없고 손해 증명에 반드시 필요한 자료는 제출해야 합니다.","영업비밀 자료, 자진신고 등 관련 자료, 다른 법률상 비공개 자료는 제외한다":"영업비밀과 자진신고 관련 자료와 다른 법률상 비공개 자료는 열람과 복사 대상에서 빠집니다.","영업을 개시하지 않았거나 영업중단 등으로 영업실적이 없는 경우, 재해 등으로 매출액 산정자료가 소멸·훼손된 경우, 위반기간 또는 관련 상품·용역의 범위를 확정할 수 없는 경우":"실적이 없거나 자료가 없어졌거나 위반 범위를 정할 수 없을 때가 매출액 산정이 곤란한 경우입니다.","영업의 주요 부문 공동 수행(공동행위)과 거래상대방 사업활동의 부당 구속 거래(불공정거래행위)는 남용행위가 아니다":"공동 수행은 부당한 공동행위, 상대방 구속은 불공정거래행위에 속해 남용행위의 유형이 아닙니다.","영업의 주요 부문을 공동으로 수행·관리하거나 이를 위한 회사 등을 설립하는 행위":"영업의 핵심 부분을 함께 운영하거나 이를 위한 회사를 세워 경쟁을 없애는 행위입니다.","영업 전반을 총괄할 권한이 없는 상업사용인은 임원이 아니다":"영업 전체를 총괄할 권한이 없는 상업사용인은 임원의 범위에 들어가지 않습니다.","예술을 목적으로 하는 비영리단체도 사업자에 해당할 수 있다":"영리를 목적으로 하지 않는 예술 단체라도 사업을 하는 실질이 있으면 사업자일 수 있습니다.","예외: 사건처리 필요, 자진신고자 동의, 소 제기·수행에 필요한 경우":"정보 제공 예외는 사건처리에 필요하거나 신고자가 동의했거나 소송 제기와 수행에 필요한 경우입니다.","예외는 조세특례제한법 합리화기준에 따라 인수되는 회사의 채무 관련, 국제경쟁력 강화 등 대통령령으로 정하는 경우":"합리화기준에 따라 인수하는 회사의 채무와 국제경쟁력 강화 등 시행령이 정한 경우가 채무보증 예외입니다.","예외는 합병 또는 영업 전부의 양수, 담보권 실행 또는 대물변제 수령이며 6개월 이내에 처분하여야 한다":"합병이나 담보권 실행 등으로 취득한 경우는 허용되지만 육 개월 안에 처분해야 합니다.","예탁금 회원제로 운영되는 골프클럽 회원권의 양도·양수절차 조항":"골프클럽 회원권의 양도양수 절차를 정한 조항도 다수 회원에게 적용되는 약관에 해당합니다.","외국 법률로 허용되는 행위라는 사정만으로 우리 법 적용이 당연히 배제되지 않는다":"외국법상 적법한 행위라는 사정 하나로 우리 법의 적용이 저절로 막히지는 않습니다.","외국사업자가 국외에서 한 행위가 국내 시장에 영향을 미친 경우":"역외적용의 대상은 외국 사업자가 국외에서 했는데도 국내 시장에 영향을 준 행위입니다.","요건 적합 증명서류, 불가 사유 비해당 증명서류, 참가사업자 최근 2년간 영업보고서·대차대조표·손익계산서, 공동행위 협정 또는 결의서 사본, 고시하는 서류":"신청서에는 요건과 불가 사유 비해당 증명서류, 최근 이 년의 재무 서류, 협정서 사본 등을 첨부합니다.","요건 충족의 입증은 해당 사업자가 한다":"예외 요건을 갖췄다는 점은 기업결합을 하는 사업자가 직접 입증해야 합니다.","요청·권고는 내용을 분명히 밝힌 서면(전자문서 포함)으로 한다":"관청에 하는 요청과 권고는 내용을 분명히 적은 서면으로 하며 전자문서도 허용됩니다.","요청·권고를 받은 행정관청 또는 금융감독원은 받은 날부터 60일 이내에 공정거래위원회에 서면으로 처리결과를 알려야 한다":"요청이나 권고를 받은 관청과 금융감독원은 육십 일 안에 처리 결과를 서면으로 알려야 합니다.","용역도 재판매가격유지행위 규제 대상이다":"재판매가격유지행위는 상품에만 한정되지 않고 용역 거래에도 규제가 적용됩니다.","용역의 시공 방법은 정보에 해당하지 않는다":"시공 방법은 시행령에 열거된 교환 금지 정보에 포함되지 않습니다.","용역의 제공을 부당하게 조절하는 행위도 남용행위다":"상품뿐 아니라 용역 제공을 부당하게 조절하는 것도 남용행위에 포함됩니다.","원가, 출고량·재고량·판매량, 거래조건 또는 대금·대가의 지급조건":"교환이 문제 되는 정보는 원가와 출고량, 재고량, 판매량, 거래조건과 지급조건입니다.","원재료 구매 방해와 인력 채용, 필수요소 접근 거절(기존 사업자 대상)은 사업활동 방해다":"기존 사업자를 상대로 한 원재료 구매 방해와 인력 채용, 필수요소 접근 거절은 사업활동 방해로 분류합니다.","위계에 의한 차별은 차별적 취급 유형이 아니다(위계에 의한 고객유인은 부당한 고객유인)":"위계는 속임수를 뜻하며 이 유형은 차별적 취급에 없고 부당한 고객유인에 있습니다.","위 계열회사가 단독으로 발행주식총수의 100분의 50을 초과하여 소유한 국내 계열회사":"위 계열회사가 혼자 주식의 절반을 넘게 가진 계열회사도 규제 대상이 되는 상대방입니다.","위반기간 동안 일정한 거래분야에서 판매한 관련 상품·용역의 매출액":"관련매출액은 위반 기간에 해당 거래분야에서 판매한 관련 상품과 용역의 매출액을 말합니다.","위반사업자가 위반기간 동안 일정한 거래분야에서 판매한 관련 상품·용역의 매출액 또는 이에 준하는 금액":"관련매출액은 위반 기간 동안 해당 거래분야에서 판매한 관련 상품과 용역의 매출액이나 이에 준하는 금액입니다.","위반의 정도가 객관적으로 명백하고 중대하여 경쟁질서를 현저히 해친다고 인정하면 공정거래위원회는 고발하여야 한다(현행 고발 상대방은 중대범죄수사청장, 기출 당시 검찰총장)":"위반이 명백하고 중대해 경쟁질서를 크게 해친다고 인정되면 공정거래위원회는 반드시 고발해야 합니다.","위반의 정도가 객관적으로 명백하고 중대하여 경쟁질서를 현저히 해친다고 인정하면 공정거래위원회는 고발하여야 한다 (현행 중대범죄수사청장에게 고발, 기출 당시 검찰총장)":"위반이 객관적으로 명백하고 중대하여 경쟁질서를 크게 해친다고 인정되면 공정거래위원회는 고발해야 합니다.","위반행위 종료일부터 7년이 지나면 시정조치·과징금을 부과할 수 없다":"위반행위가 끝난 날부터 칠 년이 지나면 시정조치와 과징금을 부과할 수 없습니다.","위반 혐의 행위 종료일(인지일·신고일까지 계속되면 그 일)이 속하는 사업연도의 직전 1년 동안 공급·구매한 상품·용역 금액(간접세 제외)":"점유율의 기준 금액은 위반 종료일이 속한 사업연도 직전 일 년 동안의 공급이나 구매액이며 간접세는 뺍니다.","위반 혐의 행위 종료일이 속하는 사업연도의 직전 1년 동안 국내에서 공급·구매된 상품·용역 금액 중 해당 사업자가 공급·구매한 금액의 비율":"시장점유율은 위반 행위 종료일이 속한 사업연도 직전 일 년간 국내 전체 거래액 중 해당 사업자의 비중입니다.","위 방법 외의 부당한 방법으로 다른 사업자의 사업활동을 심히 곤란하게 할 정도로 방해":"앞의 방법 외의 부당한 방법으로도 사업활동을 심히 곤란하게 할 정도로 방해하면 금지됩니다.","위 방법 외의 부당한 방법으로 다른 사업자의 사업활동을 어렵게 하는 행위 중 공정거래위원회가 고시하는 행위":"앞의 유형 외에도 공정거래위원회가 고시한 부당한 방법의 사업활동 방해가 있습니다.","위 방법 외의 부당한 방법으로 신규진입을 어렵게 하는 행위 중 고시하는 행위":"고시로 정해진 그 밖의 부당한 방법으로 신규 진입을 어렵게 하는 행위도 참가 방해에 들어갑니다.","위원 또는 배우자(였던 자)가 분쟁당사자이거나 공동권리자·의무자인 경우, 친족관계, 자문·고문, 대리인 관여·증언·감정 등":"위원이나 배우자가 당사자이거나 친족, 자문, 대리인 관여, 증언 등의 관계이면 제척 사유가 됩니다.","위원 본인은 스스로 회피할 수 있다":"위원이 스스로 제척이나 기피 사유가 있다고 보면 자발적으로 회의에서 빠질 수 있습니다.","위원 본인이 제척·기피 사유에 해당하면 스스로 심의·의결을 회피할 수 있다":"위원은 자신에게 제척이나 기피 사유가 있다고 판단하면 스스로 심의에서 빠질 수 있습니다.","위원은 정당에 가입하거나 정치운동에 관여할 수 없다":"위원은 정치적 중립을 위해 정당에 가입하거나 정치운동을 할 수 없습니다.","위원은 조정원의 장의 제청으로 공정거래위원회 위원장이 임명하거나 위촉한다":"협의회 위원 선임은 조정원 장이 후보를 내면 공정거래위원회 위원장이 임명하거나 위촉하는 구조입니다.","위원은 조정원의 장의 제청으로 공정거래위원회 위원장이 임명하거나 위촉한다(약관규제·소비자 분야 경험·전문지식이 있는 사람: 4급 이상 공무원 경력자, 판사·검사·변호사 자격자, 부교수 이상 대학 교원, 기업경영·소비자권익·분쟁조정 학식·경험자)":"약관 규제나 소비자 분야 전문성을 갖춘 공무원과 법조인, 교수, 실무 경험자 중에서 조정원 장의 제청으로 선임합니다.","위원 임기는 3년이며 연임할 수 있다":"위원의 임기는 삼 년이고 연임도 가능합니다.","위원장, 부위원장 및 다른 위원 모두 3년이며 한 차례만 연임할 수 있다":"위원장과 부위원장, 나머지 위원 모두 임기가 삼 년이고 한 번만 연임할 수 있습니다.","위원장 1명, 부위원장 1명을 포함하여 11명, 그중 5명은 비상임위원 (2023·2025 기출 당시 9명, 비상임 4명)":"위원회는 위원장과 부위원장을 포함해 열한 명이고 그중 다섯 명이 비상임위원입니다.","위원장 1명을 포함한 9명의 위원으로 구성한다":"협의회는 위원장 한 명을 포함해 아홉 명의 위원으로 구성합니다.","위원장과 부위원장은 국무총리의 제청으로 대통령이 임명한다":"위원장과 부위원장의 임명권자는 대통령이며 국무총리의 제청을 거친다는 절차가 붙습니다.","위원장과 부위원장은 정무직이다":"위원장과 부위원장의 신분은 정무직 공무원입니다.","위원장 또는 위원장이 지명하는 위원이 주재하며 구성위원 전원의 출석과 출석위원 전원의 찬성으로 의결한다":"분과회의는 구성위원 전원이 출석하고 출석위원 전원이 찬성해야 의결됩니다.","위원장·부위원장·사무처장은 정부위원이 된다":"위원장과 부위원장, 사무처장은 국회에서 정부를 대표해 발언하는 정부위원이 됩니다.","위원장은 공정거래위원회를 대표하며 국무회의에 출석하여 발언할 수 있다":"위원장은 위원회를 대표하고 국무회의에 출석해 발언할 수 있습니다.","위원장은 국회 인사청문을 거친다":"위원장은 임명 전에 국회의 인사청문 절차를 거칩니다.","위원장은 위원 중에서 조정원의 장의 제청으로 공정거래위원회 위원장이 위촉한다":"협의회 위원장은 위원 가운데서 조정원 장이 제청하면 공정거래위원회 위원장이 위촉합니다.","위원장은 위원회 의결을 거치지 않고 기피 여부를 결정한다":"기피 여부는 위원회 의결 없이 위원장이 직접 결정합니다.","위원장은 조정원의 장의 제청으로 공정거래위원회 위원장이 위촉한다":"협의회 위원장은 조정원 장이 제청하면 공정거래위원회 위원장이 위촉합니다.","위원장은 직무 외에 영리를 목적으로 하는 업무에 종사하지 못한다":"약관 분쟁조정협의회 위원장도 영리 업무에는 종사할 수 없습니다.","위원장은 회의를 소집하고 의장이 된다":"협의회 위원장은 회의를 소집하고 회의를 이끄는 의장을 맡습니다.","위원장이 사고로 직무를 수행할 수 없으면 위원장이 지명하는 협의회 위원이 대행한다":"위원장이 사고로 직무를 못 하면 위원장이 미리 지명한 협의회 위원이 대신합니다.","위원장이 소회의 구성위원을 지정하고 분장업무를 지정·변경할 수 있다":"소회의에 누가 들어가고 어떤 사건을 맡을지는 위원장이 지정하고 바꿀 수 있습니다.","위원장이 주재하며 재적위원 과반수의 찬성으로 의결한다 (현행 조문에는 별도의 출석 정족수가 없다)":"전원회의는 위원장이 주재하고 재적위원 과반수가 찬성하면 의결되며 따로 출석 정족수는 없습니다.","위원장이 주재하며 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다 (3분의 2가 아니다)":"전체회의는 재적위원 과반수의 출석과 출석위원 과반수의 찬성으로 의결하며 삼분의 이가 아닙니다.","위원장이 직무를 수행할 수 없으면 공정거래위원회 위원장이 지명하는 위원이 대행한다":"협의회 위원장의 직무가 불가능하면 공정거래위원회 위원장이 지명한 위원이 대신합니다.","위원장이 직무를 수행할 수 없으면 부위원장이, 둘 다 불가능하면 선임상임위원 순으로 대행한다":"위원장이 직무를 못 하면 부위원장이, 둘 다 못 하면 선임 상임위원 순으로 대행합니다.","위원 전원으로 구성되는 전체회의, 위원장이 지명하는 3명(위원장 포함 가능)으로 구성되는 분과회의":"회의는 위원 전원의 전체회의와 위원장이 지명하는 세 명으로 구성하는 분과회의가 있습니다.","위원 전원으로 구성하는 전원회의, 상임위원 1명을 포함하여 위원 3명으로 구성하는 소회의":"회의는 위원 전원이 모이는 전원회의와 상임위원 한 명을 포함해 세 명이 하는 소회의로 나뉩니다.","위원 전원이 아니라 조정에 참가한 위원이다":"조정조서에 서명하는 위원은 협의회 전원이 아니라 실제로 조정에 참가한 위원입니다.","위탁매매 형식이라는 이유만으로 모든 거래에 대해 재판매가격유지행위가 허용되지는 않는다":"계약 형식이 위탁매매라는 이유만으로 모든 거래에서 가격 구속이 허용되는 것은 아닙니다.","위탁받은 기관은 이행관리 현황을 분기별로 보고하고, 신청인이 이행을 게을리하면 지체 없이 통보한다":"위탁받은 기관은 이행관리 현황을 분기마다 보고하고 신청인이 게을리하면 곧바로 알립니다.","유효한 부분만으로 목적 달성이 가능하면 계약 전체가 무효로 되지 않는다":"유효한 부분만으로 계약 목적을 이룰 수 있다면 계약이 전체로 무효가 되지 않습니다.","은행법에 따른 은행의 약관이 불공정약관에 해당한다고 인정하면 금융감독원에 통보하고 시정에 필요한 조치를 권고할 수 있다":"은행 약관이 불공정하다고 인정되면 금융감독원에 통보하고 시정 조치를 권고할 수 있습니다.","의견을 받은 관계 행정기관의 장은 검토 후 결과를 공정거래위원회에 송부하여야 한다":"의견을 받은 행정기관은 이를 검토한 결과를 공정거래위원회에 보내야 합니다.","의결 내용 및 이유를 명시하고 의결에 참여한 위원이 서명날인한다":"의결서에는 결론과 이유를 적고 의결에 참여한 위원이 서명날인합니다.","의결서 등에 오기, 계산착오, 그 밖에 유사한 오류가 명백한 경우 신청이나 직권으로 경정할 수 있다":"의결서에 명백한 오기나 계산 착오가 있으면 신청이나 직권으로 고칠 수 있습니다.","의결의 합의는 공개하지 않는다":"결론을 정하는 합의 과정은 심리와 달리 공개하지 않습니다.","이 경우 분쟁당사자 간에 조정조서와 동일한 내용의 합의가 성립된 것으로 본다":"조정조서를 쓰면 당사자들 사이에 그 조서와 같은 내용의 합의가 이루어진 것으로 인정합니다.","이때 다른 사업자와 공동불법행위자(민법 제760조)로서 그 범위에서 책임진다":"감면 사업자도 그 범위에서는 다른 사업자와 공동불법행위자로 함께 책임을 집니다.","이를 통해 공정하고 자유로운 경쟁을 촉진한다":"규제 수단은 궁극적으로 시장에서 공정하고 자유로운 경쟁이 이루어지게 하려는 것입니다.","이를 통해 소비자를 보호하고 국민생활을 균형 있게 향상시킨다":"약관 규제의 궁극적 목적은 소비자 보호와 국민생활의 균형 있는 향상입니다.","이 법에 따른 직무에 종사하거나 종사하였던 위원·공무원, 분쟁조정업무 담당자, 동의의결 이행관리 담당자, 시정조치 이행관리 담당자는 직무상 알게 된 사업자·사업자단체의 비밀을 누설하거나 이 법 시행 목적 외에 이용해서는 안 된다":"직무를 맡았거나 맡았던 사람은 업무상 알게 된 사업자의 비밀을 누설하거나 목적 외로 쓰면 안 됩니다.","이 법 위반 의결은 심리를 종결하는 날까지 발생한 사실을 기초로 판단한다":"위반 여부는 심리를 마치는 날까지 있었던 사실을 근거로 판단합니다.","이 법은 약관에 관한 일반법이다":"약관법은 모든 약관에 적용되는 일반법의 지위에 있습니다.","이 법의 적용대상이 아닌 사안에 관해 신청한 경우":"공정거래법의 적용 대상이 아닌 사안으로 신청한 것도 각하 사유입니다.","이사, 대표이사, 업무집행을 하는 무한책임사원, 감사, 이들에 준하는 사람, 지배인 등 본점이나 지점의 영업 전반을 총괄적으로 처리할 수 있는 상업사용인":"임원은 이사와 감사, 업무집행 사원 등 경영진과 영업 전반을 총괄할 수 있는 지배인 등 상업사용인까지 포함합니다.","이의신청, 소송 제기, 불복 소송의 전속관할에는 공정거래법 제96조~제98조, 제98조의2, 제98조의3, 제99조~제101조를 준용한다":"이의신청과 불복 소송, 전속관할에 관해서도 공정거래법의 절차 규정을 빌려 적용합니다.","이의신청 서류 보완에 걸리는 기간은 재결기간에 산입하지 않는다":"서류를 보완하는 데 걸린 기간은 재결기간에 넣지 않고 빼고 셉니다.","이의신청을 받은 날부터 60일 이내에 하여야 한다":"이의신청에 대한 재결은 신청을 받은 날부터 육십 일 안에 내려야 합니다.","이의신청 재결 또는 법원 판결 등으로 환급하면 납부한 날부터 환급한 날까지 환급가산금을 지급하여야 한다":"재결이나 판결로 과징금을 돌려줄 때는 납부한 날부터 환급한 날까지의 가산금도 함께 지급해야 합니다.","이 중 한 부류 이상이 1명 이상 포함되어야 한다":"위원 구성에서는 여러 자격 부류 중 일정 부류 이상이 각각 한 명 이상 들어가야 합니다.","이해관계인 의견 청취를 위해 30일 이내 공시할 수 있다":"이해관계인 의견을 듣기 위해 신청 내용을 삼십 일 이내의 기간 동안 공시할 수 있습니다.","이해관계인·참고인을 출석하게 하거나 감정인을 위촉하면 예산 범위에서 필요한 경비를 지급할 수 있다":"출석시키거나 위촉한 사람에게는 예산 범위에서 필요한 경비를 줄 수 있습니다.","이해관계자만 신고할 수 있는 것이 아니다":"피해를 입은 이해관계자에 한하지 않고 제삼자도 위반 사실을 신고할 수 있습니다.","이행강제금은 기재사항이 아니다":"권고서의 기재사항에는 이행강제금이 들어 있지 않습니다.","이행관리 업무는 한국공정거래조정원 또는 한국소비자원에 위탁할 수 있다":"동의의결의 이행 점검은 공정거래위원회가 직접 하지 않고 조정원이나 소비자원에 맡길 수도 있습니다.","인가된 공동행위가 폐지되면 공동행위대표사업자가 지체 없이 공정거래위원회에 알려야 한다":"인가받은 공동행위가 없어지면 대표사업자가 바로 공정거래위원회에 알려야 합니다.","인가를 받으면 제1항이 적용되지 않는 목적: 불황극복을 위한 산업구조조정, 연구·기술개발, 거래조건의 합리화, 중소기업의 경쟁력향상":"인가를 받으면 담합 금지가 적용되지 않는 목적은 불황 극복 구조조정, 연구개발, 거래조건 합리화, 중소기업 경쟁력 향상입니다.","인력을 상당히 낮거나 높은 대가로 또는 상당한 규모로 제공·거래":"인력을 상당히 낮거나 높은 대가로 또는 상당한 규모로 제공하는 부당한 인력지원입니다.","일반 공중에게 물품·용역을 공급하는 계약으로서 체결의 긴급성·신속성 때문에 고객이 약관 조항 내용을 변경하기 곤란한 경우":"일반 공중 대상 계약으로 체결이 급하고 빨라 고객이 약관 내용을 바꾸기 어려운 경우도 시정명령 사유입니다.","일정한 거래분야에서 경쟁을 실질적으로 제한하는 기업결합은 금지":"경쟁을 실질적으로 제한하는 기업결합은 원칙적으로 해서는 안 됩니다.","일정한 거래분야에서 연간 매출액 또는 구매액이 80억원 미만인 사업자는 추정에서 제외한다 (2021 기출 당시 40억원)":"연간 매출액이나 구매액이 팔십억 원 미만인 사업자는 점유율이 높아도 추정에서 제외됩니다.","일정한 거래분야에서 현재 또는 장래의 사업자 수를 제한하는 행위":"현재나 앞으로 시장에 있을 사업자 수를 제한하는 행위가 두 번째 금지행위입니다.","일정한 거래분야의 경쟁이 감소하여 특정 사업자 또는 사업자단체의 의사에 따라 어느 정도 자유로이 가격, 수량, 품질, 그 밖의 거래조건 등의 결정에 영향을 미치거나 미칠 우려가 있는 상태를 초래하는 행위":"경쟁이 줄어 특정 사업자의 뜻대로 가격이나 수량 같은 조건을 어느 정도 좌우할 수 있는 상태를 만드는 행위입니다.","일정한 거래분야의 공급자나 수요자로서 단독으로 또는 다른 사업자와 함께 상품·용역의 가격, 수량, 품질, 그 밖의 거래조건을 결정·유지·변경할 수 있는 시장지위를 가진 사업자":"시장지배적사업자는 거래분야에서 혼자나 함께 가격과 수량, 품질 같은 조건을 좌우할 수 있는 지위의 사업자입니다.","일정한 거래분야의 공정한 거래질서 확립을 위해 서면실태조사를 하고 결과를 공표할 수 있다":"공정한 거래질서를 위해 서면으로 실태를 조사하고 그 결과를 공표할 수 있습니다.","일정한 작위·부작위가 있을 때 고객의 의사표시가 표명되거나 표명되지 않은 것으로 보는 조항":"어떤 행동이나 무행동이 있으면 고객의 의사표시가 있거나 없는 것으로 간주하는 의사표시 의제 조항입니다.","일정한 조합의 행위에는 적용하지 않는다":"일정한 요건을 갖춘 조합이 하는 행위는 이 법의 적용을 받지 않는 적용제외 사유입니다.","임의로 설립되고 조합원이 임의로 가입하거나 탈퇴할 수 있을 것":"설립이 자유롭고 가입과 탈퇴도 조합원 마음대로 할 수 있어야 한다는 요건입니다.","임직원에게 상품을 수여하는 신규 구독자 확장계획을 수립·시행한 것도 사원판매에 해당하지 않는다고 본 사례가 있다":"임직원에게 상품을 주면서 신규 구독자 확장 계획을 시행한 것도 사원판매로 보지 않은 사례입니다.","임직원에게 자사 상품 구매자 확대를 촉구·독려하는 것만으로는 사원판매가 아니다":"구매자를 늘리라고 독려하는 정도로는 강제로 사고팔게 한 것이 아니어서 사원판매가 아닙니다.","입증책임은 가해 사업자에게 있다":"고의나 과실이 없었다는 입증은 피해자가 아니라 가해 사업자가 부담합니다.","입찰가격 결정에 필요한 정보를 주고받은 둘 이상의 사업자는 입찰담합을 합의한 것으로 추정한다":"서로 입찰가격 관련 정보를 주고받은 사실만 있어도 입찰 담합 합의가 있었다고 법이 미리 추정합니다.","입찰담합 및 유사 행위는 계약금액":"입찰담합과 비슷한 행위에서는 매출액 대신 계약금액을 기준으로 삼습니다.","입찰담합 및 이와 유사한 행위의 매출액은 계약금액을 매출액으로 본다":"입찰담합의 매출액은 낙찰받은 계약금액을 기준으로 합니다.","입찰 또는 경매에서 낙찰자, 경락자, 입찰가격, 낙찰가격 또는 경락가격, 그 밖에 대통령령으로 정하는 사항을 결정하는 행위":"입찰담합은 낙찰자나 입찰가격 같은 입찰의 핵심 사항을 미리 정하는 행위입니다.","입찰에서 들러리를 서주는 등 입찰행위 실행에 묵시적으로 동의한 경우에도 공동행위가 성립한다":"들러리를 서는 것처럼 입찰 실행에 묵시적으로 동의했다면 그것도 공동행위입니다.","자기가 공급하는 상품·용역과 관련하여 거래상대방의 거래에 관한 목표를 제시하고 이를 달성하도록 강제":"거래상대방에게 판매 목표를 정해 주고 달성하도록 강제하는 판매목표강제입니다.","자기·배우자(였던 사람)가 분쟁당사자이거나 공동권리자·의무자, 분쟁당사자와 친족, 자문·고문, 증언·감정, 대리인 관여":"위원 본인이나 배우자가 당사자이거나 친족, 자문, 증언, 대리인 관여 등이 있으면 해당 분쟁에서 배제됩니다.","자기의 거래상의 지위를 부당하게 이용하여 상대방과 거래하는 행위(거래상 지위의 남용)":"여섯 번째는 거래상 우월한 지위를 부당하게 이용해 거래하는 거래상 지위의 남용입니다.","자기의 상품·용역을 공급하면서 정당한 이유 없이 공급에 소요되는 비용보다 현저히 낮은 가격으로 계속 공급하거나, 그 밖에 부당하게 낮은 가격으로 공급하여 자기 또는 계열회사의 경쟁사업자를 배제시킬 우려가 있는 행위":"비용보다 크게 낮은 가격으로 계속 팔아 경쟁사업자를 몰아낼 우려가 있는 부당염매입니다.","자동차부분정비사업자 사업자단체가 구성사업자들에게 특정 지정폐기물 처리업체를 통해서만 처리하도록 강제하고 따르지 않는 구성사업자를 제명한 행위는 제3호에 해당한다":"특정 처리업체만 이용하도록 강제하고 따르지 않는 구성원을 제명한 것은 구성사업자 활동 제한에 해당합니다.","자료를 제출한 자의 동의 여부와 상관없이 모든 자료에 응해야 하는 것이 아니다":"제출자가 동의하지 않았다고 해서 모든 자료를 열람시켜 줘야 하는 것은 아닙니다.","자료·물건 제출 명령은 사건명, 보고·제출 일시, 보고·제출할 사항이 포함된 서면으로 한다":"제출 명령은 사건명과 제출 일시, 제출할 사항을 적은 서면으로 하는 것이 원칙입니다.","자본총액의 2배 초과 부채 보유 금지, 자회사 주식 100분의 50 미만 소유 금지(상장·국외상장·공동출자법인은 30, 벤처지주회사의 자회사는 20), 계열회사 아닌 국내 회사 주식 5% 초과 소유 금지, 금융지주회사의 비금융 국내 회사 주식 소유 금지, 일반지주회사의 금융·보험 국내 회사 주식 소유 금지":"지주회사에는 부채 비율, 자회사 지분율, 비계열사 주식, 금융과 비금융 겸영에 관한 행위 제한이 있습니다.","자산총액 5조원 이상인 기업집단으로 공정거래위원회가 지정":"공시대상기업집단은 자산총액이 오조 원 이상인 기업집단을 공정거래위원회가 지정한 것입니다.","자진신고 감면 사업자(제44조 제1항 해당)의 손해배상액은 해당 사업자가 제40조 위반으로 손해를 입은 자에게 끼친 손해를 초과할 수 없고, 다른 사업자와 공동불법행위자로서 그 범위에서 책임을 진다":"감면받은 자는 자기가 끼친 손해를 넘는 배상은 하지 않으며 그 범위에서만 다른 사업자와 공동 책임을 집니다.","자진신고 관련 자료는 자료 열람·복사 요구 제외 대상이다":"자진신고와 관련한 자료는 사건 관계자가 열람이나 복사를 요구할 수 있는 대상에서 빠집니다.","자진신고자의 순서에 따라 감면 혜택에 차이가 있다":"먼저 신고하거나 협조한 순서에 따라 받을 수 있는 감면의 폭이 달라집니다.","자진신고·조사협조 감면 사업자는 배상액이 제40조 위반으로 손해를 입은 자에게 발생한 손해를 초과할 수 없다":"자진신고 등으로 감면받은 사업자의 배상액은 피해자가 입은 실제 손해를 넘지 않도록 제한됩니다.","자회사는 지주회사의 지배를 받는 국내 회사, 손자회사는 자회사의 지배를 받는 국내 회사":"지주회사가 직접 지배하는 회사가 자회사이고 그 자회사가 지배하는 회사가 손자회사입니다.","재판관할 합의 조항 자체가 이 법의 적용대상에서 제외되는 것은 아니다":"재판관할을 합의하는 조항도 약관법의 규제 대상에 포함됩니다.","재판매가격유지행위 관련 분쟁조정 신청·신고·조사협조를 이유로 한 보복조치는 금지된다":"재판매가격유지행위에 관한 신고나 조사 협조를 이유로 한 보복도 금지됩니다.","재판매가격유지행위의 중지 및 재발방지를 위한 조치, 보복조치 금지, 계약조항의 삭제, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치":"재판매가격유지에 대한 시정조치는 중지와 재발방지, 보복조치 금지, 계약조항 삭제, 시정명령 사실 공표입니다.","재판에서 조사과정 진술이나 제출 자료의 중요한 내용을 부정하는 경우, 진술·자료가 재판에서 거짓으로 밝혀진 경우, 정당한 이유 없이 진술하지 않거나 출석하지 않는 경우, 자진신고 사실을 부인하는 소를 제기하는 경우":"재판에서 진술을 뒤집거나 거짓으로 밝혀지거나 불출석하는 등 협조 의무를 저버리면 감면이 취소됩니다.","저작권법, 특허법, 실용신안법, 디자인보호법, 상표법에 따른 권리의 정당한 행사라고 인정되는 행위에는 적용하지 않는다":"지식재산권법에 따른 권리를 정당하게 행사하는 행위는 이 법이 적용되지 않는 무체재산권 행사행위입니다.","저작권법 제2조 제1호에 따른 저작물 중 관계 중앙행정기관의 장과 협의를 거쳐 공정거래위원회가 고시하는 출판된 저작물(전자출판물 포함)":"저작권법상 저작물 중 협의를 거쳐 공정거래위원회가 고시한 출판물은 전자출판물까지 허용 대상입니다.","전원회의 및 소회의 의장은 심판정에 출석하는 당사자·이해관계인·참고인·참관인 등에게 질서유지를 위해 필요한 조치를 명할 수 있다":"회의 의장은 심판정에 나온 사람들에게 질서 유지에 필요한 조치를 명할 수 있습니다.","전화·구두나 법원 제출은 안 된다":"전화나 말로 하거나 법원에 내는 방식은 심사청구로 인정되지 않습니다.","전후방 연관 계열회사 간 부품·소재 거래, 기획·생산·판매에 필수적인 서비스를 산업연관성 높은 계열회사에서 공급받는 거래, 일부 사업을 전문 계열회사가 전담하는 경우의 거래, 협업체계가 이미 구축된 거래, 전문 지식·인력·연속적 사업과의 밀접한 연관성·신뢰성을 고려한 계열회사 거래":"전후방 부품 거래나 전문 계열회사 전담 같은 거래는 효율성 증대를 위해 불가피한 거래로 인정되는 예입니다.","정당한 이유가 있는지의 증명책임은 사업자에게 있다":"정당한 이유가 있다는 점은 재판매가격유지를 한 사업자가 입증해야 합니다.","정당한 이유 없이 가격을 수급 변동이나 공급 비용(같은 종류 또는 유사 업종의 통상 수준) 변동에 비해 현저하게 상승시키거나 근소하게 하락시키는 행위":"수급이나 비용 변동에 비해 가격을 크게 올리거나 조금만 내리는 행위가 가격 남용입니다.","정당한 이유 없이 거래하는 유통사업자와 배타적 거래계약을 체결하는 행위":"자신과 거래하는 유통업자와 배타적 거래를 맺어 신규 경쟁자가 유통망에 들어오지 못하게 하는 참가 방해입니다.","정당한 이유 없이 경쟁관계에 있는 다른 사업자와 공동으로 특정사업자에게 거래개시를 거절하거나 계속적 거래관계에 있는 특정사업자에게 거래를 중단하거나 수량·내용을 현저히 제한":"경쟁 사업자와 함께 특정 사업자와의 거래를 거절하거나 끊거나 크게 줄이는 공동의 거래거절입니다.","정당한 이유 없이 기존 사업자의 계속적인 사업활동에 필요한 권리 등을 매입하는 행위":"기존 사업자가 사업을 이어 가는 데 필요한 권리를 사들여 신규 진입을 막는 것도 참가 방해입니다.","정당한 이유 없이 다른 사업자의 상품·용역의 생산·공급·판매에 필수적인 요소의 사용 또는 접근을 거절·중단하거나 제한하는 행위":"사업에 꼭 필요한 요소의 사용이나 접근을 막는 것은 기존 사업자에 대해서는 사업활동 방해입니다.","정당한 이유 없이 다른 사업자의 생산활동에 필요한 원재료 구매를 방해하는 행위":"경쟁 사업자가 생산에 쓸 원재료를 사지 못하도록 방해하는 것은 사업활동 방해입니다.","정당한 이유 없이 새로운 경쟁사업자의 상품·용역의 생산·공급·판매에 필수적인 요소의 사용 또는 접근을 거절하거나 제한하는 행위":"새로 진입하려는 경쟁사업자에게 필수 요소의 사용을 거절하는 것이 참가 방해의 한 유형입니다.","정당한 이유 없이 유통단계에서 공급부족이 있음에도 공급량을 감소시키는 행위":"유통 단계에서 이미 물량이 부족한데도 공급을 더 줄이는 것도 부당한 출고조절입니다.","정당한 이유 없이 이행기한까지 이행하지 않은 자에게 이행되거나 취소되기 전까지 이행기한 다음 날부터 1일당 200만원 이하":"이행기한을 넘긴 날부터 이행하거나 취소될 때까지 하루에 이백만 원 이하의 이행강제금을 부과합니다.","정당한 이유 없이 자기 계열회사를 유리하게 하기 위해 가격·수량·품질 등 거래조건이나 거래내용을 현저하게 유리하거나 불리하게 하는 행위":"계열회사를 돕기 위해 거래 조건을 계열회사에는 유리하게, 다른 사업자에는 불리하게 하는 차별입니다.","정당한 이유 없이 자료제출명령에 따르지 않으면 법원은 자료 기재에 대한 상대방의 주장을 진실한 것으로 인정할 수 있다":"정당한 이유 없이 자료를 내지 않으면 그 자료에 관한 상대방의 주장을 진실한 것으로 인정할 수 있습니다.","정당한 이유 없이 최근의 추세에 비추어 상품·용역의 공급량을 현저히 감소시키는 행위":"최근 추세와 비교해 공급량을 크게 줄이면 부당한 출고조절이 될 수 있습니다.","정부는 대한민국의 법률 및 이익에 반하지 않는 범위에서 외국정부와 이 법의 집행을 위한 협정을 체결할 수 있다":"정부는 우리 법과 이익에 어긋나지 않는 한 외국 정부와 집행에 관한 협정을 맺을 수 있습니다.","정부는 외국정부와 이 법의 집행을 위한 협정을 체결할 수 있고, 공정거래위원회는 협정에 따라 외국정부의 법집행을 지원할 수 있다":"정부가 외국과 집행 협정을 맺으면 공정거래위원회는 그 협정에 따라 외국의 법집행을 지원할 수 있습니다.","정부조직법상 중앙행정기관으로서 소관 사무를 수행한다":"정부조직법상 중앙행정기관의 지위에서 법이 정한 소관 사무를 처리합니다.","정상 거래 조건과의 차이가 100분의 7 미만이고 거래당사자 간 해당 연도 거래총액이 50억원(상품·용역은 200억원) 미만이면 상당히 유리한 조건이 아니다":"조건 차이가 백분의 칠 미만이고 연간 거래총액이 기준액 미만이면 상당히 유리한 조건으로 보지 않습니다.","정상 거래 조건과의 차이가 100분의 7 미만이고 해당 연도 거래총액이 50억원 미만이면 상당히 유리한 조건이 아니다":"현금이나 금융상품 거래도 차이가 백분의 칠 미만이고 연 거래총액이 오십억 원 미만이면 규제를 피합니다.","정상적인 거래관행에 비추어 부당하거나 과대한 이익을 제공하거나 제공할 제의를 하여 경쟁사업자의 고객을 자기와 거래하도록 유인":"정상 관행을 넘는 과대한 이익을 주거나 제안해 경쟁사업자의 고객을 끌어오는 행위입니다.","정상적인 거래관행에 비추어 부당한 조건 등 불이익을 제시하여 자기 또는 자기가 지정하는 사업자와 거래하도록 강제하는 행위":"불이익을 내걸어 자기나 지정한 사업자와 거래하게 만드는 그 밖의 거래강제입니다.","정상적인 거래에서 적용되거나 적용될 것으로 판단되는 조건보다 상당히 유리한 조건으로 거래하는 행위":"정상 거래 조건보다 훨씬 유리한 조건으로 특수관계인과 거래하는 것이 첫째 유형입니다.","정상적인 관행에 따른 채용은 금지되지 않는다":"정상적인 관행 범위 안에서 인력을 채용하는 것은 방해행위로 금지되지 않습니다.","정상적인 관행에 비추어 과도한 경제상 이익을 제공하거나 약속하면서 다른 사업자의 사업활동에 필수적인 인력을 채용하는 행위":"정상 관행보다 과도한 이익을 내걸어 다른 사업자의 핵심 인력을 빼 오는 행위가 방해에 해당합니다.","제124조·제125조의 죄는 공정거래위원회의 고발이 있어야 공소를 제기할 수 있다(전속고발)":"무거운 두 벌칙 조항의 죄는 공정거래위원회가 고발해야 공소를 제기할 수 있는 전속고발입니다.","제17조를 위반한 사업자에게 해당 불공정약관조항의 삭제·수정 등 시정에 필요한 조치를 권고할 수 있다":"불공정약관을 사용한 사업자에게 해당 조항의 삭제나 수정 등 시정에 필요한 조치를 권고할 수 있습니다.","제17조 위반 약관 등으로 피해가 발생했고, 합의한 고객·중재 진행 중인 고객·소를 제기한 고객을 제외한 피해 고객이 20명 이상일 것":"불공정약관으로 피해가 났고 합의나 중재, 소송을 한 고객을 뺀 피해 고객이 이십 명 이상이어야 합니다.","제17조 위반 약관 등으로 피해를 입은 고객이 분쟁조정 신청서를 협의회에 제출":"불공정약관으로 피해를 입은 고객이 분쟁조정 신청서를 협의회에 제출해 조정을 신청합니다.","제17조의2 제2항에 따른 명령을 이행하지 않은 자: 2년 이하의 징역 또는 1억원 이하의 벌금":"시정명령에 해당하는 명령을 따르지 않으면 이 년 이하 징역 또는 일억 원 이하 벌금입니다.","제1항 각 호의 행위(제9호 중 정보교환으로 경쟁을 실질적으로 제한하는 행위는 제외)에 필요한 정보를 주고받은 때":"공동행위에 필요한 정보를 주고받았다면 합의가 있었던 것으로 추정되며 제외되는 것은 정보교환 유형입니다.","제1항에 따라 행정관청에 시정을 요청한 경우 공정거래위원회는 제17조의2 제1항·제2항의 시정권고·시정명령을 하지 않는다":"관청에 시정을 요청했다면 같은 사항에 대해 공정거래위원회가 직접 시정권고나 시정명령을 하지 않습니다.","제1호 사유로 취소하면 신청인이 다시 신청할 수 있다":"사정 변경 때문에 취소된 경우에는 신청인의 잘못이 없어 다시 동의의결을 신청할 수 있습니다.","제1호 위반 참가 사업자는 100분의 20(40억원), 제2~4호 위반 참가 사업자는 100분의 10(20억원)":"단체의 금지행위에 참가한 사업자는 유형에 따라 매출액의 백분의 이십이나 백분의 십이 한도입니다.","제1호 위반 행위에 참가한 사업자에 매출액 100분의 20 이하(매출액이 없는 경우 등 40억원 이하)":"경쟁제한 행위에 참가한 사업자에게는 매출액의 백분의 이십 이하, 매출이 없으면 사십억 원 이하입니다.","제1호의 인가에 관하여는 제40조 제2항·제3항을 준용한다('사업자'는 '사업자단체'로 본다)":"경쟁 제한 금지행위의 인가는 담합 인가 규정을 준용하며 사업자를 사업자단체로 읽습니다.","제1호 행위는 사업자단체의 의사결정만으로 성립한다":"경쟁제한 행위는 단체가 의사결정을 한 시점에 성립하며 이후 집행은 별개의 문제입니다.","제2호~제4호 위반 행위에 참가한 사업자에 매출액 100분의 10 이하(매출액이 없는 경우 등 20억원 이하)":"나머지 금지행위에 참가한 사업자에게는 매출액의 백분의 십 이하, 매출이 없으면 이십억 원 이하입니다.","제2호·제3호 사유로 취소하면 중단된 심의절차를 계속 진행할 수 있다":"거짓 정보나 불이행으로 취소되면 중단했던 심의를 다시 이어서 진행할 수 있습니다.","제3항 또는 제4항의 고발요청이 있으면 공정거래위원회는 고발하여야 한다":"검찰총장 등이나 다른 기관의 고발 요청이 있으면 공정거래위원회는 반드시 고발해야 합니다.","제3항·제4항의 사무는 대통령령으로 정하는 바에 따라 다른 기관에 위탁할 수 있다":"조사와 자료 요청 같은 사무는 시행령이 정한 바에 따라 다른 기관에 위탁할 수 있습니다.","제40조(부당한 공동행위), 제48조(보복조치), 제51조 제1항 제1호(사업자단체의 공동행위 방식 경쟁제한) 위반":"담합과 보복조치, 사업자단체의 경쟁제한 위반은 삼 배 배상 제도가 적용되는 대상입니다.","제40조 제1항 각 호의 행위(부당한 공동행위 유형)로 부당하게 경쟁을 제한하는 행위":"사업자단체가 담합 유형에 해당하는 행위로 경쟁을 부당하게 제한하는 것이 첫 번째 금지행위입니다.","제45조 제1항(제9호 제외), 제46조, 제48조 위반 사업자에게 관련매출액 100분의 4 이하":"지원행위를 뺀 불공정거래행위와 재판매가격유지 등 위반에는 관련매출액의 백분의 사 이하를 부과합니다.","제45조 제1항(제9호 제외) 위반으로 피해를 입거나 입을 우려가 있는 자는 위반행위를 하거나 할 우려가 있는 사업자(사업자단체)에 침해행위의 금지·예방을 청구할 수 있다":"불공정거래행위로 피해를 입었거나 입을 우려가 있는 자는 법원에 금지와 예방을 청구할 수 있습니다.","제45조 제1항 위반(제1호·제2호·제3호·제7호·제9호 제외)의 불공정거래행위는 2년 이하의 징역 또는 1억5천만원 이하의 벌금":"일부 유형을 뺀 그 밖의 불공정거래행위는 이 년 이하 징역 또는 일억오천만 원 이하 벌금입니다.","제45조 제1항 위반 혐의 행위 관련 분쟁 조정, 다른 법률상 분쟁 조정, 시장·산업 동향과 공정경쟁 조사·분석, 사업자 거래관행 조사·분석, 동의의결 이행관리, 시정조치 이행관리, 제도·정책 연구·건의, 위탁받은 사업":"조정원은 분쟁조정과 시장 및 거래관행 조사와 분석, 이행관리, 제도 연구, 위탁받은 사업을 맡습니다.","제45조 제1항을 위반한 혐의가 있는 행위로 피해를 입은 사업자가 분쟁조정신청서를 협의회에 제출":"불공정거래행위로 피해를 입은 사업자가 분쟁조정신청서를 협의회에 내어 조정을 신청합니다.","제45조 제1항을 위반한 혐의가 있는 행위와 관련된 분쟁을 조정하기 위해 조정원에 공정거래분쟁조정협의회를 둔다":"불공정거래행위 관련 분쟁을 조정하기 위해 조정원에 공정거래분쟁조정협의회를 둡니다.","제45조 제1항 제9호(부당한 지원행위) 또는 제2항(지원받는 행위), 제47조 제1항·제3항 위반 시 해당 특수관계인 또는 회사에 평균매출액 100분의 10 이하":"부당한 지원이나 지원받는 행위, 사익편취 위반은 평균매출액의 백분의 십 이하까지 과징금이 가능합니다.","제45조 제1항 제9호 위반은 3년 이하의 징역 또는 2억원 이하의 벌금":"부당한 지원행위를 하면 삼 년 이하 징역 또는 이억 원 이하 벌금에 처해집니다.","제46조 위반은 형사처벌 규정(제124조·제125조) 대상 조문에 열거되어 있지 않다":"재판매가격유지 위반은 형사처벌 조항이 적용되는 조문 목록에 들어 있지 않습니다.","제47조 위반은 해당 특수관계인 또는 회사에 명한다":"시정조치는 위반한 특수관계인이나 회사를 상대로 명령합니다.","제47조 제1항·제3항 위반 시 해당 특수관계인 또는 회사에 평균매출액(직전 3개 사업연도 평균)에 100분의 10을 곱한 금액 이하":"과징금은 직전 세 사업연도 평균매출액에 백분의 십을 곱한 금액 이하로 해당 특수관계인이나 회사에 부과합니다.","제47조 제1항·제4항을 위반한 자: 3년 이하의 징역 또는 2억원 이하의 벌금":"해당 조항을 위반한 자에 대한 벌칙은 삼 년 이하 징역 또는 이억 원 이하 벌금입니다.","제4호·제5호 사유로 결손처분하면 체납처분을 중지하고 압류를 해제한다":"재산이 남을 여지가 없다는 사유로 결손처분하면 체납처분을 중지하고 이미 한 압류를 풀어 줍니다.","제4호 해당 여부는 공정거래위원회의 확인을 받는다":"조사가 이미 개시되었는지의 판단은 협의회가 아니라 공정거래위원회의 확인을 받아 정합니다.","제51조 제1항 위반 사업자단체에 10억원의 범위":"금지행위를 한 사업자단체에는 십억 원의 범위에서 과징금을 부과합니다.","제51조 제1항 제1호 위반은 3년 이하의 징역 또는 2억원 이하의 벌금":"사업자단체가 경쟁을 부당하게 제한하는 행위를 하면 삼 년 이하 징역 또는 이억 원 이하 벌금입니다.","제7조~제14조 적용이 제한되는 업종: ① 국제적으로 통용되는 운송업, ② 국제적으로 통용되는 금융업 및 보험업, ③ 무역보험법에 따른 무역보험":"적용 제한 업종은 국제적으로 통용되는 운송업과 금융 및 보험업, 무역보험으로 열거되어 있습니다.","제재는 시정조치와 과징금이다":"재판매가격유지행위에 대한 제재 수단은 형사처벌이 아니라 시정조치와 과징금입니다.","제조업, 서비스업 또는 그 밖의 사업을 하는 자":"사업자는 업종에 한정이 없어 제조업과 서비스업을 비롯해 사업을 하는 자를 폭넓게 가리킵니다.","조사 거부 사업자도 5천만원 이하":"조사를 거부한 사업자나 단체도 표지 위반과 같은 오천만 원 이하의 과태료 대상입니다.","조사계획을 수립하고, 자료제출 요구 시 자료의 범위·내용, 요구사유, 제출기한을 서면으로 밝힌다":"서면실태조사는 계획을 세우고 자료 요구 때 범위와 사유, 제출 기한을 서면으로 밝혀야 합니다.","조사 공무원은 권한을 표시하는 증표를 내보여야 한다":"조사하는 공무원은 자신의 권한을 표시하는 증표를 상대방에게 보여 주어야 합니다.","조사공무원은 이 법 시행에 필요한 최소한의 범위에서 조사하여야 하며 다른 목적 등을 위해 조사권을 남용해서는 안 된다":"조사는 이 법의 시행에 필요한 최소한의 범위에서 해야 하고 다른 목적으로 조사권을 남용하면 안 됩니다.","조사공무원은 자료나 물건의 제출을 명하거나 제출된 자료·물건을 일시 보관할 수 있다":"조사공무원은 자료를 내라고 명하는 데 그치지 않고 받은 자료를 잠시 맡아 둘 수도 있습니다.","조사공무원은 제59조의 심의·의결 절차가 진행 중이면 출입 조사나 진술청취를 해서는 안 된다":"심의와 의결이 진행 중인 사건에 대해서는 조사공무원이 출입 조사나 진술 청취를 하면 안 됩니다.","조사공무원은 지정된 장소에서 당사자 등의 진술을 들을 수 있다":"진술 청취는 지정한 장소에서 당사자 등의 이야기를 듣는 방식으로 합니다.","조사기간 내에 종료하며 필요하면 연장할 수 있고 연장 시 공문서를 발급한다":"조사는 정해진 기간 안에 끝내며 필요하면 늘릴 수 있고 이때는 공문서를 발급합니다.","조사는 정규 근무시간 내에 진행한다":"조사는 피조사업체의 정규 근무시간 안에 진행하는 것이 원칙입니다.","조사를 개시한 경우 조사 개시일부터 5년, 조사를 개시하지 않은 경우 위반행위 종료일부터 7년":"담합은 조사를 시작했다면 개시일부터 오 년, 시작하지 않았다면 종료일부터 칠 년의 시효가 적용됩니다.","조사를 개시한 경우 조사 개시일부터 5년, 조사를 개시하지 않은 경우 위반행위 종료일부터 7년이 지나면 시정조치·과징금을 부과할 수 없다":"조사를 시작했다면 개시일부터 오 년, 시작하지 않았다면 행위 종료일부터 칠 년이 지나면 부과가 불가능합니다.","조정 대상 분쟁의 당사자인 사업자는 협의회에 출석하여 의견을 진술할 수 있다":"분쟁 당사자인 사업자는 협의회에 나와 자기 의견을 말할 수 있습니다.","조정 성립 시 조정에 참가한 위원과 분쟁당사자가 기명날인하거나 서명한 조정조서를 작성한다":"약관 분쟁조정에서 합의가 이루어지면 참가 위원과 당사자가 서명하거나 날인한 조서를 만들어 둡니다.","조정신청 내용과 직접적인 이해관계가 없는 자가 신청한 경우":"신청 내용과 직접 이해관계가 없는 사람이 신청하면 협의회는 신청을 각하합니다.","조정신청을 각하하거나 절차를 종료하면 공정거래위원회에 조정의 경위, 사유 등을 서면으로 지체 없이 보고하고 분쟁당사자에게 통보한다":"각하하거나 종료하면 경위와 사유를 서면으로 공정거래위원회에 보고하고 당사자에게도 알립니다.","조정원의 분쟁조정은 제45조 제1항을 위반한 혐의가 있는 행위와 관련된 분쟁이 대상이다":"분쟁조정은 불공정거래행위를 한 혐의가 있는 행위와 관련된 분쟁을 대상으로 합니다.","조정원의 장은 공정거래위원회 위원장이 임명한다":"한국공정거래조정원의 장은 공정거래위원회 위원장이 임명합니다.","조정이 성립되면 조정에 참가한 위원과 분쟁당사자가 기명날인하거나 서명한 조정조서를 작성한다":"공정거래 분쟁조정에서 조정이 성립하면 참여한 위원과 당사자가 이름을 적고 날인한 조서로 남깁니다.","조정이 성립된 사항과 같거나 비슷한 유형의 피해가 다수 고객에게 발생할 가능성이 크다고 판단한 경우로 대통령령으로 정하는 사건":"조정 성립 사항과 비슷한 유형의 피해가 다수 고객에게 생길 가능성이 크다고 시행령이 정한 사건이 대상입니다.","조정절차 개시 전에 시정조치 등을 하지 않은 분쟁조정사항은 조정절차가 종료될 때까지 공정거래위원회가 시정조치(제49조 제1항) 및 시정권고(제88조 제1항)를 하지 못한다":"조정이 진행되는 동안에는 공정거래위원회가 같은 사항에 시정조치와 시정권고를 하지 못합니다.","조정절차 개시 전에 처분하지 않은 사항에 대해 합의가 이루어지고 이행하면 공정거래위원회는 시정조치 및 시정권고를 하지 않는다":"조정으로 합의하고 이행하면 처분하지 않은 사항에는 공정거래위원회가 시정조치와 시정권고를 하지 않습니다.","조정조서는 재판상 화해와 동일한 효력을 갖는다":"조정조서가 작성되면 법원의 재판상 화해와 같은 효력이 생겨 당사자를 구속합니다.","조합연합체도 조합에 포함된다":"조합들이 모인 연합체도 적용제외를 받는 조합의 범위에 들어갑니다.","조합원에게 이익배분을 하는 경우 그 한도가 정관에 정하여져 있을 것":"이익을 조합원에게 나누는 경우 그 한도가 정관에 정해져 있어야 합니다.","주식 소유를 통해 국내 회사의 사업내용을 지배하는 것을 주된 사업으로 하는 회사로서 자산총액이 대통령령으로 정하는 금액 이상인 회사":"지주회사는 주식을 보유해 국내 회사를 지배하는 것이 주된 사업이며 자산총액이 일정 금액 이상인 회사입니다.","주식의 처분·소각, 계약조항의 삭제, 법위반사실의 공표(조문은 시정명령을 받은 사실의 공표), 사죄광고, 이행강제금 부과, 다른 회사와의 합병, 경쟁촉진 방안 마련":"이 목록은 남용행위 시정조치 조문에 열거되지 않은 것들로 합병이나 사죄광고는 명할 수 없습니다.","주식 취득·소유, 임원겸임, 합병, 영업양수, 새로운 회사설립 참여":"기업결합의 유형은 주식 취득, 임원 겸임, 합병, 영업양수, 신설 회사 설립 참여의 다섯 가지입니다.","중단된 시효는 조정조서를 작성한 때 또는 조정이 이루어지지 않고 절차가 종료된 때부터 새로 진행한다":"중단된 시효는 조정조서를 작성한 때나 조정 없이 절차가 끝난 때부터 다시 시작합니다.","중소벤처기업부장관은 직접 검찰총장에게 고발할 수 없고 공정거래위원회에 고발을 요청할 수 있을 뿐이다":"중소벤처기업부장관은 검찰에 직접 고발할 권한이 없고 공정거래위원회에 요청만 할 수 있습니다.","중재법에 따라 중재가 진행 중이거나 신청된 사건":"중재법에 따른 중재가 진행 중이거나 신청된 사건은 조정 신청의 각하 사유입니다.","증거인멸 우려 등으로 목적 달성이 불가능하면 피조사업체와 협의해 근무시간 외에도 할 수 있다":"증거를 없앨 우려로 목적을 이룰 수 없으면 협의해 근무시간 밖에도 조사할 수 있습니다.","증거조사 신청을 채택하지 않으면 의장이 그 이유를 당사자에게 고지한다":"신청한 증거조사를 받아들이지 않을 때는 의장이 그 이유를 당사자에게 알려야 합니다.","지방자치단체의 택지공급계약서":"지방자치단체가 다수의 상대방과 맺는 택지공급계약서도 미리 마련한 형식이어서 약관입니다.","지식재산권 행사 수준이나 가격의 남용 정도는 판단 요소로 명시되어 있지 않다":"지식재산권 행사 수준과 가격 남용 정도는 법에 명시된 판단 요소가 아닙니다.","지연 손해금 등을 부담시키는 것 자체가 무효인 것은 아니다":"지연 손해금을 정하는 것 자체가 아니라 부당하게 과중한 경우에만 무효로 봅니다.","지정 당시 위반 중이면 상호출자·계열출자 위반은 1년, 채무보증은 2년간 적용하지 않는다":"지정 때 이미 위반 상태라면 상호출자와 계열출자는 일 년, 채무보증은 이 년간 적용을 유예합니다.","지주회사 설립·전환 시 위 금지 행위에는 설립·전환일부터 2년의 유예기간이 있다":"지주회사로 설립하거나 전환한 날부터 이 년간은 위 행위 제한을 지키지 않아도 됩니다.","지주회사 설립·전환 신고 미이행·허위, 지주회사 사업내용 보고서 미제출, 주식소유·채무보증 현황 신고 미이행·허위, 거짓 감정":"지주회사 설립 신고나 보고서 제출, 주식소유와 채무보증 현황 신고를 하지 않거나 거짓으로 하면 일억 원 이하 벌금입니다.","지침을 제정하려면 관계 행정기관의 장의 의견을 들어야 한다":"지침을 만들기 전에 관계 행정기관의 장의 의견을 먼저 들어야 합니다.","직권조사는 처분·조사를 한 날 중 가장 빠른 날, 신고(자진신고 포함)로 개시하면 신고 접수일":"조사 개시일은 직권 조사라면 처분이나 조사를 한 날 가운데 가장 빠른 날이고 신고로 개시하면 접수일입니다.","직권 조사 또는 신고로 조사한 결과 처분을 하거나 하지 않는 경우 그 근거·내용·사유 등을 기재한 서면(의결서를 작성하면 의결서 정본)을 당사자에게 통지하여야 한다":"조사 결과 처분을 하든 하지 않든 근거와 사유를 적은 서면을 당사자에게 통지해야 합니다.","직전 3개 사업연도 연속 당기순손실 여부, 자본총액의 2배 초과 부채 보유 여부, 그 밖에 고시하는 사항":"자금사정이 어려운지 판단할 때 연속 순손실과 부채 비율과 고시 사항을 살핍니다.","직접 거래하면 상당히 유리한데도 ① 거래상 역할이 없거나 미미한 특수관계인·다른 회사를 거래단계에 추가하거나 거쳐 거래하는 행위, ② 거래단계에 추가하거나 거쳐 거래하면서 거래상 역할에 비해 과도한 대가를 지급하는 행위":"직접 거래가 더 유리한데 역할 없는 회사를 거래단계에 끼우거나 역할에 비해 과도한 대가를 주는 행위입니다.","직접적이고 상당하며 합리적으로 예측 가능한 영향으로 제한 해석한다":"국내에 미치는 영향은 직접적이고 상당하며 예측 가능한 정도로 좁게 해석합니다.","집단분쟁조정 당사자인 다수 고객 중 일부가 법원에 소를 제기하면 절차를 중지하지 않고 소를 제기한 일부 고객을 절차에서 제외한다":"당사자 중 일부가 소를 내면 절차를 멈추지 않고 그 고객만 집단분쟁조정에서 뺀 채 계속 진행합니다.","집단분쟁조정의 기간은 공고가 종료된 날의 다음 날부터 기산한다 (공고 종료일 당일이 아니다)":"조정 기간은 공고가 끝난 날의 다음 날부터 세며 종료일 당일부터가 아닙니다.","집단으로 특정사업자를 부당하게 차별적으로 취급하여 그 사업활동을 현저하게 유리하거나 불리하게 하는 행위":"여럿이 함께 특정 사업자를 차별해 사업활동을 현저히 유리하거나 불리하게 만드는 집단적 차별입니다.","징수금등의 징수권에 대한 소멸시효가 완성된 경우":"징수권의 소멸시효가 완성되어 더 이상 걷을 수 없게 된 때도 결손처분 사유입니다.","징수·체납처분 업무는 국세청장에게 위탁할 수 있다":"과징금을 걷고 체납자에게 강제 징수하는 실무는 세금 징수 전문 기관인 국세청장에게 맡길 수 있습니다.","징수할 가능성이 없는 경우로서 대통령령으로 정하는 사유":"그 밖에 징수할 가능성이 없다고 시행령이 정한 사유가 있으면 결손처분을 할 수 있습니다.","징역형과 벌금형은 병과할 수 있다":"해당 범죄에 대해서는 징역과 벌금을 함께 선고하는 병과가 가능합니다.","징역형과 벌금형을 병과할 수 있다":"징역과 벌금을 함께 선고하는 병과도 가능합니다.","채무자회생법 제215조에 따라 새로운 회사를 설립하는 경우 기존 회사 또는 새로운 회사 중 어느 하나의 행위로 보고 과징금을 부과·징수할 수 있다":"회생 절차로 새 회사를 세운 경우에도 기존 회사나 새 회사의 행위로 보아 과징금을 부과할 수 있습니다.","채무자회생법 제215조에 따라 새로운 회사를 설립하는 경우 기존 회사 또는 새로운 회사 중 어느 하나의 행위로 보고 시정조치를 명할 수 있다":"회생 절차에서 새 회사를 세운 경우에도 기존 회사나 새 회사 중 하나의 행위로 보아 시정조치를 명할 수 있습니다.","처분의 통지를 받은 날 또는 이의신청에 대한 재결서 정본을 송달받은 날부터 30일 이내에 제기":"불복의 소는 처분을 통지받거나 재결서 정본을 송달받은 날부터 삼십 일 안에 내야 합니다.","처분의 통지를 받은 날부터 30일 이내에 그 사유를 갖추어 공정거래위원회에 한다":"이의신청은 처분 통지를 받은 날로부터 삼십 일 안에 사유를 갖춰 공정거래위원회에 합니다.","천재지변이나 그 밖에 대통령령으로 정하는 사유(예: 인수·합병 절차 진행)로 처분 이행이나 조사를 받기 곤란하면 연기를 신청할 수 있다":"천재지변이나 인수합병 진행 같은 사유로 조사를 받기 곤란하면 연기를 신청할 수 있습니다.","첨부: 원인과 사실 증명서류, 위임장, 증거서류":"신청서에는 원인과 사실을 증명하는 서류와 위임장, 증거서류를 첨부합니다.","청구인 성명·주소, 사업자 성명(상호)·주소, 심사청구의 취지와 이유":"청구서에는 청구인과 사업자의 인적 사항, 심사청구의 취지와 이유를 적습니다.","체납된 과징금 징수를 위해 필요하다고 인정하면 국세청장에게 체납자의 국세과세정보 제공을 요청할 수 있다(요청하여야 하는 것이 아니다)":"체납 과징금을 징수하기 위해 필요하면 국세청장에게 체납자 과세정보를 요청할 수 있고 요청이 의무는 아닙니다.","체납자의 행방이 분명하지 않거나 재산이 없다는 것이 판명된 경우":"체납자가 어디 있는지 알 수 없거나 재산이 없다고 확인된 때도 결손처분 사유입니다.","체납처분 목적물인 총재산의 추산가액이 체납처분비에 충당하고 남을 여지가 없음이 확인된 경우":"체납자의 총재산 추산가액이 체납처분비를 갚고 나면 남지 않는 것이 확인되면 결손처분을 합니다.","체납처분이 끝나고 체납액에 충당된 배분금액이 체납액에 미치지 못하는 경우":"체납처분을 모두 했는데도 거둔 금액이 체납액에 모자라는 경우가 결손처분 사유의 하나입니다.","총재산이 징수금등보다 우선하는 국세·지방세·전세권·질권·저당권 담보채권 등의 변제에 충당하고 남을 여지가 없음이 확인된 경우":"총재산이 우선하는 세금과 담보채권을 갚으면 남을 것이 없다고 확인될 때도 결손처분 사유입니다.","최고가격유지행위는 정당한 이유가 있으면 허용된다":"가격의 상한을 정해 두는 행위도 정당한 이유가 있다면 허용됩니다.","최저재판매가격 유지행위도 정당한 이유가 있으면 허용되므로 이유의 존재 여부와 상관없이 금지되는 것은 아니다":"최저가격을 지키게 하는 행위도 정당한 이유가 있으면 허용되어 당연히 금지되는 것은 아닙니다.","최초 자진신고자 협조일부터 2년 이내여야 한다":"두 번째 신고나 협조는 최초 자진신고자가 협조한 날부터 이 년 안에 이루어져야 합니다.","추정되는 자는 A, B, C, E":"A는 절반 이상이고 합계 요건에서도 B와 E, C가 포함되어 이 네 곳이 추정 대상입니다.","추정할 때도 해당 사업자와 그 계열회사를 하나의 사업자로 본다":"시장지배적사업자로 추정할 때에도 계열회사를 하나로 묶어 점유율을 합산합니다.","출석 요구는 출석 지정일 7일 전까지 알린다":"당사자에게 출석을 요구할 때는 출석일 칠 일 전까지 그 사실을 알려야 합니다.","출석요구서에는 사건명, 출석하는 자의 성명, 출석일시·장소를 적어 발부한다":"출석요구서에는 사건명과 출석자, 출석 일시와 장소를 적어 발부합니다.","취소신청에 대한 재판에 대해서도 즉시항고를 할 수 있고, 취소 재판은 확정되어야 효력이 발생한다":"취소신청 재판에도 즉시항고가 가능하며 취소 재판은 확정되어야 효력이 생깁니다.","취하·각하된 경우 6개월 내에 재판상 청구, 파산절차 참가, 압류·가압류, 가처분을 하면 시효는 최초의 분쟁조정 신청으로 중단된 것으로 본다":"취하나 각하 후 육 개월 안에 소송 등을 하면 처음 분쟁조정을 신청한 때 시효가 중단된 것으로 봅니다.","친목, 종교, 학술, 조사, 연구, 사회활동만을 목적으로 하는 단체는 사업자단체에 해당하지 않는다":"경제적 이익과 무관하게 친목이나 학술 같은 활동만 하는 단체는 사업자단체가 아닙니다.","통상 수준을 현저히 벗어나 가격의 인상·하락 방지에 중대한 영향을 미치거나 수급차질을 초래할 우려가 있는지로 판단한다":"공급 감소가 통상 수준을 크게 벗어나 가격이나 수급에 중대한 영향을 줄 우려가 있는지로 부당성을 가립니다.","통지받은 당사자는 회의에 출석해 의견을 진술하거나 자료를 제출할 수 있다":"통지를 받은 당사자는 회의에 나와 의견을 말하거나 자료를 낼 수 있습니다.","특수관계인(동일인 및 그 친족으로 한정)":"이익 제공 대상인 특수관계인은 동일인과 그 친족으로 한정됩니다.","특수관계인과 현금이나 그 밖의 금융상품을 상당히 유리한 조건으로 거래하는 행위":"현금이나 금융상품을 특수관계인과 상당히 유리한 조건으로 거래하는 것도 금지됩니다.","특수관계인 또는 다른 회사에 가지급금·대여금 등 자금을 상당히 낮거나 높은 대가로 제공·거래하거나 상당한 규모로 제공·거래":"자금을 상당히 낮거나 높은 대가로, 또는 상당한 규모로 특수관계인 등에게 제공하는 부당한 자금지원입니다.","특수관계인 또는 회사는 제9호에 해당할 우려가 있음에도 해당 지원을 받는 행위를 해서는 안 된다":"지원받는 쪽도 부당한 지원행위에 해당할 우려가 있음에도 지원을 받아서는 안 됩니다.","특수관계인에 대한 부당한 이익제공행위의 중지 및 재발방지를 위한 조치, 계약조항의 삭제, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치":"시정조치는 이익제공 행위의 중지와 재발 방지, 계약조항 삭제, 시정명령 사실 공표 등을 포함합니다.","특수관계인은 누구에게든지 제1항·제3항 행위를 하도록 지시하거나 해당 행위에 관여해서는 안 된다":"특수관계인은 이러한 부당 이익 제공을 지시하거나 관여하는 것도 금지됩니다.","특정한 거래 분야의 약관에 대해 다른 법률에 특별한 규정이 있으면 그 법률을 우선 적용하고, 없는 경우에 이 법에 따른다":"다른 법률에 특별한 규정이 있으면 그것을 우선하고 없을 때 약관법을 적용합니다.","판매업자에게 안정적 이윤을 보장해 유통경로 확보와 시장지배력 확대에 도움이 될 수 있다":"판매업자의 이윤이 보장되므로 제조사가 유통경로를 확보하고 시장지배력을 넓히는 데 이용할 수 있습니다.","평균매출액 100분의 10, 매출액 없으면 40억원":"부당한 지원행위와 지원받는 행위, 사익편취는 평균매출액의 백분의 십 또는 사십억 원이 상한입니다.","평균적 고객의 이해가능성을 기준으로 해석한다":"약관의 뜻은 평균적인 고객이 이해할 수 있는 의미를 기준으로 정합니다.","표시광고법상 부당한 표시·광고 외의 방법으로 자기 상품·용역의 내용이나 거래조건 등을 실제보다 또는 경쟁사업자의 것보다 현저히 우량·유리한 것으로 또는 경쟁사업자의 것을 현저히 불량·불리한 것으로 고객이 잘못 알게 하여 유인":"자기 상품을 실제보다 낫게, 경쟁사의 것을 더 나쁘게 오인시켜 고객을 끌어오는 위계에 의한 고객유인입니다.","표준약관과 다른 내용을 약관으로 사용하는 경우 표준약관 표지를 사용해서는 안 된다":"표준약관과 다른 내용을 쓰면서 표지를 붙이면 오인을 줄 수 있어 표지 사용이 금지됩니다.","표준약관 사용 사업자에게 운용 상황 제출을 하게 할 수 있다":"표준약관을 사용하는 사업자에게는 표준약관을 어떻게 운용하는지 그 상황을 제출하게 할 수 있습니다.","표준약관 사용을 권장받은 사업자·사업자단체가 표준약관과 다른 약관을 사용하면 다르게 정한 주요 내용을 고객이 알기 쉽게 표시하여야 한다":"표준약관과 다르게 정했다면 다른 주요 내용을 고객이 알기 쉽게 표시해야 합니다.","표준약관 심사청구를 받으면 공정거래위원회는 받은 날부터 60일 이내에 심사결과를 신청인에게 알려야 한다(90일이 아니다)":"표준약관 심사청구 결과는 받은 날부터 육십 일 안에 알려야 하며 구십 일이 아닙니다.","표준약관 표지를 사용하면서 표준약관과 다른 내용을 약관으로 사용하는 경우, 표준약관보다 고객에게 더 불리한 약관 내용은 무효다":"표준약관 표지를 쓰면서 표준약관보다 고객에게 불리한 내용을 쓰면 그 부분이 무효입니다.","표준약관 표지 위반(5천만원 이하)":"약관법의 과태료 중 가장 큰 금액은 표준약관 표지 위반에 대한 오천만 원 이하입니다.","표준화·체계화된 용어를 사용하여야 한다":"약관에는 표준화되고 체계화된 용어를 써야 고객이 이해하기 쉽습니다.","품질·기술향상 등 생산성 향상이나 교섭력 강화가 명백할 것, 참가사업자 모두가 중소기업자일 것, 공동행위 외의 방법으로는 대기업과 효율적으로 경쟁하거나 대항하기 어려울 것":"중소기업 경쟁력 인가는 생산성이나 교섭력 향상이 명백하고 참가자가 모두 중소기업이며 다른 방법이 어려워야 합니다.","필수시설(전사적 자원관리시스템, 공장, 연구개발시설, 통신기반시설) 구축·운영·핵심기술 연구·개발·보유 관련, 영업·판매·구매 기밀이나 고객 개인정보 등 핵심 경영정보에 접근 가능한 경우로서 유출 시 회복하기 어려운 피해가 우려되는 거래":"필수시설이나 핵심기술, 핵심 경영정보를 다루어 유출 시 회복하기 어려운 피해가 우려되는 거래가 보안성 예외입니다.","필요하면 담보를 제공하게 할 수 있다":"연기나 분할납부를 허용하면서 공정거래위원회가 필요하다고 보면 담보를 내게 할 수 있습니다.","하나의 사업자의 시장점유율이 100분의 50 이상":"한 사업자의 점유율이 절반 이상이면 시장지배적사업자로 추정합니다.","한국공정거래조정원은 집단분쟁조정 대상 발굴, 조정에 의한 피해구제 사례 연구 등 활성화에 필요한 연구를 하며 결과를 인터넷 홈페이지에 공개한다":"조정원은 집단분쟁조정의 대상 발굴과 피해구제 사례 연구를 하고 결과를 홈페이지에 공개합니다.","한국공정거래조정원 인터넷 홈페이지 및 전국을 보급지역으로 하는 일간신문에 게재":"개시 공고는 조정원 홈페이지와 전국에 보급되는 일간신문에 싣는 방식으로 합니다.","한국소비자원은 규정되어 있지 않다":"집단분쟁조정을 의뢰하거나 신청할 수 있는 주체로 한국소비자원은 조문에 정해져 있지 않습니다.","합병·분할 등 승계는 제7조 제2항~제4항 준용":"회사가 합병이나 분할로 승계된 경우의 시정조치는 남용행위의 승계 규정을 준용합니다.","합병·분할 등에 따른 시정조치는 제7조 제2항~제4항을 준용한다('시장지배적사업자'는 '사업자단체'로 본다)":"합병이나 분할이 있어도 시정조치를 승계시키는 남용행위 규정을 사업자단체에 맞게 준용합니다.","합병·분할·포괄적 교환·이전·영업 전부 양수와 담보권 실행·대물변제는 6개월, 신주배정 등으로 지분율 초과분 생긴 경우 1년, 기업구조조정 촉진법 관련은 3년":"순환출자 예외 사유별로 처분 기간이 육 개월, 일 년, 삼 년으로 달리 주어집니다.","합병으로 소멸한 회사의 위반행위는 합병 후 존속하거나 합병으로 설립된 회사의 행위로 보아 과징금을 부과·징수할 수 있다":"합병으로 없어진 회사의 위반은 존속회사나 신설회사의 행위로 보아 과징금을 부과할 수 있습니다.","합의는 공급자 사이, 수요자 사이, 공급자와 수요자 사이에서도 성립할 수 있다":"합의 당사자는 같은 편 사업자들에 한하지 않고 공급자와 수요자 사이에서도 가능합니다.","합의는 해당 거래분야나 특정 입찰의 모든 사업자 사이에서 이루어질 필요가 없다":"시장이나 입찰 참가자 전부가 합의에 참여해야 하는 것은 아닙니다.","합의에는 명시적 합의뿐 아니라 암묵의 요해(묵시적 합의)도 포함된다":"서로 말없이 뜻이 통해 묵시적으로 이해한 경우에도 합의가 성립합니다.","합의에 따른 행위의 일치(실행)는 요건이 아니다":"합의한 대로 실제로 행동했는지는 요건이 아니어서 합의만으로 성립합니다.","항변권·상계권 = 상당한 이유 없이, 기한의 이익 박탈 = 상당한 이유 없이, 제3자와의 계약 제한 = 부당하게, 고객 비밀 누설 = 정당한 이유 없이":"조항마다 수식어가 달라 항변권과 기한 박탈은 상당한 이유, 계약 제한은 부당하게, 비밀 누설은 정당한 이유를 씁니다.","해당 거래분야, 상품·용역의 특성, 행위의 경제적 이유와 파급효과, 사업자 간 접촉의 횟수·양태 등을 보아 사업자들이 공동으로 한 것으로 볼 수 있는 상당한 개연성이 있는 때":"거래분야와 접촉 횟수 등을 종합할 때 사업자들이 공동으로 했을 상당한 개연성이 있으면 합의로 추정합니다.","해당 기업결합 외의 방법으로는 달성하기 어려운 효율성 증대효과가 경쟁제한 폐해보다 큰 경우, 회생이 불가능한 회사와의 기업결합":"다른 방법으로는 어려운 효율성 증대가 폐해보다 크거나 회생 불가능한 회사와의 결합이면 예외입니다.","해당 불공정거래행위의 중지 및 재발방지를 위한 조치, 보복조치 금지, 계약조항의 삭제, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치":"불공정거래행위의 시정조치에는 중지와 재발방지, 보복조치 금지, 계약조항 삭제, 시정명령 사실 공표가 있습니다.","해당 사업자단체(필요한 경우 관련 구성사업자 포함)에 해당 행위의 중지, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치를 명할 수 있다":"사업자단체와 필요하면 관련 구성사업자에게 행위 중지와 시정명령 사실 공표 등을 명할 수 있습니다.","해당 사업자의 직전 3개 사업연도 평균 매출액이다":"지원행위 등의 매출액은 직전 세 사업연도의 평균 매출액을 기준으로 합니다.","해당 산업 내 상당수 기업이 불황으로 사업활동에 곤란을 겪을 우려, 공급능력 현저 과잉 또는 생산시설·방법 낙후로 생산능률·국제경쟁력 현저 저하, 기업 합리화로는 극복 불가, 경쟁제한 효과보다 구조조정 효과가 클 것":"산업구조조정 인가는 불황 우려와 공급 과잉이나 낙후, 합리화로 극복 불가, 구조조정 효과가 클 것을 모두 갖춰야 합니다.","해당 연도 거래총액이 200억원 미만이고 거래상대방 평균매출액의 100분의 12 미만이면 상당한 규모가 아니다":"거래총액이 이백억 원 미만이고 상대방 평균매출액의 백분의 십이 미만이면 상당한 규모로 보지 않습니다.","해당 행위의 중지, 시정명령을 받은 사실의 공표, 그 밖에 필요한 시정조치":"담합에 대한 시정조치는 행위 중지와 시정명령 사실 공표 등이며 가격 인하 명령은 명시되지 않습니다.","해당 행위의 중지, 주식 처분, 임원 사임, 영업 양도, 시정명령을 받은 사실의 공표, 영업방식·범위 제한, 그 밖에 필요한 조치":"기업결합 시정조치로는 행위 중지와 주식 처분, 임원 사임, 영업 양도, 영업방식 제한 등이 있습니다.","해제·해지로 인한 사업자의 원상회복의무나 손해배상의무를 부당하게 경감하는 조항":"해제나 해지로 생기는 사업자의 원상회복이나 배상 의무를 부당하게 덜어 주는 조항은 무효입니다.","해제·해지로 인한 원상회복의무를 상당한 이유 없이 고객에게 과중하게 부담시키거나 고객의 원상회복 청구권을 부당하게 포기하도록 하는 조항":"해제나 해지 때 고객에게 원상회복 부담을 과중하게 지우거나 고객의 청구권을 포기하게 하는 조항은 무효입니다.","행정관청이 다른 법률에 따라 약관을 인가하거나 특정 거래 분야에 설치된 심사기구에서 약관을 심사할 때는 제6조~제14조를 인가·심사 기준으로 하여야 한다":"다른 법률에 따라 약관을 인가하거나 심사하는 기관도 불공정 약관 조항 규정을 기준으로 삼아야 합니다.","허용하여야 하는 것이 아니다":"요건을 갖추었더라도 공정거래위원회가 반드시 연기나 분할납부를 허용해야 하는 것은 아닙니다.","현재 기준은 제45조 제1항 제9호(부당한 지원행위) 위반 혐의 행위":"현재 시행령이 정한 그 기준은 부당한 지원행위의 위반 혐의가 있는 행위입니다.","현행 80억원 기준이면 B도 빠진다":"기준이 팔십억 원이면 오십억 원인 B도 매출 요건에서 제외되어 추정 대상이 줄어듭니다.","현행 제46조에는 지정상품 제도가 없다":"현재의 재판매가격유지 조문에는 지정상품을 허용하는 제도가 남아 있지 않습니다.","협의회는 분쟁당사자에게 스스로 조정하도록 권고하거나 조정안을 작성해 제시할 수 있다":"협의회는 당사자에게 스스로 조정하도록 권하거나 조정안을 만들어 보여 줄 수 있습니다.","협의회는 분쟁당사자에게 스스로 합의하도록 권고하거나 조정안을 작성하여 제시할 수 있다":"협의회는 당사자에게 합의를 권하거나 직접 조정안을 만들어 제시할 수 있습니다.","협의회는 사실 확인을 위해 조사를 하거나 분쟁당사자에게 자료 제출이나 출석을 요구할 수 있다":"약관 분쟁조정에서도 협의회는 사실을 확인하려고 조사하고 당사자에게 자료나 출석을 요구할 수 있습니다.","협의회는 사실 확인을 위해 필요하면 조사를 하거나 분쟁당사자에게 자료 제출이나 출석을 요구할 수 있다":"사실을 확인하기 위해 협의회는 조사를 하고 당사자에게 자료 제출과 출석을 요구할 수 있습니다.","협의회는 신청서를 접수하거나 의뢰받으면 즉시 분쟁당사자에게 통지하여야 한다":"신청서를 받거나 의뢰를 받으면 협의회는 곧바로 분쟁 당사자에게 알려야 합니다.","협의회는 신청·의뢰를 받으면 즉시 접수사실 등을 공정거래위원회 및 분쟁당사자에게 통지하여야 한다":"신청이나 의뢰를 받으면 협의회는 바로 공정거래위원회와 분쟁 당사자에게 접수 사실을 알려야 합니다.","협의회는 신청의 보완이 필요하면 상당한 기간을 정해 요구할 수 있다":"신청서에 부족한 부분이 있으면 협의회가 상당한 기간을 정해 보완하라고 요구할 수 있습니다.","협의회는 위원장 1명을 포함하여 9명 이내의 위원으로 구성한다":"협의회는 위원장을 포함하여 아홉 명 이내의 위원으로 꾸립니다.","협의회는 의결로 집단분쟁조정 절차를 개시할 수 있고, 분쟁조정된 사안 중 집단분쟁조정 신청에 필요한 사항을 공표하고 일정 기간 개시를 공고하여야 한다":"협의회는 의결로 집단분쟁조정을 시작하고 신청에 필요한 사항을 공표하며 일정 기간 개시 사실을 공고합니다.","협의회는 재적위원 과반수의 출석으로 개의하고 출석위원 과반수의 찬성으로 의결한다":"협의회는 재적위원 과반수가 출석해야 회의를 열고 출석위원 과반수가 찬성하면 의결합니다.","협의회는 조정이 성립되면 공정거래위원회에 조정결과를 보고한다":"조정이 성립되면 협의회는 그 결과를 공정거래위원회에 보고합니다.","협의회는 집단분쟁조정의 당사자가 아닌 고객으로부터 당사자에 추가로 포함될 수 있도록 하는 신청을 받을 수 있다":"당사자가 아닌 다른 피해 고객도 추가로 당사자가 되게 해 달라고 협의회에 신청할 수 있습니다.","협의회는 협의회의 의결로써 당사자 중에서 공동의 이익을 대표하기에 가장 적합한 1인 또는 수인을 대표당사자로 선임할 수 있다(위원장이 선임하는 것이 아니다)":"대표당사자는 위원장이 아니라 협의회의 의결로 당사자 가운데서 공동 이익을 대표하기에 적합한 사람을 뽑습니다.","협의회 위원장은 직무 외에 영리를 목적으로 하는 업무에 종사하지 못한다":"협의회 위원장은 직무 외에 돈을 버는 영리 업무에는 종사할 수 없습니다.","협정이 없어도 외국정부의 법집행 요청 시 동일하거나 유사한 사항에 관해 대한민국의 지원요청에 따른다는 요청국의 보증이 있으면 지원할 수 있다":"협정이 없어도 우리 요청에도 응하겠다는 요청국의 보증이 있으면 외국의 법집행을 지원할 수 있습니다.","형태가 무엇이든 상관없이 둘 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 그 연합체":"사업자단체는 이름이나 형태를 묻지 않고 둘 이상의 사업자가 공동 이익을 위해 만든 모임입니다.","형태가 무엇이든 상관없이 둘 이상의 사업자가 공동의 이익을 증진할 목적으로 조직한 결합체 또는 연합체":"사업자단체는 이름과 형식에 관계없이 둘 이상의 사업자가 공동 이익을 위해 조직한 모임입니다.","회사가 사업기회를 수행할 능력이 없는 경우, 정당한 대가를 지급받은 경우, 합리적 사유로 거부한 경우":"사업기회를 감당할 능력이 없거나 정당한 대가를 받았거나 합리적 사유로 거부했다면 규제 대상에서 제외됩니다.","회사가 직접 또는 자신이 지배하는 회사를 통해 수행하면 회사에 상당한 이익이 될 사업기회를 제공하는 행위":"회사가 직접 했다면 상당한 이익이 되었을 사업기회를 특수관계인에게 넘기는 행위입니다.","회의는 개최 7일 전까지 일시·장소·안건을 서면으로 알려 소집한다":"회의는 열리기 칠 일 전까지 일시와 장소와 안건을 서면으로 알려 소집합니다.","회의는 공개하지 않으며 위원장이 필요하다고 인정하면 분쟁당사자 등이 방청하게 할 수 있다":"회의는 비공개이고 위원장이 필요하다고 인정할 때 당사자 등이 방청할 수 있습니다.","회의는 비공개이나 위원장이 필요하다고 인정하면 분쟁당사자·이해관계인에게 공개할 수 있다":"원칙은 닫힌 회의이지만 위원장 판단에 따라 분쟁 당사자나 이해관계인이 들어오게 할 수도 있습니다.","회의 소집은 개최 7일 전까지 일시·장소·안건을 서면으로 알린다(긴급·부득이한 경우 예외)":"회의는 열리기 칠 일 전까지 일시와 장소와 안건을 서면으로 알리며 긴급한 경우는 예외입니다.","효율성 증대로 인한 소비자후생 증대효과가 경쟁제한으로 인한 폐해보다 큰 경우 등 정당한 이유가 있는 경우":"효율성 증대로 소비자후생이 늘어나는 효과가 경쟁제한 폐해보다 크면 정당한 이유로 인정합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
